const view7 = (o) => (o.crash ? `例外 ${o.crash}` : o.refused ? `断り ${o.refused}` : `${o.text} : ${o.kind}`);

law("7 左からの畳み込み：カリー化・関数の並びを括る・余りを積むは、括りを開いた綴りと同じ", () => {
	const problems = [];
	const count = {
		"(a) カリー化": 0,
		"(b) 関数の並びを括る": 0,
		"(c) 余りを積む": 0,
		通る: 0,
		断る: 0,
		余りのある組: 0,
	};
	const pair = (name, left, right) => {
		count[name]++;
		const l = opened([left]);
		const r = opened([right]);
		if (l.crash || r.crash || view7(l) !== view7(r)) problems.push(`${name}：${left}  ⇔  ${right}`, `  左: ${view7(l)}`, `  右: ${view7(r)}`);
		if (l.refused) count.断る++;
		else count.通る++;
	};
	// (a) [頭, アリティ]
	const HEADS_A = [["add", 2], ["f2", 2], ["f3", 3], ["[<<]", 2], ["pt", 2], ["pr", 2]];
	const ARGS_A = ["1", "2", "3", "[4]", "5"];
	for (const [h, n] of HEADS_A) {
		for (let k = n; k <= n + 2; k++) {
			const xs = ARGS_A.slice(0, k);
			if (k > n) count.余りのある組++;
			for (let cut = 1; cut < n; cut++) pair("(a) カリー化", `(${h} ${xs.slice(0, cut).join(" ")}) ${xs.slice(cut).join(" ")}`, `${h} ${xs.join(" ")}`);
		}
	}
	// (b) [F, X の並び]
	const FS_B = ["f2 3 f2", "inc add", "inc f2", "f2 1 g", "add inc 1 double", "inc inc", "[<<] 5 g", "pair [1] inc", "inc (f3 1)", "double inc", "inc [+]", "inc uu", "use 5 inc"];
	const XS_B = ["5", "5 6", "5 6 7"];
	for (const f of FS_B) for (const x of XS_B) pair("(b) 関数の並びを括る", `[${f}] ${x}`, `${f} ${x}`);
	// (c) [頭, アリティ]（本体の根が A の物だけ）
	const HEADS_C = [["inc", 1], ["add", 2], ["f3", 3], ["[+ 1]", 1], ["[-_]", 1], ["[<<]", 2], ["pt", 2], ["(pr 1)", 1], ["[add !_ 10]", 1], ["inc inc", 1], ["inc f2", 2]];
	for (const [h, n] of HEADS_C) {
		for (let extra = 1; extra <= 2; extra++) {
			const xs = ARGS_A.slice(0, n + extra);
			count.余りのある組++;
			pair("(c) 余りを積む", `${h} ${xs.join(" ")}`, `[${h} ${xs.slice(0, n).join(" ")}] ${xs.slice(n).join(" ")}`);
		}
	}
	// (d)（一番近い1項の逆適用）は、2026-10-24 の逆適用の廃止（R47）で外した（上の注）。
	// 断る組（HEAD で 4）は、片イ（2026-11-02）で門が廃止されて 0 になった（R120・R125）。数えるだけで、無くても落とさない。
	for (const [k, v] of Object.entries(count)) if (!v && k !== "断る") problems.push(`「${k}」の組が無い（法則がその枝を見ていない）`);
	return { problems, note: Object.entries(count).map(([k, v]) => `${k} ${v}`).join("・") };
});

// ---------------------------------------------------------------------------
// 法則8：既定値のある口に書いた `_` は、同じ口に数を書いたのと同じ種類（R39、2026-10-22）
// ---------------------------------------------------------------------------
//
// 比べる綴り：既定値のある関数 h の実引数の並びで、既定値のある口に書いた `_` と、同じ口に数 5 を書いた物。
//
// なぜ同じか：既定値は口の上の値で、計算で来た `_` も既定値に落ちる（U〔答え〕10-21 23:42「そうなるね。」。主の Claude の問いは
// 「既定値は口の上の Maybe の代数（`x | a0`）で、計算で来た `_` も既定値に落ちる、でいい？」）。口は書いた `_` とほかの値を見分けない
// ので、`_` の口は既定値という値で、その口に別の値を書いたときと同じ種類でなければならない（R39）。
//
// 何を同じと見るか：全部の行の種類、断るなら門（reason と番号）、最後の行の木（`_` の葉を 5 に読み替えた綴り）。呼ぶ形は、根・値の
// 定義を通す・合成の最初の関数・構築の後ろ・括りに包んで後ろに関数（`[h a] inc`。2026-10-23 までは逆適用、R47 から inc は閉じた値の
// 後ろに積まれて余る）・穴 `!_` と混ぜる。
//
// 2026-10-26 の R68（§5 Q8 の答え）から、既定値の無い口に当たる内側の `_` はカリー化で、同じ口の `!_` の穴と同じ答え（下の注）。→ 2026-10-28 の R105 で R68 は
// 廃止：既定値の無い口の `_` は単位律で消える（口を使わない）ので、その `_` を外した並びと同じ答えで比べる。評価する所（根）で既定値の口だけが開けば R107 で既定値で
// 埋まるので、`_` を外した並びにも同じく埋まる（両側に同じ読みが乗る）。
// 既定値の無い口に当たる最後の項の `_`・仮引数の外に当たる末尾の `_` は、R68 の片までは比べの外（今のまま G15）で、G15 で断ることだけを見ていた。2026-10-26 の
// R28 の書き直し（末尾の書いた `_` は消える。既定値の無い口・仮引数の外でも）から、その `_` を外した並びと同じ答え（法則30 と同じ比べ）。
// 2026-11-04 の寄せ2（R131：仮引数の括りに既定値は書けない）で、gf・gb・gm の定義を仮引数のブロックへ書き換えた（前は括りの既定値 `gf : [x : 1] y ? y`・
// `gb : [x : 1] [y : 2] ? x`・`gm : x [y : 2] [z : 3] ? x`）。口の並びと口ごとの既定値の有無（HEADS8）は同じで、使う所の綴りも変えない。
const DEFS8 = [
	INC, "gd :", "\t\tys", "\t\tzs : 3", "\t? ys", "", "gf :", "\t\tx : 1", "\t\ty", "\t? y", "", "gb :", "\t\tx : 1", "\t\ty : 2", "\t? x", "",
	"gm :", "\t\tx", "\t\ty : 2", "\t\tz : 3", "\t? x", "",
];
// [頭, 口ごとの既定値の有無]（試験の側で、定義から数える）
const HEADS8 = [
	["gd", [false, true]],
	["gf", [true, false]],
	["gb", [true, true]],
	["gm", [false, true, true]],
];
const FORMS8 = [
	["根", (h, a) => [`${h} ${a}`]],
	["値の定義を通す", (h, a) => [`v : ${h} ${a}`, "v"]],
	["合成の最初の関数", (h, a) => [`${h} inc ${a}`]],
	["構築の後ろ", (h, a) => [`1 ${h} ${a}`]],
	["括りに包んで後ろに関数（前は逆適用）", (h, a) => [`[${h} ${a}] inc`]],
];
law("8 既定値のある口に書いた _ は、同じ口に数を書いたのと同じ種類", () => {
	const problems = [];
	const count = { 通る: 0, 断る: 0, "穴と混ぜた": 0, "既定値の無い口の内側の _（R105 で消える、外した並びと同じ。前は R68 で `!_` と同じ）": 0, "既定値の無い口の最後・仮引数の外の末尾の _（R28 で消える、外した並びと同じ）": 0 };
	const look = (lines) => {
		try {
			const r = resolve(src([...DEFS8, ...lines]));
			const t = r.trees[r.trees.length - 1];
			return { kinds: r.trees.map((x) => kindOf(x)).join(" "), last: show(t), diag: diagKeys(r).map((k) => k.split("/")[0]).join(" ") };
		} catch (e) {
			if (!e.reason) return { crash: `${e.name}: ${e.message}` };
			return { refused: `${e.reason} ${e.gate || ""}` };
		}
	};
	// 既定値の葉 `_` を 5 に読み替える（木の綴りの中の、空白か括弧で区切られた `_` だけ。`!_`・`$p0` などは触らない）。括りの葉の中の `_`（`[gd 7 _]`）も
	// 読み替える：片イ（R120、2026-11-02）から `[gd 7 _] inc` が G7 で断らずに通り、括りの葉の綴りを比べるようになった（前は `[gd 7 5] inc` も同じ G7）。
	const asNum = (text) => text.replace(/(^|[\s([])_(?=[\s)\]]|$)/g, (m, p) => `${p}5`);
	const view = (o, asUnit) => (o.crash ? `例外 ${o.crash}` : o.refused ? `断り ${o.refused}` : `${asUnit ? asNum(o.last) : o.last} : ${o.kinds} || ${o.diag}`);
	for (const [h, slots] of HEADS8) {
		const n = slots.length;
		// 口ごとに：既定値のある口は `_` か 5、無い口は 7 か `!_`。後ろに余りを1つ足す形も。
		for (let mask = 0; mask < 1 << n; mask++) {
			for (const extra of [[], ["9"]]) {
				const unitArgs = [];
				const numArgs = [];
				let units = 0;
				let holes = 0;
				for (let i = 0; i < n; i++) {
					const on = !!(mask & (1 << i));
					if (slots[i]) {
						unitArgs.push(on ? "_" : "5");
						numArgs.push("5");
						if (on) units++;
					} else {
						unitArgs.push(on ? "!_" : "7");
						numArgs.push(on ? "!_" : "7");
						if (on) holes++;
					}
				}
				if (!units) continue;
				if (holes) count["穴と混ぜた"]++;
				const ua = [...unitArgs, ...extra].join(" ");
				const na = [...numArgs, ...extra].join(" ");
				for (const [formName, form] of FORMS8) {
					if (holes && formName !== "根") continue; // 穴は並び全体が頭の実引数の並びのときだけ（R16・R34）
					const u = look(form(h, ua));
					const m = look(form(h, na));
					const vu = view(u, true);
					const vm = view(m, false);
					if (u.crash || m.crash || vu !== vm) problems.push(`${formName}：${form(h, ua).join(" ⏎ ")}  ⇔  ${form(h, na).join(" ⏎ ")}`, `  _: ${vu}`, `  5: ${vm}`);
					if (u.refused) count.断る++;
					else count.通る++;
				}
			}
		}
		// 既定値の無い口に書いた `_`（前から i 番目）：最後の項でなければ、2026-10-26 の R68（§5 Q8 の答え：カリー化）から、同じ口に `!_` を書いた穴と同じ木と
		// 種類（素の関数の内側の `_` の R16・R38 と同じ読み。法則9 と同じ比べ）。最後の項と、仮引数の外に当たる `_`（n 番目）は、同じ日の R28 の書き直しから、
		// その `_` を外した並びと同じ答え（末尾の `_` は消える）。前は G15（R28 の終わりを既定値のある関数に当てるかが §5 Q8 の残りだった）。その前（R68 の前）は、
		// 既定値の無い口の `_` を全部 G15 で見ていた。
		for (let i = 0; i <= n; i++) {
			if (i < n && slots[i]) continue;
			const args = [...Array(i < n ? n : n + 1).keys()].map((j) => (j === i ? "_" : "5"));
			const o = look([`${h} ${args.join(" ")}`]);
			// 2026-10-28 の R105 から、既定値の無い口の内側の `_` も単位律で消える（口を使わない）ので、その `_` を外した並びと同じ答え（前は R68 で `!_` の穴と同じ）。
			if (i < n - 1) {
				count["既定値の無い口の内側の _（R105 で消える、外した並びと同じ。前は R68 で `!_` と同じ）"]++;
				const p = look([`${h} ${args.filter((a, j) => j !== i).join(" ")}`]);
				if (view(o, false) !== view(p, false)) problems.push(`${h} ${args.join(" ")}：既定値の無い口の内側の \`_\` が消えていない（${view(o, false)}  ⇔  外した ${view(p, false)}）`);
				continue;
			}
			count["既定値の無い口の最後・仮引数の外の末尾の _（R28 で消える、外した並びと同じ）"]++;
			const p = look([`${h} ${args.slice(0, -1).join(" ")}`]);
			if (view(o, false) !== view(p, false)) problems.push(`${h} ${args.join(" ")}：既定値の無い口・仮引数の外の末尾の \`_\` が消えていない（${view(o, false)}  ⇔  外した ${view(p, false)}）`);
		}
	}
	// 「断る」は片イ（R126、2026-11-03）で G15 を外してから 0（前は位置の数えられない `_` などで断っていた）。どちらの側も断らないことは上の比べが見るので、
	// 組が無いことを問題にしない。
	for (const [k, v] of Object.entries(count)) if (!v && k !== "断る") problems.push(`「${k}」の組が無い（法則がその枝を見ていない）`);
	return { problems, note: Object.entries(count).map(([k, v]) => `${k} ${v}`).join("・") };
});

// ---------------------------------------------------------------------------
// 法則9：既定値の無い素の関数の内側の `_` は、`_` を外した並びと同じ木（R105、2026-10-28。前は R38 で `!_` と同じ木、2026-10-22）
// ---------------------------------------------------------------------------
//
// 2026-10-28 の R105（値の口の書いた `_` は単位律 `f _ = f` で消えて口を使わない）で R38（内側の `_` は k ≠ n でも `!_` と同じ穴）は廃止した。根拠：主の Claude の問い
// 「値の口の書いた `_` も単位律で消える（穴は `!_` だけ）を、片9 の初めに入れていい？」のボタンの答え U〔答え〕[2026-10-27 15:59 58a809c9]「それでいい。値の口の書いた _ も
// 単位律 f _ = f で消えて、sub _ 1 2 は -1。書いた・名前・計算の _ は値の口でどれも同じ。穴は !_ だけ。mx _ 1 は mx 1。片9 の初めに入れて。」（ボタンの文は主の Claude の物）。
// 前の法則は、穴の位置に書いた `_` と `!_` と交互の3つの綴りが同じ木かを見ていた（k = n の撒く項と、前から n 個の外だけの穴は比べの外）。
//
// 比べる綴り：素の関数 h の実引数の並び（k は n − 1 から n + 2 まで、撒く項の位置も回す）の、位置の部分集合に書いた `_`（全部 `_` と、`_` と `!_` の交互）と、その `_` を
// 外した並び（`!_` は外さない）。
// 何を同じと見るか：最後の行の木・種類、断るなら門（reason と番号）。期待値は書かない。
// なぜ同じか：値の口の `_` は口を使わないので、書かなかった並びと同じ。口が閉じた後ろの `_` も値の隣で消える（R43・R89）。包み方と頭の種類を広く見るのは法則39。
const DEFS9 = [INC, "add : x y ? x + y", "f2 : x y ? x - y", "f3 : a b c ? a + b + c", "f4 : a b c e ? a + b + c + e", "use : f x ? @f x", "uu : x ? [,] x", "vs : 1 , 2 , 3"];
const HEADS9 = [["inc", 1], ["add", 2], ["f2", 2], ["f3", 3], ["f4", 4], ["use", 2], ["uu", 1]];
law("9 既定値の無い素の関数の内側の _ は、_ を外した並びと同じ木（R105。前は R38 で !_ と同じ木）", () => {
	const problems = [];
	const count = { 通る: 0, 断る: 0, "k ≠ n": 0, 撒く項: 0, "`!_` と混ぜた": 0 };
	const look = (line) => {
		try {
			const r = resolve(src([...DEFS9, line]));
			const t = r.trees[r.trees.length - 1];
			return { text: `${show(t)} : ${kindOf(t)}` };
		} catch (e) {
			if (!e.reason) return { crash: `${e.name}: ${e.message}` };
			return { refused: `${e.reason} ${e.gate || ""}` };
		}
	};
	const view = (o) => (o.crash ? `例外 ${o.crash}` : o.refused ? `断り ${o.refused}` : o.text);
	for (const [h, n] of HEADS9) {
		for (let k = Math.max(1, n - 1); k <= n + 2; k++) {
			for (const spreadAt of [-1, ...[...Array(k).keys()]]) {
				// `_` を置く位置（最後の項には置かない：末尾の `_` は法則30）。
				for (let mask = 1; mask < 1 << (k - 1); mask++) {
					if (spreadAt >= 0 && mask & (1 << spreadAt)) continue;
					const build = (pick) => {
						let j = 0;
						return [...Array(k).keys()].map((i) => (i === spreadAt ? "vs~" : mask & (1 << i) ? pick(j++) : String(i + 2))).filter((a) => a !== null).join(" ");
					};
					for (const [label, pick] of [["_", () => "_"], ["交互", (j) => (j % 2 ? "!_" : "_")]]) {
						const line = `${h} ${build(pick)}`;
						const bare = `${h} ${build((j) => (pick(j) === "_" ? null : pick(j)))}`;
						const a = look(line);
						const b = look(bare);
						if (k !== n) count["k ≠ n"]++;
						if (spreadAt >= 0) count.撒く項++;
						if (label === "交互" && line.includes("!_")) count["`!_` と混ぜた"]++;
						if (a.crash || b.crash || view(a) !== view(b)) problems.push(`${line}  ⇔  ${bare}`, `  _: ${view(a)}`, `  外した: ${view(b)}`);
						else if (a.refused) count.断る++;
						else count.通る++;
					}
				}
			}
		}
	}
	for (const [k, v] of Object.entries(count)) if (!v) problems.push(`「${k}」の組が無い（法則がその枝を見ていない）`);
	return { problems, note: Object.entries(count).map(([k, v]) => `${k} ${v}`).join("・") };
});

// ---------------------------------------------------------------------------
// 法則10：前を括っても同じ（左結合、R40、2026-10-23）
// ---------------------------------------------------------------------------
//
// 比べる3つの綴り：括らない並び `P S`、前を括った `(P) S`、前を名前に入れた `v : P ⏎ v S`（P は2〜3項、S は1〜2項）。
//
// なぜ同じか：余積は1つの演算子で左結合（R40、§3.3 の文面。U 2026-10-22 11:24「…余積は左結合で解決できるはずだと睨んでた。」）。並びは
// 左から1項ずつ畳むので、`P S` は P を畳んだ物に S の項を1つずつ畳んだ物で、P を畳んだ積み上げが1項なら `(P) S` と同じ。名前は右辺を
// 閉じた1つの項として指す（R42 の読み7。2026-10-24 の §5 Q50 の答え：右辺にも R52 を当て、`v : 5 inc` の v は 5）ので、`v : P ⏎ v S` は
// どの P でも括った `(P) S` と同じ（比べるのは種類と門。名前の葉は開けない）。2026-10-24 の Q50 の答えの前は、`:` の右辺は R52 の外で、
// 値の上に積まれた関数のある P の名前の側は v が未知（G7）に倒れていることを見ていた（下の (iii) の注）。
// 2026-10-24 の逆適用の廃止（R47）で、畳み込みの1歩は3行になった（いちばん上が A か空なら次の項を積み、積まれた関数は後ろの項を右から
// 受ける）。下の P の畳み方（fold10）と比べの外も、それに合わせて直した。
//
// 何を同じと見るか：根の種類と、断るなら門（reason と番号）。通るなら、括りの葉を開いて（openTree）流れの入れ子に書き直した
// （flowCanon）木。名前の綴りは、名前の葉を開けないので種類と門だけを、どの枝でも括った `(P) S` と比べる（下の比べの外 (i)〜(iii) でも。
// 2026-10-24 の §5 Q50 の答えまでは、名前は並び `P S` と比べ、(iii) の値の上に積まれた関数の枝では G7 を見ていた）。期待値は書かない（3つの
// 綴りを互いに比べる）。
//
// 比べの外（同じにならない所。試験の側で、語の口の形の表 SHAPE10 から P を畳んで決める。実装の答えを見て決めない）：
// - (i) 可変長の口が括りの終わりで閉じる：P の終わりに、可変長の口（最後の括り・畳む点なし、R41）の関数が1つ以上受けて開いて
//   いる。括らなければ、S の値もその口が受け、S の関数は合成の後ろに入る（`[+] 1 2 inc 3` は `inc ([+] 1 2 3)`）。括りの終わりで閉じ
//   れば、閉じた値の後ろに S が来て、S の関数は値の後ろに積まれる（R47。`([+] 1 2) 3` は2つの値、`(n 1 2) inc` は inc が余る）。
//   だから比べない。2026-10-23 までは、S が口の1つの関数だけで閉じた値が A なら、合成でも逆適用でも `g (P)` で同じなので比べていた
//   （`(n 1 2) [+ 1]`）。R47 で逆適用の読みが無くなり、その枝も比べの外になった。
// - (ii) 根の `_`：P を根で評価した値（行の根に残った未評価のラムダは `_`、R42）は、括りの中身とは違う。括りと名前の中は評価する所
//   ではないので、ラムダのまま S を受ける。だから、P を1行で解いた結果を S の前に置いた物とは比べない（比べるのは括りと名前だけ）。
//   P が根で `_` になる組は、そのことだけ見る（P を1行で解くと `(unit …)`、括りの中は L）。
// - (iii) 積み上げが括りの中で閉じる：P を畳んだ積み上げが2つ以上。括りは積み上げを1つの項（構築）にする。
//   - 積み上げの上が口の開いた関数（値の後ろに積まれた関数、R47）：括らなければ、S の項はその関数が受ける。だから `P S` とは比べない。
//     2026-10-24 の R52 から、括りの中でも、値の上に積まれて口の開いたまま閉じた関数は余ったラムダで `_` になり、構築の中で消える。だから
//     `(P) S` は、積み上げの上の関数の語（その関数を値の上に積んだ語から、P の終わりまで）を除いた `(Pv) S` と同じ種類か同じ門。その関数が
//     何も受けていなくても（`5 5 add`・`5 inc double`）、値の上で受けた後でも（`5 add 5`）同じ：値の上に積まれたのは `(F Y)` の1項（法則5）。
//     R52 の最初の版は受けた後の関数を外に置いていて（`(5 add 5) 5` は G7）、括りの側が G7 で断ることだけを見ていた（2026-10-24 の確かめの
//     指摘で、`(5 (add 5)) 5` が A と割れていたので直した）。その前は、括りの中が値と関数の並んだ構築で種類を決めず（未知、§5 Q38）、S が
//     あれば G7 だった。
//     名前の側 `v : P ⏎ v S` は、R52 の片では比べの外（`:` の右辺の並びは R52 の外で v は未知、`v S` は G7。§5 Q50 の決まっていない側に
//     倒れていることを見ていた）。2026-10-24 の Q50 の答え（閉じた1つの項）から、ほかの枝と同じく `(P) S` と比べる（字面どおり `P S` と
//     読む案は採らなかった）。
//   - 値だけの積み上げ：括らなければ S の項は値の後ろに積まれ、括れば構築の後ろに積まれる。R47 では値の後ろの関数も値を取らないので、
//     S が値でも関数でも、どちらも積むだけになり、種類を比べる（2026-10-23 までは、S の関数がいちばん上の項だけを逆適用で取るか、構築全体を
//     取るかで割れるので、S が値だけのときだけ比べていた）。木は括りの入れ子の分だけ綴りが違うので比べない。
// - (iv) 印と穴：P の中の `_`（口を埋める所で読む、R43。並びの終わりの `_` は R28）と `!_`（穴の規則は並び全体を見る、R16・R34・
//   R38）は、括りで並びが切れると読みが変わるので、語に入れない。
const DEFS10 = [INC, "double : x ? x * 2", "add : x y ? x + y", "f2 : x y ? x - y", "n : [~x] ? x", "hd : [x ~xs] ? x", "vs : 1 , 2 , 3"];
// 語の口の形：v は値、one は口が1つ、two は口が2つ、var は可変長の口、pf1 は点なしの単項、pfv は畳む点なし（可変長の口）。
const SHAPE10 = new Map([
	["5", "v"], ["[1 2]", "v"], ["vs", "v"],
	["inc", "one"], ["double", "one"], ["(add 1)", "one"], ["add", "two"], ["f2", "two"], ["n", "var"], ["hd", "var"],
	["[+ 1]", "pf1"], ["[+]", "pfv"],
]);
const WORDS10 = [...SHAPE10.keys()];
// P を試験の側で畳む（R40・R41・R47）。返す物：{ stack, openVar, rootUnit }。stack は積み上げの項の種類の並び（"v" か "f"）、openVar は
// 終わりに可変長の口が1つ以上受けて開いている、rootUnit は根なら `_` になる（上が口の開いた関数）。2026-10-23 までは、値の後ろの関数が
// 値を逆適用で取り（口が2つなら主語の口が決まらず、後ろに値が来れば G8 の { gate }）、ここでもそう畳んでいた。
const fold10 = (ws) => {
	const stack = [];
	let topStart = -1; // 積み上げの上の関数を積んだ語の位置
	ws.forEach((w, at) => {
		const sh = SHAPE10.get(w);
		const top = stack[stack.length - 1];
		if (sh === "v") {
			if (!top || top.t === "v") stack.push({ t: "v" });
			else feed10(stack, top);
			return;
		}
		// いちばん上が空か値なら積む（R47）。関数なら合成：後ろに段を足す。
		if (!top || top.t === "v") {
			stack.push({ t: "f", stages: [{ sh, recv: 0 }] });
			topStart = at;
		} else top.stages.push({ sh, recv: 0 });
	});
	const top = stack[stack.length - 1];
	const cur = top && top.t === "f" ? top.stages.find((s) => !s.done) : null;
	const openVar = !!cur && (cur.sh === "var" || cur.sh === "pfv") && cur.recv > 0;
	// 並びの終わり（R41）：可変長の口で1つ以上受けた段は閉じ、結果は次の段に入る（次も可変長なら、それも閉じる）。閉じきらない段が
	// 残る（固定の口が足りない）なら、上は口の開いた関数のままで、根なら `_`（R42）。
	let rootUnit = false;
	if (top && top.t === "f") {
		const need = { one: 1, pf1: 1, two: 2 };
		const st = top.stages.map((s) => ({ ...s }));
		let i = st.findIndex((s) => !s.done);
		while (i >= 0 && i < st.length) {
			const s = st[i];
			const fixed = need[s.sh];
			if (fixed !== undefined ? s.recv < fixed : s.recv === 0) break;
			s.done = true;
			i++;
			if (i < st.length) st[i].recv++;
		}
		rootUnit = st.some((s) => !s.done);
	}
	// いちばん上が値の上に積まれた関数なら、それを積んだ語の位置（R52 で、その語から P の終わりまでが括りの中で消える）。
	const stackedAt = stack.length >= 2 && !!top && top.t === "f" ? topStart : -1;
	return { stack: stack.map((e) => e.t), openVar, rootUnit, stackedAt };
};
// 関数の項の、いちばん最初の閉じていない段に1つ入れる。固定の口が埋まった段は閉じ、結果が次の段に入る。全部閉じたら値になる。
const feed10 = (stack, e) => {
	const need = { one: 1, pf1: 1, two: 2 };
	let i = e.stages.findIndex((s) => !s.done);
	e.stages[i].recv++;
	while (i >= 0 && i < e.stages.length && need[e.stages[i].sh] !== undefined && e.stages[i].recv >= need[e.stages[i].sh]) {
		e.stages[i].done = true;
		i++;
		if (i < e.stages.length) e.stages[i].recv++;
	}
	if (e.stages.every((s) => s.done)) stack[stack.length - 1] = { t: "v" };
};

law("10 前を括っても同じ（左結合）：P S と (P) S と v : P ⏎ v S", () => {
	const problems = [];
	const count = {
		比べた組: 0,
		通る: 0,
		"(i) 可変長の口が括りの終わりで閉じる（比べの外）": 0,
		"(ii) P が根で _（括りと名前の中は L のまま）": 0,
		"(iii) 値だけの積み上げ（種類だけ比べる）": 0,
		"(iii) 値だけの積み上げに関数が来る（種類だけ比べる、R47）": 0,
		"(iii) 積み上げの上が値の上に積まれて何も受けない関数（R52 で消える。(P) S と (Pv) S の種類を比べる）": 0,
		"(iii) 積み上げの上が値の上で受けた後の関数（R52 で消える。(P) S と (Pv) S の種類を比べる）": 0,
		"名前 v : P ⏎ v S と括り (P) S（種類と門。§5 Q50 の閉じた1つの項）": 0,
		"そのうち積み上げの上が値の上に積まれた関数（R52 の片までは名前の側が G7）": 0,
	};
	// 断る組は、2026-10-23 までは P の中の G8 だった。R47 で P の中の門は無くなったので、断る組は数えるだけにする（無くてもよい）。
	let refusedPairs = 0;
	const solve = (lines) => {
		const s = src([...DEFS10, ...lines]);
		try {
			const r = resolve(s);
			const t = r.trees[r.trees.length - 1];
			return { text: show(flowCanon(openTree(t))), kind: kindOf(t), unit: t.t === "unit", inner: t.t === "unit" ? kindOf(t.inner) : null };
		} catch (e) {
			if (!e.reason) return { crash: `${e.name}: ${e.message}` };
			return { refused: `${e.reason} ${e.gate || ""}` };
		}
	};
	const v10 = (o, withTree) => (o.crash ? `例外 ${o.crash}` : o.refused ? `断り ${o.refused}` : withTree ? `${o.text} : ${o.kind}` : `${o.kind}`);
	const prefixes = [];
	for (const a of WORDS10) for (const b of WORDS10) {
		prefixes.push([a, b]);
		// 3項目は、値・口が2つ・可変長の口の代表だけ（組が多く、1本が 15 秒を超えないように）。
		for (const c of ["5", "add", "n"]) prefixes.push([a, b, c]);
	}
	const suffixes = [];
	for (const x of WORDS10) {
		suffixes.push([x]);
		for (const y of ["5", "inc"]) suffixes.push([x, y]);
	}
	for (const P of prefixes) {
		const fp = fold10(P);
		// (ii) P を根で解くと、上が関数なら `_`。括りの中（`(P)` を1行に置くと、括りの葉1つの並びで、やはり根で `_`）と名前の右辺は L。
		if (fp.rootUnit && fp.stack.length === 1) {
			count["(ii) P が根で _（括りと名前の中は L のまま）"]++;
			const alone = solve([P.join(" ")]);
			const named = solve([`v : ${P.join(" ")}`, "v"]);
			if (!alone.refused && !alone.crash && !(alone.unit && alone.inner === "L")) problems.push(`${P.join(" ")}：根で \`_\`（包みの中が L）のはず: ${v10(alone, true)}`);
			if (!named.refused && !named.crash && !(named.unit && named.inner === "L")) problems.push(`v : ${P.join(" ")} ⏎ v：右辺が丸ごと関数なら名前も L のまま（R52 は値の上に積まれた関数だけ）で、根で使えば同じく \`_\` のはず: ${v10(named, true)}`);
		}
		for (const S of suffixes) {
			const br = solve([`(${P.join(" ")}) ${S.join(" ")}`]);
			// 名前の側：どの枝でも、括った `(P) S` と種類と門が同じ（閉じた1つの項。上の注）。
			{
				count["名前 v : P ⏎ v S と括り (P) S（種類と門。§5 Q50 の閉じた1つの項）"]++;
				if (fp.stackedAt >= 0) count["そのうち積み上げの上が値の上に積まれた関数（R52 の片までは名前の側が G7）"]++;
				const named = solve([`v : ${P.join(" ")}`, `v ${S.join(" ")}`]);
				if (v10(named) !== v10(br)) problems.push(`v : ${P.join(" ")} ⏎ v ${S.join(" ")}  ⇔  (${P.join(" ")}) ${S.join(" ")}：名前は右辺を閉じた1つの項として指すので同じはず`, `  名前: ${v10(named)}`, `  括り: ${v10(br, true)}`);
			}
			if (fp.openVar) {
				count["(i) 可変長の口が括りの終わりで閉じる（比べの外）"]++;
				continue;
			}
			if (fp.stackedAt >= 0) {
				// R52：括りの中で、値の上に積まれて口の開いたまま閉じた関数は消える。その関数を積んだ語から後ろを除いた Pv と比べる。
				const received = P.slice(fp.stackedAt).some((w) => SHAPE10.get(w) === "v");
				count[received ? "(iii) 積み上げの上が値の上で受けた後の関数（R52 で消える。(P) S と (Pv) S の種類を比べる）" : "(iii) 積み上げの上が値の上に積まれて何も受けない関数（R52 で消える。(P) S と (Pv) S の種類を比べる）"]++;
				const pv = P.slice(0, fp.stackedAt);
				const bv = solve([`(${pv.join(" ")}) ${S.join(" ")}`]);
				if (v10(br) !== v10(bv)) problems.push(`(${P.join(" ")}) ${S.join(" ")}  ⇔  (${pv.join(" ")}) ${S.join(" ")}：括りの中の上の関数は余って消える（R52）ので同じはず`, `  P: ${v10(br, true)}`, `  Pv: ${v10(bv, true)}`);
				// 名前の側は、上で `(P) S` と比べた（§5 Q50 の答えの前は、ここで G7 を見ていた）。
				continue;
			}
			const onlyKind = fp.stack.length >= 2;
			if (onlyKind) {
				if (S.every((w) => SHAPE10.get(w) === "v")) count["(iii) 値だけの積み上げ（種類だけ比べる）"]++;
				else count["(iii) 値だけの積み上げに関数が来る（種類だけ比べる、R47）"]++;
			}
			count.比べた組++;
			const plain = solve([`${P.join(" ")} ${S.join(" ")}`]);
			const vp = v10(plain, !onlyKind);
			const vb = v10(br, !onlyKind);
			if (vp !== vb) problems.push(`${P.join(" ")} ${S.join(" ")}  ⇔  (${P.join(" ")}) ${S.join(" ")}`, `  並び: ${vp}`, `  括り: ${vb}`);
			// 名前の側は、上で `(P) S` と比べた（ここでは並びと括りが同じなので、名前と並びも同じ種類と門）。
			if (plain.refused) refusedPairs++;
			else count.通る++;
		}
	}
	for (const [k, v] of Object.entries(count)) if (!v) problems.push(`「${k}」の組が無い（法則がその枝を見ていない）`);
	return { problems, note: `${Object.entries(count).map(([k, v]) => `${k} ${v}`).join("・")}・断る ${refusedPairs}` };
});

// ---------------------------------------------------------------------------
// 法則11：口の外の `!_` は、`i : !_` の i と同じ（R44、2026-10-23）
// ---------------------------------------------------------------------------
//
// 比べる2つの綴り：`!_ X` と、`i : !_` の下の `i X`（X は1〜3項）。値の後ろでも同じ：`5 !_ X` と `5 i X`（X は1〜2項）。
//
// なぜ同じか：`:` はメタで、名前は右辺の式を指す（U〔答え〕2026-10-22 22:14、ボタン「定義は式を指す」）ので、`i` と書くのは右辺の `!_` と
// 書くのと同じ。並びの頭と値の後ろは口の外（`!_` が埋める口が無い）で、口の外の `!_` は恒等射（R44。U〔答え〕[2026-10-22 23:48 ebf18260]
// 「5 !_ / 5 , !_ も追加で、 全部5になるはず…」。主の Claude の問い「`!_ 5` は `i 5` に合わせて 5、でいい？」への答え）。だから X が
// 何でも、2つの綴りは同じ答えでなければならない（期待値は書かない）。
//
// 何を同じと見るか：最後の行の木（葉の `i` を `!_` と読む）・種類・余りの印、断るなら門（reason と番号と名指し）。
//
// 比べの外：無い。X の中に `!_` があっても（口の中の穴・G5・G7）、2つの綴りで同じ所に同じ物があるので比べる。中置の被演算子の `!_`
// （`!_ + 1`、§5 Q15）は項の中で、並びの頭の `!_` ではないので、X の語に中置を入れない。頭の関数の口を値で埋めた後ろの `!_`
// （`inc 5 !_` の G13、§5 Q40。`inc 5 i` は通る）は、並びの頭でも `5` の後ろでもないので、この法則の比べの外（名指しで断る所）。
// この法則は `!_` と i の配線が揃っているかを見るだけで、恒等射の読みそのもの（R29 の流れ）が単位律と合うかは見ない（両側に同じ
// 読みが乗る）。それは法則13 が見る。
const DEFS11 = [
	INC,
	"add : x y ? x + y",
	"f2 : x y ? x - y",
	"f3 : a b c ? c",
	"n : [~r] ? r",
	"io1 : [say] ? say 21",
	"uu : m ? [,] m",
	"use : f m ? @f m",
	// 2026-11-04 の寄せ2（R131）で、仮引数のブロックへ書き換えた（前は括りの既定値 `gq : m [y : 1] ? m + y`）。toUnits で続く TAB の行と閉じの空の行まで1文。
	"gq :",
	"\t\tm",
	"\t\ty : 1",
	"\t? m + y",
	"",
	"i : !_",
	"vs : 1 , 2 , 3",
];
const UNITS11 = toUnits(DEFS11);
const WORDS11 = ["5", "[1 2]", "vs", "_", "$inc", "(inc 5)", "inc", "add", "f2", "f3", "n", "io1", "uu", "use", "gq", "i", "!_", "[+]", "[+ 1]", "[* 2,]", "[<<]", "[' 0]", "||inc||", "(add 1)", "vs~"];
const WORDS11_3 = ["5", "_", "inc", "add", "n", "io1", "i", "!_", "[+]", "[+ 1]", "(add 1)", "vs~"];
// 葉の `i` を `!_` と読む（木の綴りの、空白か括弧で区切られた `i` だけ。`inc`・`$inc` などは触らない）。
const asBang = (s) => s.replace(/(?<=^|[\s(\[])i(?=$|[\s)\]])/g, "!_");
const view11 = (o) => (o.crash ? `例外 ${o.crash}` : o.refused ? `断り ${asBang(refusalText(o))}` : `${asBang(lastOf(o).text)} : ${lastOf(o).kind}${lastOf(o).leftover ? "（余りを積む）" : ""}`);
const solve11 = (line, defsFrom = line) => outcome(src([...usedDefs(UNITS11, defsFrom), line]));
const seqs11 = (ws, k) => (k === 0 ? [[]] : seqs11(ws, k - 1).flatMap((s) => ws.map((w) => [...s, w])));

law("11 口の外の !_ は i : !_ の i と同じ：!_ X と i X、5 !_ X と 5 i X", () => {
	const problems = [];
	const count = { 比べた組: 0, 通る: 0, 断る: 0, "値の後ろ": 0 };
	const Xs = [...seqs11(WORDS11, 1), ...seqs11(WORDS11, 2), ...seqs11(WORDS11_3, 3)];
	const pairs = [
		...Xs.map((x) => [`!_ ${x.join(" ")}`, `i ${x.join(" ")}`, false]),
		...Xs.filter((x) => x.length <= 2).map((x) => [`5 !_ ${x.join(" ")}`, `5 i ${x.join(" ")}`, true]),
	];
	for (const [a, b, after] of pairs) {
		const oa = solve11(a, b);
		const ob = solve11(b);
		count.比べた組++;
		if (after) count.値の後ろ++;
		if (oa.crash || ob.crash || view11(oa) !== view11(ob)) problems.push(`${a}  ⇔  ${b}`, `  !_: ${view11(oa)}`, `  i : ${view11(ob)}`);
		else if (oa.refused) count.断る++;
		else count.通る++;
	}
	for (const [k, v] of Object.entries(count)) if (!v) problems.push(`「${k}」の組が無い（法則がその枝を見ていない）`);
	return { problems, note: Object.entries(count).map(([k, v]) => `${k} ${v}`).join("・") };
});

// ---------------------------------------------------------------------------
// 法則12：恒等射は `,` の単位（R45、2026-10-23）
// ---------------------------------------------------------------------------
//
// 比べる綴り：行 `X` と、`!_ , X`・`X , !_`・`i , X`・`X , i`（X は1〜2項の並び）。もう1つ被演算子があっても同じ：`X , !_ , 7` と
// `!_ , X , 7` と `X , 7`（`,` は右結合なので、`X , !_ , 7` は `X , (!_ , 7)`）。X が右でも同じ：`7 , !_ , X`・`7 , X , !_`・`7 , i , X` と
// `7 , X`（中の `,` が消えて残った X の並びにも、外の `,` の G3 が当たる。2026-10-24 の確かめで足した。前は X が左の形しか比べず、
// `2 , !_ , inc 1` が `2 , inc 1`（G3）なのに通っていたのが見えなかった）。
//
// なぜ同じか：恒等射の型 0 ⇒ 0 ≅ 1 は終対象で、積の単位（1 × A ≅ A・A × 1 ≅ A。書いた `_` が余積の並びから消える 0 ⊕ A ≅ A（R15）の
// 双対。主の Claude の読み）。`,` の被演算子の恒等射は消え、もう片方の被演算子が答え（木も、もう片方の木そのもの。U〔答え〕[2026-10-22
// 23:48 ebf18260]「5 !_ / 5 , !_ も追加で、 全部5になるはず…」）。片方が恒等射なら、G3 の割れ（`(f x) , y` か `f (x , y)` か、§5 Q3）も
// 消える（`(f x) , !_` も `f (x , !_)` も `f x`）。根の `,` が消えて並びだけが残れば、その行の根はその並びなので、行 `X` と同じく評価する
// 所（R42）。
//
// 何を同じと見るか：法則11 と同じ（葉の `i` を `!_` と読む。恒等射どうしの `!_ , i` は、どちらの恒等射が残っても同じ）。
//
// 名前の右辺でも同じ：`v : X , !_`・`v : !_ , X`・`v : X , i`・`v : i , X` と `v : X`（使う行は `v` と `v 3`。全部の行の木・種類・門と、
// 診断を比べる）。`,` が恒等射で消えて残った並びは右辺の並びそのもの（R45）なので、`v : X` と同じ答えでなければならない。2026-10-24 の確かめ
// で足した：前は根だけを比べていて、`v : 5 inc , !_` ⏎ `v 3` が通り（残った並びに R52 が当たって v は 5）、`v : 5 inc` ⏎ `v 3` が G7 と割れて
// いたのが見えなかった（そのときは、左が名前1つの `:` の右辺の並びは R52 の外だった）。同じ日の §5 Q50 の答えから、右辺は閉じた1つの項で
// R52 を当てる（どちらも v は 5）。加えて、名前 `v : X` ⏎ `v`・`v 3` と、括った右辺 `(X)`・`(X) 3` も比べる（最後の行の種類と門と診断。名前の
// 葉は開けない。閉じた1つの項の読み）。
//
// 比べの外：`$!_` は値（A）で恒等射ではないので、X の語に入れて、消えないことも比べる。名前と括りの比べでは、X が `!_` 1つの形だけ外す：
// 1行の括り `(!_)` は否定の点なし（§2、U 2026-10-21 08:24）で、`!_` を括った物ではない。2026-10-26 の確かめの直しから、`!_` の後ろに書いた `_` だけが続く
// X（`!_ _`）も外す：括った `(!_ _)` は、末尾の `_` を消してから括りの形を見れば否定の点なし、書いた項で見れば恒等射（R29・R28）で割れるので G7（§5 Q74）。
// 比べずに、括りの側が G7 で断ることを見る（名前の右辺 `v : !_ _` は括らないので恒等射）。2026-10-28 の R108 から、括った `(!_ _)` も書いた項どおり恒等射なので比べる。
// 2026-10-25（R61、§5 Q41 の答え）に広げた所：書いた `_` も積の単位なので、`_ , X`・`X , _`・`X , _ , 7`・`_ , X , 7`・`7 , _ , X`・`7 , X , _`・名前の右辺の
// `v : X , _`・`v : _ , X` も、恒等射のときと同じ相手と比べる（U [2026-10-25 08:41 533071da]「Q41 / _ , 5 も 5 , _ も 5 になるはずだ。」。主の Claude の読み：
// `_` は点付きの側の零対象で、終対象として積の単位）。X が恒等射で `_` と隣り合う積だけは、どちらの単位が消えるかで残る物が割れるので、`_` の側が G7
// で断っていた（§5 Q61、断る側だけを許す）。2026-10-26 の R71（§5 Q61 の答え、U〔答え〕[2026-10-25 21:56 c8ccdd69]「Q61 / _ に落としていい」）から `_` に
// 落ちるので、恒等射を消した綴り（X が `_` のとき）か、X を `_` に替えた綴り（X が恒等射のとき）と比べる。消えるのは書いた `_` だけで、名前や括りを通した
// `_`（`un : _` の un・`(_)`）は比べない（閉じた1つの項）。
// 比べ・論理の被演算子（2026-10-28 の片9 の確かめの直しで足した）：`X , !_ == 7`・`!_ , X == 7`・`X , _ == 7` と `X == 7`、`1 & X , !_` と `1 & X`（全部の行の木・種類・
// 門と、診断）。比べと論理の被演算子は評価する所（R76）で、そこの `,` が単位で消えて残った並びも評価する所の並び（R107 の R の所、resolveEvaluatedSide）。前は行の
// 根でだけ解き直していて、`gq 5 , !_ == 7` が埋めない木、`gq 5 == 7` が既定値を埋めた木と割れていた（余ったラムダの `add 5 , !_ == 7` と `add 5 == 7` は HEAD から
// 割れていた）。比べの外：X が恒等射と書いた `_` だけの並び（`i`・`!_`・`i _`）は、`,` の両辺が恒等射なら断る側の `!_` を残す（resolveProduct の注、§5 Q15）ので、
// `i , !_ == 7` は G7、`i == 7` は通る（断る側だけの割れで、根の比べが見る）。値の後ろに関数を置いた X は、逆適用の廃止（R47）の決まりで新しい綴りを作らない
// ので、この包みでは比べない（根と名前の右辺の比べは前からの綴り）。
const VALUE11 = new Set(["5", "[1 2]", "vs", "_", "$inc", "(inc 5)", "vs~", "$!_"]);
const opX12 = (X) => {
	const ws = X.split(" ");
	if (ws.every((w) => w === "i" || w === "!_" || w === "_") && ws.some((w) => w !== "_")) return false;
	return !ws.some((w, j) => j > 0 && VALUE11.has(ws[j - 1]) && !VALUE11.has(w));
};
law("12 恒等射は , の単位：X と !_ , X・X , !_・i , X・X , i、X , !_ , 7 と X , 7、7 , !_ , X と 7 , X、v : X , !_ と v : X、v : X と (X)、X , !_ == 7 と X == 7", () => {
	const problems = [];
	const count = { 比べた組: 0, 通る: 0, 断る: 0, "もう1つの被演算子": 0, "名前の右辺": 0, "名前と括った右辺": 0, "書いた `_`（R61）": 0, "書いた `_` と恒等射の積は `_`（R71）": 0, "括った `(!_ _)` は書いた項どおり恒等射で比べる（R108。前は G7）": 0, "比べ・論理の被演算子（R76。確かめの直しで足した）": 0 };
	// 全部の行の木（葉の `i` を `!_` と読む）・種類・門と、診断。
	const viewAll = (o) =>
		o.crash ? `例外 ${o.crash}` : o.refused ? `断り ${asBang(refusalText(o))}` : `${o.trees.map((t) => `${asBang(t.text)} : ${t.kind}`).join(" | ")} || ${o.diag.join(" ")}`;
	// 最後の行の種類・門と、診断（名前と括りの比べ。名前の葉は開けないので木は比べない）。
	const viewLast = (o) => (o.crash ? `例外 ${o.crash}` : o.refused ? `断り ${asBang(refusalText(o))}` : `${lastOf(o).kind} || ${o.diag.join(" ")}`);
	// 2026-10-26 の R66（§5 Q3 の答え）から、X の最後の値が括りの関数の最後の括りに最初に入る形（X が `n 5`・`io1 [1 2]`）の `X , !_ , 7` は `n (5 , !_ , 7)` と
	// 読み、木は括って書いた形の葉で、書いた積の綴り（`[5 , !_ , 7]`）を持つ（括りは書いたとおりに書く、§1.3）。だから木の比べでは、括りの綴りの中の書いた
	// 単位（`!_`・`i`・`_`）を消して読む。木の S 式の積は `(, a b)` と書くので、` , ` が出るのは括りの綴りの中だけで、X の語に `,` を含む括りは無いので、
	// ほかの綴りは変わらない。
	const unitsOut = (s) => s.replace(/ , (?:!_|i|_)(?= ,|\])/g, "").replace(/(?<=\[)(?:!_|i|_) , /g, "");
	const view12 = (o) => unitsOut(view11(o));
	const solveLines = (lines, defsFrom) => outcome(src([...usedDefs(UNITS11, defsFrom), ...lines]));
	const Xs = [...seqs11([...WORDS11, "$!_"], 1), ...seqs11(WORDS11, 2)].map((x) => x.join(" "));
	for (const X of Xs) {
		const defsFrom = `i ${X}`;
		const base = solve11(X, defsFrom);
		// 3つ目は、恒等射が X と隣り合う `,` の積か（X が書いた `_` なら、下の R61 の注のとおり G7 で断る側）。
		const xIsMark = X.split(" ").every((w) => w === "_"); // `_`・`_ _`（書いた `_` だけの並びは `_`、R15）
		const groups = [
			[base, [`!_ , ${X}`, `${X} , !_`, `i , ${X}`, `${X} , i`], true],
			[solve11(`${X} , 7`, defsFrom), [`${X} , !_ , 7`, `!_ , ${X} , 7`], false],
			[solve11(`7 , ${X}`, defsFrom), [`7 , !_ , ${X}`, `7 , ${X} , !_`, `7 , i , ${X}`], true],
		];
		for (const [want, lines, adjacentId] of groups) {
			for (const line of lines) {
				const o = solve11(line, defsFrom);
				count.比べた組++;
				if (want !== base) count["もう1つの被演算子"]++;
				// X が書いた `_` で恒等射と隣り合う積は、2026-10-26 の R71（§5 Q61 の答え）から `_` に落ちるので、恒等射を消した綴りと同じ（ほかの X と同じ比べ。
				// R61 の片では G7 で断る側だった）。
				if (xIsMark && adjacentId) count["書いた `_` と恒等射の積は `_`（R71）"]++;
				const ref = want === base ? X : line.startsWith("7 ,") ? `7 , ${X}` : `${X} , 7`;
				if (o.crash || want.crash || view12(o) !== view12(want)) problems.push(`${line}  ⇔  ${ref}`, `  ${line}: ${view11(o)}`, `  ${ref}: ${view11(want)}`);
				else if (o.refused) count.断る++;
				else count.通る++;
			}
		}
		// 書いた `_` も積の単位（R61、2026-10-25 の §5 Q41 の答え。U [2026-10-25 08:41 533071da]「Q41 / _ , 5 も 5 , _ も 5 になるはずだ。」）：`_ , X`・`X , _` と X、
		// `X , _ , 7`・`_ , X , 7` と `X , 7`、`7 , _ , X`・`7 , X , _` と `7 , X`。X が恒等射（`!_`・`i`）で、`_` と隣り合う `,` の積は、どちらの単位が消えるかで
		// 残る物が割れるので、`_` の側が G7 で断る（§5 Q61。法則13 の「恒等射の側が断る」と同じく、断る側だけを許す）。X が `_` なら `_ , _` は `_`。
		const xIsId = X === "i" || X === "!_";
		const unitGroups = [
			[base, [`_ , ${X}`, `${X} , _`], true],
			[solve11(`${X} , 7`, defsFrom), [`${X} , _ , 7`, `_ , ${X} , 7`], false],
			[solve11(`7 , ${X}`, defsFrom), [`7 , _ , ${X}`, `7 , ${X} , _`], true],
		];
		for (const [want0, lines, adjacent] of unitGroups) {
			for (const line of lines) {
				let want = want0;
				const o = solve11(line, defsFrom);
				count.比べた組++;
				count["書いた `_`（R61）"]++;
				let ref = want === base ? X : line.startsWith("7 ,") ? `7 , ${X}` : `${X} , 7`;
				// X が恒等射で `_` と隣り合う積は、R71 から `_` に落ちる（恒等射が消える側）ので、X を `_` に替えた綴り（`_`・`7 , _`）と比べる。R61 の片では G7。
				if (xIsId && adjacent) {
					count["書いた `_` と恒等射の積は `_`（R71）"]++;
					ref = want === base ? "_" : "7 , _";
					want = solve11(ref, defsFrom);
				}
				if (o.crash || want.crash || view12(o) !== view12(want)) problems.push(`${line}  ⇔  ${ref}`, `  ${line}: ${view11(o)}`, `  ${ref}: ${view11(want)}`);
				else if (o.refused) count.断る++;
				else count.通る++;
			}
		}
		// 名前の右辺（上の注）。
		for (const use of ["v", "v 3"]) {
			const wantN = solveLines([`v : ${X}`, use], defsFrom);
			// 名前と括った右辺（閉じた1つの項。`(!_)` は否定の点なしなので外す、上の注）。`(!_ _)` は括りの側が G7（上の注、§5 Q74）。
			// 2026-10-28 の R108（§5 Q74 (c) を閉じた）から、`(!_ _)` は書いた項どおり恒等射の括りなので、ほかの X と同じに比べる（名前の右辺 `v : !_ _` も恒等射）。
			if (/^!_( _)+$/.test(X)) count["括った `(!_ _)` は書いた項どおり恒等射で比べる（R108。前は G7）"]++;
			if (X !== "!_") {
				const brL = solveLines([use.replace(/^v/, `(${X})`)], defsFrom);
				count.比べた組++;
				count["名前と括った右辺"]++;
				if (wantN.crash || brL.crash || viewLast(wantN) !== viewLast(brL)) problems.push(`v : ${X} ⏎ ${use}  ⇔  ${use.replace(/^v/, `(${X})`)}`, `  名前: ${viewLast(wantN)}`, `  括り: ${viewLast(brL)}`);
				else if (brL.refused) count.断る++;
				else count.通る++;
			}
			const rhss = [`${X} , !_`, `!_ , ${X}`, `${X} , i`, `i , ${X}`, `${X} , _`, `_ , ${X}`];
			for (let k = 0; k < rhss.length; k++) {
				const rhs = rhss[k];
				const o = solveLines([`v : ${rhs}`, use], defsFrom);
				count.比べた組++;
				count["名前の右辺"]++;
				// 名前の右辺の `X , _`・`_ , X`（R61、後ろの2つ）。X が恒等射なら、上と同じく R71 で `_` に落ちるので `v : _` と比べる（R61 の片では G7）。X が書いた `_` で、
				// 前の4つ（恒等射との積）は恒等射が消えて `v : X`（= `v : _`）と同じ。
				let refN = wantN;
				let refText = X;
				if ((k >= 4 && xIsId) || (k < 4 && xIsMark)) {
					count["書いた `_` と恒等射の積は `_`（R71）"]++;
					refN = solveLines(["v : _", use], defsFrom);
					refText = "_";
				}
				if (o.crash || refN.crash || viewAll(o) !== viewAll(refN)) problems.push(`v : ${rhs} ⏎ ${use}  ⇔  v : ${refText} ⏎ ${use}`, `  ,: ${viewAll(o)}`, `  X: ${viewAll(refN)}`);
				else if (o.refused) count.断る++;
				else count.通る++;
			}
		}
		// 比べ・論理の被演算子（上の注）。
		if (opX12(X)) {
			const eqRef = `${X} == 7`;
			const andRef = `1 & ${X}`;
			const eqBase = solve11(eqRef, defsFrom);
			const andBase = solve11(andRef, defsFrom);
			const opPairs = [
				[eqBase, eqRef, `${X} , !_ == 7`],
				[eqBase, eqRef, `!_ , ${X} == 7`],
				[eqBase, eqRef, `${X} , _ == 7`],
				[andBase, andRef, `1 & ${X} , !_`],
			];
			for (const [want, ref, line] of opPairs) {
				const o = solve11(line, defsFrom);
				count.比べた組++;
				count["比べ・論理の被演算子（R76。確かめの直しで足した）"]++;
				if (o.crash || want.crash || viewAll(o) !== viewAll(want)) problems.push(`${line}  ⇔  ${ref}`, `  ,: ${viewAll(o)}`, `  X: ${viewAll(want)}`);
				else if (o.refused) count.断る++;
				else count.通る++;
			}
		}
	}
	for (const [k, v] of Object.entries(count)) if (!v) problems.push(`「${k}」の組が無い（法則がその枝を見ていない）`);
	return { problems, note: Object.entries(count).map(([k, v]) => `${k} ${v}`).join("・") };
});

// ---------------------------------------------------------------------------
// 法則13：恒等射を消しても同じか、恒等射の側が断る（単位律、R29・R44・R46、2026-10-23）
// ---------------------------------------------------------------------------
//
// 比べる2つの綴り：`P i S` と、恒等射を消した `P S`（P は0〜1項、S は1〜2項）。行の根のほかに、括って後から当てた `(P i S) 3` と
// `(P S) 3`、名前に入れて当てた `v9 : P i S ⏎ v9 3` と `v9 : P S ⏎ v9 3` も比べる（根では行の終わりの `_`（R42）で同じになる割れが、
// 後から当てると見える）。名前に入れて当てた形は、括って当てた形とも比べる：`v9 : X ⏎ v9 3` と `(X) 3` が同じ種類と門（X は `P i S` も
// `P S` も。名前は右辺を閉じた1つの項として指す、2026-10-24 の §5 Q50 の答え）。その答えの前は、`:` の右辺は R52 の外で、値の上に積まれた
// 関数の残る X（`5 i inc`・`5 inc`）は、名前の側だけ v9 が未知で両側とも G7 になり、単位律の比べは断る側で素通りしていた。
//
// なぜ同じか：恒等射との合成はその関数そのもの、恒等射を当てた物は当てた物そのもの（単位律。U〔答え〕[2026-10-22 23:48 ebf18260]
// 「5 !_ / 5 , !_ も追加で、 全部5になるはず…」で `5 !_` は 5）。余積は左結合（R40）なので `P i S` は `(P i) S` で、`P i` は P。一方、
// 恒等射は並び全体を受けて1つの値で次へ渡す（R29、主の Claude の読み）ので、恒等射が開いている間に来た関数は合成の後ろに入り、単位律の
// 読みと割れうる（2026-10-23 は、単位律の読みのその関数が逆適用で値を取った。2026-10-24 の R47 からは、値の後ろに積まれて値を取らない）。
// 割れる所は G18 で断る（§4 R29、§5 Q13）。だから恒等射の側は、消した側と同じ答えか、断るかのどちらか。`!_` の側は、法則11（口の外）と
// 法則14（口の中、R46）が `i` に結ぶ。
// 2026-10-24 に、S が3項で、恒等射が受けた物を口の数の分からない関数（`[,]`・段18 の点なし・既定値のある関数・撒く項を受けた固定の口の
// 関数）が受け、その後に関数が合成される形を足した（`i [,] 5 inc`。単位律では G2(a) で、HEAD では恒等射の側が通っていた）。
//
// 何を同じと見るか：恒等射の側が通るなら、消した側も通り、根の種類と積み上げの形（sig13：恒等射を当てた節はその中身、恒等射が並びを
// 受けた節は構築に開く、ほかの適用・合成は1つ）が同じ。恒等射の側の種類が未知なのは、弱い答えとして許す（恒等射が撒く項を受けた並びは
// 未知。R24 の「撒く項があれば k は数えない」で、消した側は構築で A）。恒等射の側が断るのは許す（断る側。`vs~ i` は R14 の G9）。
// 期待値は書かない。
//
// 2026-10-23 の確かめで足した。法則11 は `!_ X` と `i X` の配線を比べるだけで、両側に同じ恒等射の読みが乗るので、この割れ
// （`(5 !_ f2) 3` が f2 5 3 で通り、`(5 f2) 3` は G8。`!_ 1 2 [* 2,]` が `[* 2,] [1 2]`、`1 2 [* 2,]` は `1 ([* 2,] 2)`）に盲目だった。
// R47 の後の割れの例：`i 5 inc` は流れでは `inc 5`、消した `5 inc` は inc が余る（恒等射の側が G18）。
const DEFS13 = [
	INC,
	"add : x y ? x + y",
	"f2 : x y ? x - y",
	"n : [~r] ? r",
	"io1 : [say] ? say 21",
	"uu : m ? [,] m",
	"c1 : inc inc",
	"i : !_",
	"vs : 1 , 2 , 3",
	"gd :",
	"\t\tys",
	"\t\tzs : 3",
	"\t? ys",
	"",
];
const UNITS13 = toUnits(DEFS13);
const WORDS13 = ["5", "[1 2]", "vs~", "inc", "add", "f2", "n", "io1", "uu", "gd", "[+]", "[+ 1]", "[* 2,]", "[<<]", "(add 1)", "||!_||", "[' 0]"];
const isId13 = (t) => !!t && t.t === "leaf" && !!t.view && (t.view.text === "i" || t.view.text === "!_");
const idRow13 = (t) => t.t === "apply" && isId13(t.head) && t.arg.t === "construct";
// 積み上げの形：構築は項ごと（恒等射が並びを受けた節は開く）、恒等射を当てた節はその中身、恒等射を除いて1つの関数の合成はその関数、
// ほかの適用・合成と関数の葉は f、値の葉は x、根の `_` は u(…)。
const sig13 = (t) => {
	switch (t.t) {
		case "unit":
			return `u(${sig13(t.inner)})`;
		case "construct":
			return `[${t.items.flatMap((u) => (idRow13(u) ? u.arg.items : [u])).map(sig13).join(",")}]`;
		case "apply":
			return isId13(t.head) ? sig13(t.arg) : "f";
		case "compose": {
			const xs = t.items.filter((u) => !isId13(u));
			return xs.length === 1 && xs[0].t !== "leaf" ? sig13(xs[0]) : "f";
		}
		case "leaf":
			return isId13(t) || (t.kind && t.kind.k === "L") ? "f" : "x";
		default:
			return "x";
	}
};
const memo13 = new Map();
const solve13 = (line) => {
	let o = memo13.get(line);
	if (o) return o;
	try {
		const r = resolve(src([...usedDefs(UNITS13, line), ...line.split("\n")]));
		const t = r.trees[r.trees.length - 1];
		o = { text: show(t), sig: sig13(t), kind: t.t === "unit" ? `${kindOf(t.inner)}（根で _）` : kindOf(t) };
	} catch (e) {
		o = e.reason ? { refused: `${e.reason} ${e.gate || ""}` } : { crash: `${e.name}: ${e.message}` };
	}
	memo13.set(line, o);
	return o;
};
const view13 = (o) => (o.crash ? `例外 ${o.crash}` : o.refused ? `断り ${o.refused}` : `${o.sig} : ${o.kind}`);
const weaker13 = (o) => o.kind === "未知" || o.kind === "未知（根で _）";
// 恒等射の側 a と、比べる側 b。a が通るなら、b も通り、種類（a が未知なら許す）と形が同じ。
const unitLaw13 = (a, b) => {
	if (a.crash || b.crash) return "例外";
	if (a.refused) return null;
	if (b.refused) return "恒等射の側だけ通る";
	if (a.kind !== b.kind) return weaker13(a) ? null : "種類";
	return a.sig === b.sig ? null : "形";
};
const ctx13 = (s, c) => (c === 1 ? `(${s}) 3` : c === 2 ? `v9 : ${s}\nv9 3` : s);
// 名前と括りの比べ（種類と門。名前の葉は開けないので形は比べない）。
const kindGate13 = (o) => (o.crash ? `例外 ${o.crash}` : o.refused ? `断り ${o.refused}` : o.kind);

law("13 恒等射を消しても同じか、恒等射の側が断る（単位律）：P i S と P S、v9 : X ⏎ v9 3 と (X) 3", () => {
	const problems = [];
	const count = { 比べた組: 0, 通る: 0, "恒等射の側が断る": 0, "恒等射の側が未知（弱い答え）": 0, 後から当てる: 0, 名前と括り: 0 };
	const Ps = [[], ...seqs11(WORDS13, 1)];
	// S の3項（上の注）：[口の数の分からない関数か固定の口の関数, 受ける物, 後ろの関数]。
	const S3 = [];
	for (const f of ["[,]", "[' 0]", "gd", "f2", "inc"]) for (const x of ["5", "[1 2]", "vs~"]) for (const g of ["inc", "f2", "[* 2,]"]) S3.push([f, x, g]);
	const Ss = [...seqs11(WORDS13, 1), ...seqs11(WORDS13, 2), ...S3];
	for (const P of Ps) for (const S of Ss) for (const c of [0, 1, 2]) {
		const a = ctx13(`${[...P, "i", ...S].join(" ")}`, c);
		const b = ctx13(`${[...P, ...S].join(" ")}`, c);
		const oa = solve13(a);
		const ob = solve13(b);
		count.比べた組++;
		if (c) count.後から当てる++;
		const bad = unitLaw13(oa, ob);
		if (bad) problems.push(`${bad}：${a.replace("\n", " ⏎ ")}  ⇔  ${b.replace("\n", " ⏎ ")}`, `  恒等射: ${view13(oa)}`, `  消した: ${view13(ob)}`);
		else if (oa.refused) count["恒等射の側が断る"]++;
		else if (!ob.refused && oa.kind !== ob.kind) count["恒等射の側が未知（弱い答え）"]++;
		else count.通る++;
		// 名前に入れて当てた形は、括って当てた形と同じ種類と門（上の注。閉じた1つの項）。恒等射の側も、消した側も。
		if (c === 2) {
			for (const s of [[...P, "i", ...S], [...P, ...S]]) {
				const on = solve13(ctx13(s.join(" "), 2));
				const ok = solve13(ctx13(s.join(" "), 1));
				count["名前と括り"]++;
				if (kindGate13(on) !== kindGate13(ok)) problems.push(`名前と括り：${ctx13(s.join(" "), 2).replace("\n", " ⏎ ")}  ⇔  ${ctx13(s.join(" "), 1)}`, `  名前: ${view13(on)}`, `  括り: ${view13(ok)}`);
			}
		}
	}
	for (const [k, v] of Object.entries(count)) if (!v) problems.push(`「${k}」の組が無い（法則がその枝を見ていない）`);
	return { problems, note: Object.entries(count).map(([k, v]) => `${k} ${v}`).join("・") };
});

// ---------------------------------------------------------------------------
// 法則14：口の中で通った `!_` は、恒等射と読んでも穴と読んでも同じ（R46、2026-10-23）
// ---------------------------------------------------------------------------
//
// 比べる綴り：`Y !_ S` と、恒等射の読みの `Y i S`、穴の読みの `[x ? Y x] S`（その口に置いた λ、R16・R34 の穴と同じくその段の適用を
// 包む）。Y は口が1つの関数で、穴の頭（名前の定義か `?` の括り）でない物（穴の規則が並び全体で読まないので、通るなら R46）。S は0〜2項。
// 根のほかに、法則13 と同じく後から当てた形も比べる。
//
// なぜ同じか：R46 は、口の数の決まった関数に口が1つだけ残った所の `!_` を、穴と読んでも恒等射と読んでも同じ関数なので通す（主の Claude の
// 依頼から出した規則、R）。だから通った `Y !_ S` は、`Y i S` と同じ木（葉の `i` を `!_` と読む）・同じ種類で、`[x ? Y x] S` とは法則13 の
// 見方で同じ（`!_` の側が未知なのは弱い答えとして許す：恒等射が撒く項を含む並びを受けた `[+ 1] !_ 5 vs~` は未知、λ の読みは構築で A）。
//
// 何を同じと見るか：上の通り。`Y !_ S` が断るなら比べない（断る側。口が2つ以上残る・可変長の口などの G7 と、割れる所の G18）。
// 2026-10-23 の確かめで足した（前は R46 に期待値の行しか無かった）。
const HEADS14 = [
	["[+ 1]", "[x ? [+ 1] x]"],
	["(add 1)", "[x ? add 1 x]"],
	["(inc)", "[x ? inc x]"],
	["||inc||", "[x ? ||inc|| x]"],
	["[<<] 1", "[x ? [<<] 1 x]"],
	["c1", "[x ? c1 x]"],
];
law("14 口の中で通った !_ は、恒等射と読んでも穴と読んでも同じ：Y !_ S と Y i S・[x ? Y x] S", () => {
	const problems = [];
	const count = { 比べた組: 0, 通る: 0, 断る: 0, "!_ の側が未知（弱い答え）": 0 };
	const Ss = [[], ...seqs11(WORDS13, 1), ...seqs11(["5", "vs~", "inc", "f2", "uu", "[* 2,]", "||!_||", "[' 0]"], 2)];
	for (const [Y, lam] of HEADS14) for (const S of Ss) for (const c of [0, 1, 2]) {
		const tail = S.length ? ` ${S.join(" ")}` : "";
		const a = ctx13(`${Y} !_${tail}`, c);
		const bi = ctx13(`${Y} i${tail}`, c);
		const bl = ctx13(`${lam}${tail}`, c);
		const oa = solve13(a);
		count.比べた組++;
		if (oa.crash) {
			problems.push(`例外：${a}`, `  ${oa.crash}`);
			continue;
		}
		if (oa.refused) {
			count.断る++;
			continue;
		}
		const oi = solve13(bi);
		if (oi.refused || oi.crash || asBang(oi.text) !== oa.text || oi.kind !== oa.kind) {
			problems.push(`恒等射の読みと違う：${a.replace("\n", " ⏎ ")}  ⇔  ${bi.replace("\n", " ⏎ ")}`, `  !_: ${view13(oa)} ${oa.text}`, `  i : ${view13(oi)} ${oi.text || ""}`);
			continue;
		}
		const ol = solve13(bl);
		const bad = unitLaw13(oa, ol);
		if (bad) problems.push(`穴の読みと${bad}：${a.replace("\n", " ⏎ ")}  ⇔  ${bl.replace("\n", " ⏎ ")}`, `  !_: ${view13(oa)}`, `  λ : ${view13(ol)}`);
		else if (oa.kind !== ol.kind) count["!_ の側が未知（弱い答え）"]++;
		else count.通る++;
	}
	for (const [k, v] of Object.entries(count)) if (!v) problems.push(`「${k}」の組が無い（法則がその枝を見ていない）`);
	return { problems, note: Object.entries(count).map(([k, v]) => `${k} ${v}`).join("・") };
});

// ---------------------------------------------------------------------------
// 法則15：撒いた並びは流れの1項（R49〜R51。2026-10-24 に試しで入れ、2026-10-25 に決定）
// ---------------------------------------------------------------------------
//
// 比べる綴り：
// - 写像（f は口が1つの関数か、可変長の口だけの関数）：`map $f xs`（`map : f [~l] ? [@f,] l~`。`$f` は指す関数を運ぶ番地で、`@f` は f そのもの、
//   `[@f,]` は f の写像）・`[f,] xs`・`[f,] xs~`。
// - 畳み込み（f は口が2つの関数）：`fold $f xs`（`fold : f [~h] ? @f h~`。撒いた流れを口が2つの関数が受ける左からの畳み込み）・`f xs~`。2026-10-25 の
//   R58（§5 Q58 の答え）から、合成全体の口が2つの合成 c も（`fold $[c] xs`・`c xs~`）。合成全体の口が3つ以上か分からない合成の流れは G19。
// - 書き下し（f は口が1つの関数。合成全体の口が1つの合成も、R58）：書いた List の `f X~` と、X の要素を書き並べた `f x1 x2 …`。
// なぜ同じか：`$f` の番地は指す関数を運ぶので、実体の中の `@f` は f と同じ関数（R49）。`[f,]` は f の写像（R50、U〔答え〕10-24 03:43）で、`[f,] xs`
// の xs は1つで入った器なのでその要素を写し（`[* 2,] \`ab\`` と同じ）、`[f,] xs~` は貪欲な単項の可変長の口が撒いた流れを丸ごと受けて写す
// （U [2026-10-25 07:37 2772473e]「[ink,] [1 2 3]~ が [2 3 4] になるのも大事だと思う。」）。撒いた並びは流れの1項で、関数は残りの口の数で受ける：
// 口が2つなら畳み込み、口が1つなら書き下し（R51。U [2026-10-25 07:24 2772473e]「…渡されたリストに後置~が指定される場合、 アリティ2の関数は
// 畳み込み演算と見做せる アリティ1の関数の後ろに , 演算子を置いた関数は、写像と見做せる。…」、U [2026-10-25 07:27 2772473e]「飽くまで、[+ 1,] [1 2 3]~
// が [2 3 4] であるべきで、 [+ 1] [1 2 3]~ は [2 2 3] になるはずだと答えたつもりだった。…」、主の Claude の問い「撒いた流れは、口2つなら畳み込み、
// 口1つなら書き下し（写像は `[f,]` だけ）。…」（07:29 UTC）に U〔答え〕[2026-10-25 07:34 2772473e]「そうか分かった！ map : f [~l] ? [@f,] l~ に対して、
// map $!_ .. と map $[!_] .. で分かれる。 安心した。」）。書き下しは流れの頭に当てて残りを積む（R47・R35）ので、書き並べた実引数と同じ並び。
// 何を同じと見るか：根が通るか断るか、通るなら根の種類、断るなら reason（門の番号と名指しは、実体の中で当たるかで綴りが違うので見ない）。
// 加えて、文脈 `inc (X)` に置いた答え（通るか断るかと種類）。書き下しの比べでは、木の綴りは違う（撒く項を書いたまま `(apply f X~)` と、書き並べた
// `(construct (apply f x1) x2 …)`）ので見ない。期待値は書かない。
// 実体の鍵：口が1つの f と g で、`map $f xs ⏎ map $g xs` の2行目の答えは、`map $g xs` 1行の答えと同じ（番地の印が鍵に入らないと、先に作った
// f の実体を g が黙って使う）。
// 比べの外：
// - 書き下しの空の List `[]`：空の流れの書き下しは G19（§5 Q57。何も書いていない `f` とも、単位 `_` とも読める）。
// - 書き下しの数の見えない流れ（`(inc 5)`・`(tl fs)`・`sv`・名前を通さない適用の結果）：書き並べる綴りが無い（流れの側は未知か G2(a)）。
// - 試しの版の `map2 : f [~t] ? @f t~` は、2026-10-25 の決定で写像ではなくなった（口が1つの `@f` の書き下しで、実体の中の t は数が見えないので未知）
//   ので、写像の比べから外した。合成の写像 `[c,] xs` と `c xs~`（書き下し）も、もう同じ物ではない（試しの版では §5 Q46 の比べの外だった）。
// - 恒等射：撒いた流れを丸ごと受ける（R29。口が1つではない）。
// 実装の外の片側（2026-10-24 の確かめで足した。写像と畳み込みの綴りは全部 mapOver・foldOver・elemsOfContainer の同じ道を通るので、それだけでは
// 両側の同じ誤りに盲目（寄生したオラクル）。反証で、中身の見えない器の畳み込みの黙った誤答 `first (tl fs)~ 5` がこの法則を通っていた）：
// - 写像と畳み込みの書き下し：書いた List（`[1 2 3]`・`[1 2]`・`5`・`[[1 2] [3 4]]`）の、写像は `f e` を要素ごとに1行ずつ、畳み込みは `f (f 1 2) 3` を
//   書いて解いた答え。流れの側が通るなら、根が A かは書き下しと同じ（流れの側が断るのは、断る側なので見ない）。口が1つの f の書き下しは上の
//   「書き下し」の比べそのもの（書き並べは畳み込みの道を通らない）。
// - R31 の1項の読み：素の2引数の関数（本体の根が A）の畳み込み `f X~` が A かは、`[|] X`（R31 の1項、foldOneKind。左を取る畳み込みで、
//   結果は要素の側の値）が A かと同じ。中身の見えない器（`(tl fs)`・`(inc 5)`）・構造体は、どちらも未知。空の括り `[]` は外す（R51 の空の流れは
//   `_` で A、R31 の1項の読みは空の括りを中身の見える List に数えない）。
const DEFS15 = [
	INC,
	"double : x ? x * 2",
	"add : x y ? x + y",
	"f2 : x y ? x - y",
	"k1 : x y ? x",
	"uu : x ? [,] x",
	"uu2 : x y ? [,] x",
	"f3 : a b c ? a + b + c",
	"adder : q ? $[+ q]",
	"pp : [a] y ? a + y",
	"pb2 : [a] [b] ? a + b",
	"hd : [y ~ys] ? y",
	"pq : x [b] ? x + b",
	"tl : [y ~ys] ? ys",
	"vs : 1 , 2 , 3",
	"ws : [1 2] [3 4]",
	"fs : inc , double",
	"sv :",
	"\tk : 1",
	"\tother : 2",
	"",
	"map : f [~l] ? [@f,] l~",
	"fold : f [~h] ? @f h~",
];
const UNITS15 = toUnits(DEFS15);
const at15 = (...lines) => outcome(src([...usedDefs(UNITS15, lines.join("\n")), ...lines]));
const ONE15 = ["inc", "double", "uu", "adder", "(add 1)", "(f3 1 2)", "[+ 1]", "[x ? x + 1]", "(pp [1])", "(k1 5)"];
const TWO15 = ["add", "f2", "k1", "uu2", "(f3 1)", "[<<]", "[x y ? x + y]", "pp", "pb2"];
const XS15 = ["vs", "[1 2 3]", "[]", "`ab`", "5", "(inc 5)", "ws", "sv", "fs", "[vs vs]", "(tl fs)"];
const VAR15 = ["hd", "[+]", "[' 0]", "(pq 1)"];
const FOLDPLAIN15 = ["add", "f2", "k1", "[x y ? x + y]", "(f3 1)"];
// 合成（2026-10-25 の §5 Q58 の答え、R58）：合成は1つの関数なので、撒いた流れは合成全体の口の数で受ける。合成全体の口が1つの合成（COMPOSE15）は
// 書き下しの比べに、口が2つの合成（COMPOSE15_TWO）は畳み込みの比べ（`fold $[c] xs` と `c xs~`）に入れる。口が3つ以上か分からない合成
// （COMPOSE15_MORE）は、流れの側が G19 であることだけを見る（R58 の文面の「3つ以上は G19」。§5 Q46）。答えの前（確かめの直し）は、`inc add`・`inc [+]`・
// `inc f3` を書き下しの比べに入れ、流れの側が G19（§5 Q58）なら数えて許していた。
const COMPOSE15 = ["inc double", "double inc", "[x ? x] inc"];
const COMPOSE15_TWO = ["inc add", "add inc", "[x ? x] add", "inc f2 double"];
const COMPOSE15_MORE = ["inc [+]", "inc f3", "add add"];
// 書き下しの List と要素（写像は要素ごと、畳み込みは左から、口が1つの関数は書き並べ）。空の List は書き下しの比べの外（§5 Q57）。
const WRITTEN15 = [
	["[1 2 3]", ["1", "2", "3"]],
	["[1 2]", ["1", "2"]],
	["5", ["5"]],
	["[[1 2] [3 4]]", ["[1 2]", "[3 4]"]],
];
const isA15 = (o) => !o.refused && !o.crash && lastOf(o).kind === "A";
const foldWritten15 = (f, es) => es.slice(1).reduce((acc, e) => `${f} ${acc === es[0] ? acc : `(${acc})`} ${e}`, es[0]);
// 関数の項の番地：名前は `$f`、括りは `$[…]`（`(add 1)` は `$(add 1)`。括りの種類は前段が残さないので同じ物）。
const ref15 = (f) => `$${f}`;
const ans15 = (o) => (o.crash ? `例外 ${o.crash}` : o.refused ? `断り ${o.refused.reason}` : `通る ${lastOf(o).kind}`);
law("15 撒いた並びは流れの1項：map $f xs・[f,] xs・[f,] xs~ と、fold $f xs・f xs~（口2つ）と、f xs~・f x1 x2 …（口1つ）", () => {
	const problems = [];
	const count = { 写像の組: 0, 可変長の口の写像の組: 0, 畳み込みの組: 0, 書き下しの組: 0, 通る: 0, 断る: 0, 実体の鍵の組: 0, 書き下しの写像の組: 0, 書き下しの畳み込みの組: 0, R31との組: 0 };
	count.書き下しより慎重 = 0; // 数えるだけ（0 でもよい。下の「組が無い」の確かめに入れない）
	count.合成の畳み込みの組 = 0; // COMPOSE15_TWO（R58）
	count.合成全体の口が3つ以上でG19の組 = 0; // COMPOSE15_MORE（R58）
	const sigOf = (x) => [x, ans15(at15(x)), ans15(at15(`inc (${x})`))];
	const sig = (r) => `${r[1]} / 文脈 ${r[2]}`;
	const compare = (label, forms) => {
		const outs = forms.map(sigOf);
		for (const [x, a] of outs) if (a.startsWith("例外")) problems.push(`例外：${x}`, `  ${a}`);
		if (outs.some((r) => sig(r) !== sig(outs[0]))) {
			problems.push(`${label}：答えが割れた`, ...outs.map((r) => `  ${r[0]}  →  ${sig(r)}`));
			return;
		}
		if (outs[0][1].startsWith("断り")) count.断る++;
		else count.通る++;
	};
	// 写像：`[f,]` の写像だけ（R50）。`map $f xs`・`[f,] xs`・`[f,] xs~`。
	// 空の List（2026-10-27 の片6 の R95、§5 Q75 (b) の点なしの所の答え）：写像の可変長の口に来た空の流れは書いた `_` と同じで、点なしの関数が残る。`map $f []` の
	// `[@f,] l~` は実体の本体の根なので、流れの側も本体の根に置いた `[y9 ? [f,] []~] 1` と比べる（下の畳み込みの flow15 と同じ置き場の違い。本体の根に `[f,]` が残れば
	// R33 の G16）。書いた `[]` を写像の口に置いた `[f,] []` は、R94 の外（可変長の口は器を受ける）で空の List の写像のまま、`[f,] []~` と木が割れる（値はどちらも `_`）。
	// 決定の文が両側を決めた割れ（§5 Q75 (b) の残り）なので比べの外に置き、錨で今の答え（通る A）を見る。片5 までは3つとも空の List の写像で A だった。
	const map15 = (f, xs) => (xs === "[]" ? [`map ${ref15(f)} []`, `[y9 ? [${f},] []~] 1`] : [`map ${ref15(f)} ${xs}`, `[${f},] ${xs}`, `[${f},] ${xs}~`]);
	const anchorEmpty15 = (f) => {
		count.空のListの写像の錨 = (count.空のListの写像の錨 || 0) + 1;
		const a = ans15(at15(`[${f},] []`));
		if (a !== "通る A") problems.push(`錨 [${f},] []：${a}（R94 の外の器で、通る A のはず）`);
	};
	for (const f of ONE15) {
		for (const xs of XS15) {
			count.写像の組++;
			compare(`写像 ${f} ${xs}`, map15(f, xs));
			if (xs === "[]") anchorEmpty15(f);
		}
	}
	for (const f of VAR15) {
		for (const xs of XS15) {
			count.可変長の口の写像の組++;
			compare(`可変長 ${f} ${xs}`, map15(f, xs));
			if (xs === "[]") anchorEmpty15(f);
		}
	}
	// 空の List（2026-10-27 の R84、§5 Q69 の答え）：空の流れは書いた `_` と同じで、末尾の `_` が消えて関数が残る。`fold $f []` の `f h~` は実体の本体の根なので、
	// 流れの側も本体の根に置いた `[y9 ? f []~] 1` と比べる（本体の根に関数が残れば R33 の G16、行の根なら R42 の `_` で、置き場の違い。前は空の流れの畳み込みで
	// どちらも `_`）。
	const flow15 = (f, xs) => (xs === "[]" ? `[y9 ? ${f} []~] 1` : `${f} ${xs}~`);
	for (const f of TWO15) {
		for (const xs of XS15) {
			count.畳み込みの組++;
			compare(`口2 ${f} ${xs}`, [`fold ${ref15(f)} ${xs}`, flow15(f, xs)]);
		}
	}
	// 合成全体の口が2つの合成（R58）：`fold $[c] xs` と `c xs~`（どちらも合成全体を2引数の関数として畳む）。
	for (const c of COMPOSE15_TWO) {
		for (const xs of XS15) {
			count.合成の畳み込みの組++;
			compare(`合成の口2 ${c} ${xs}`, [`fold $[${c}] ${xs}`, flow15(c, xs)]);
		}
	}
	// 合成全体の口が3つ以上か分からない合成（R58）：流れの側は G19。
	for (const c of COMPOSE15_MORE) {
		for (const [xs] of WRITTEN15) {
			count.合成全体の口が3つ以上でG19の組++;
			const so = at15(`${c} ${xs}~`);
			if (!so.refused || so.refused.gate !== "G19") problems.push(`合成全体の口が3つ以上：${c} ${xs}~ は ${ans15(so)}（R58 の文面では G19）`);
		}
	}
	// 書き下し：口が1つの f の `f X~` と、X の要素を書き並べた `f x1 x2 …`（R51、2026-10-25）。合成全体の口が1つの合成も（R58）。
	for (const [xs, es] of WRITTEN15) {
		for (const f of [...ONE15, ...COMPOSE15]) {
			count.書き下しの組++;
			compare(`書き下し ${f} ${xs}`, [`${f} ${xs}~`, `${f} ${es.join(" ")}`]);
		}
	}
	// 実装の外の片側：写像と畳み込みの書き下し。
	for (const [xs, es] of WRITTEN15) {
		for (const f of [...ONE15, ...VAR15]) {
			const viaMap = at15(`[${f},] ${xs}`);
			if (viaMap.refused || viaMap.crash) continue;
			count.書き下しの写像の組++;
			const written = es.every((e) => isA15(at15(`${f} ${e}`)));
			if (isA15(viaMap) !== written) problems.push(`書き下し：[${f},] ${xs} は ${ans15(viaMap)}、要素ごとの ${es.map((e) => `${f} ${e}`).join("・")} は${written ? "全部 A" : "A でない物がある"}`);
		}
		for (const f of TWO15) {
			const viaStream = at15(`${f} ${xs}~`);
			if (viaStream.refused || viaStream.crash) continue;
			count.書き下しの畳み込みの組++;
			const w = foldWritten15(f, es);
			const written = at15(w);
			// 片向き：流れの側が A なら、書き下しも A（黙って値と読まない）。流れの側が未知で書き下しが A なのは、流れの側が長さを見ない
			// （形 `[N…]` は長さを持たないので、要素1つ（f を当てない）・2つ・3つ以上（前の結果を左に当て直す）のどれでも A のときだけ A）ための
			// 慎重な答えで、数えるだけにする（`pp [1 2]~`・`uu2 5~`）。
			if (isA15(viaStream) && !isA15(written)) problems.push(`書き下し：${f} ${xs}~ は ${ans15(viaStream)}、${w} は ${ans15(written)}`);
			else if (!isA15(viaStream) && isA15(written)) count.書き下しより慎重++;
		}
	}
	// 実装の外の片側：R31 の1項の読み（左を取る畳み込み `[|] X`）。
	for (const f of FOLDPLAIN15) {
		for (const xs of XS15) {
			if (xs === "[]") continue;
			const viaStream = at15(`${f} ${xs}~`);
			if (viaStream.refused || viaStream.crash) continue;
			count.R31との組++;
			const r31 = at15(`[|] ${xs}`);
			if (isA15(viaStream) !== isA15(r31)) problems.push(`R31：${f} ${xs}~ は ${ans15(viaStream)}、[|] ${xs} は ${ans15(r31)}`);
		}
	}
	// 実体の鍵：違う関数の番地で同じ map を続けて呼ぶ。2行目の答えが1行で解いた答えと同じ（どちらの順でも）。
	for (const f of ONE15) {
		for (const g of ONE15) {
			if (f === g) continue;
			// 1行目（f）が断るなら2行目は見えない（f の答えは上の写像の組で見てある）。
			const first = at15(`map ${ref15(f)} vs`);
			if (first.refused || first.crash) continue;
			count.実体の鍵の組++;
			const two = at15(`map ${ref15(f)} vs`, `map ${ref15(g)} vs`);
			const a = ans15(two);
			const b = ans15(at15(`map ${ref15(g)} vs`));
			if (a !== b) problems.push(`実体の鍵：map ${ref15(f)} vs ⏎ map ${ref15(g)} vs の2行目  →  ${a}、1行なら ${b}`);
		}
	}
	for (const [k, v] of Object.entries(count)) if (!v && k !== "書き下しより慎重") problems.push(`「${k}」の組が無い（法則がその枝を見ていない）`);
	return { problems, note: Object.entries(count).map(([k, v]) => `${k} ${v}`).join("・") };
});

// ---------------------------------------------------------------------------
// 法則16：括りの中で値の上に積まれて閉じた関数は、括りを外して根に置いたときと同じく消える（R52、2026-10-24）
// ---------------------------------------------------------------------------
//
// 比べる綴り：値 X の後ろに、口の開いたまま閉じる関数 F を書いて括った `(X F)` を文脈 C に置いた `C[(X F)]` と、`(X F)` を X に替えた `C[X]`
// （`(X F) Y` と `X Y`・`G (X F)` と `G X`・`(X F) == 6` と `X == 6`・`(X F) , 1` と `X , 1`・`pp (X F) 1` と `pp X 1`・本体の中・名前の右辺の
// 括り）。加えて (a) 根に置いた `X F` と `(X F)`。
// なぜ同じか：逆適用は廃止した（R47）ので、値の後ろに積まれた F は X を取らず、括りが閉じた後に括りの外の項を受ける道も無い（`(5 inc) 3` の 3 は
// 括りの外の項）。だから F は、根に置いたとき（R42・R48）と同じく余ったラムダで、`_` になり、構築の中では消える（R15）：`(X F)` は `(X _)` と
// 同じで、`(X _)` は X（R15。1項の並びはその項、[x] ≅ x）。主の Claude の問い「値の後ろで何も受けずに閉じた関数は、`:` の右辺を除くどこでも、
// 余ったラムダとして `_` にして知らせる、でいい？」に U〔答え〕[2026-10-24 06:32 ebf18260]「もちろん！」（R52）。
// 何を同じと見るか：全部の行の木（`C[(X F)]` の括りの葉 `[X F]` を X の綴りに直した物。括りの関数の定義の行の実体の形も、だから同じでなければ
// ならない）・種類・門と名指し、ほかの診断。`C[(X F)]` の側にだけ、leftover-lambda が1つ多い（F が恒等射なら同じ数、R48）。(a) では、根の
// `X F` と `(X F)` が、どちらも A で、同じ名前の leftover-lambda を出す（F が恒等射なら出さない）。期待値は書かない。
// 比べの外：X が撒く項（`vs~`）なら、`(vs~)` は括りで撒く印が閉じる（括りの値は器で、`inc (vs~)` は R51 の写像にならない）ので、X ではなく
// `(X)` に替えた物と比べる。
// 名前の右辺に括らずに書いた `w : X F` ⏎ `C[w]` も、`C[(X F)]` と同じ（最後の行の種類と門、診断。名前の葉は開けないので木は比べない）：名前は
// 右辺を閉じた1つの項として指し、右辺にも R52 を当てる（2026-10-24 の §5 Q50 の答え。F は定義の行で知らせるので、診断の数も同じ）。その答えの
// 前は、左が名前1つの `:` の右辺の並びは R52 の外で、w は未知だった（名前の右辺の括り `v : (X F)` だけを比べていた）。
// `$[…]` の中身（2026-10-24 の §5 Q52 の答え。同じ日の確かめの指摘で足した）：(b) `$[X F]`・`$[X F , !_]` を文脈 D に置いた物と、F を除いた
// `$[X]` を置いた物が同じ（最後の行の種類と門、診断）。`$` は物にする＝遅延なので、書いた所では中身の並びを判定しない（主の Claude「`$` は
// 「物にする＝遅延」なので、`$[…]` を書いた所では中身を評価しない。評価しない所で「余った」と判定するのは筋違いだね。」（09:48 UTC）に、
// U〔答え〕[2026-10-24 09:49 ebf18260]「全てその方向で良いと思う。」）。`, !_` は恒等射で消えて残った中身の並び（R45 で `X F` と同じ）。
// (c) 開く所の `@[X F]` を文脈 E に置いた物と、`(X F)` に替えた物の診断が同じ（判定は `@` で開いた所でし、開いた所の読みは §5 Q50 の閉じた
// 1つの項。種類は比べない：中身が関数でない `@[…]` は前置 `@` の読みが決まっていない未知（§5 Q9）で、`(X F)` は A。前置 `@` が頭でない所は
// G6 なので E に置かない）。中身の項の中にも遅延が及ぶか（入れ子の括り・`?` の本体・中身の行の `:` の右辺）は §5 Q53 で決まっていないので、
// その形は比べない（F の括った物 `(add 1)`・`(inc !_)`・`(inc add)` は丸ごと関数で、どちらの読みでも余らない）。
// 同じ日の R53（`$` は関数だけを運ぶ、U〔答え〕[2026-10-24 12:34 ebf18260]「…だから全部の$で良いはずだ。」）で、(b) の3つの綴りは中身が関数で
// ないので、どれも G20 で書けなくなった（§5 Q53 と Q44 の残り その2 は閉じた）。(b) は、3つが同じ門で、それが G20 であることを見る。
// 2026-10-25 の R60（§5 Q54 の答え：`$` は Reader と Writer を作る接頭辞）から、値の中身の `$[X]` は値を読む参照として通るので、(b) は `$[X F]` と
// `$[X F , !_]` の2つが同じで、G20 であることを見る（遅延した中身の値と関数の積み上げは種類が決まらず、1つの Reader と言い切れない。R59 にも当たる）。
// 中身が関数の `$[B]` が `[B]` と同じ知らせを出すこと（遅延が中身の関数に効かないこと）は法則17 で見る。
// F には、何も受けない関数のほかに、値の上で何かを受けた後の関数（`add 1`）・穴の関数（`f2 !_`・`f2 _ 3`・`inc !_`）と、それを括った物
// （`(add 1)`・`(inc !_)`）・名前にした物（`p1 : add 1` の p1）も入れる。値の上に積まれたのは `(F Y)` の1項（法則5）なので、どれも R52 で
// 消える。R52 の最初の版は「何も受けない」を積み上げの項の中の記録で見ていて、`(5 add 1)` は未知・`(5 (add 1))` と `(5 p1)` は 5 と割れて
// いた。この表は前は実装と同じ「何も受けない関数」だけで選んでいたので、両側に同じ前提が乗って割れが見えなかった（2026-10-24 の確かめの指摘）。
const DEFS16 = [
	INC,
	"double : x ? x * 2",
	"add : x y ? x + y",
	"f2 : x y ? x - y",
	"n : [~x] ? x",
	"uu : x ? [,] x",
	"io1 : [say] ? say 21",
	"pp : [a] y ? a + y",
	"tl : [a ~r] ? r",
	"gd :",
	"\t\tys",
	"\t\tzs : 3",
	"\t? ys",
	"",
	"i : !_",
	"p1 : add 1",
	"vs : 1 , 2 , 3",
	...M,
];
const UNITS16 = toUnits(DEFS16);
const XS16 = ["5", "[1 2]", "vs", "(inc 5)", "m", "`ab`", "vs~"];
// F：素の関数（口1つ・2つ）・畳む点なし・単項の点なし・貪欲な単項・段18 の点なし・口の数の分からない点なし・ノルム・合成・括った合成・本体の根が
// 未知の関数・既定値のある関数・括りの関数・恒等射（知らせない）。値の上で受けた後の関数・穴の関数と、それを括った物・名前にした物（上の注）。
const FS16 = [
	"inc", "add", "f2", "[+]", "[+ 1]", "[* 2,]", "[' 0]", "[,]", "||inc||", "inc double", "(inc add)", "uu", "gd", "io1", "n", "!_", "i", "i i",
	"add 1", "(add 1)", "p1", "add 1 inc", "f2 !_", "f2 _ 3", "inc !_", "(inc !_)",
];
const IDENTITY16 = new Set(["!_", "i", "i i"]);
// 文脈：B は `(X F)` か、それを替えた物。
const CTX16 = [
	(b) => [b],
	(b) => [`${b} 3`],
	(b) => [`${b} 3 4`],
	(b) => [`${b} inc`],
	(b) => [`${b} inc 3`],
	(b) => [`3 ${b}`],
	(b) => [`inc ${b}`],
	(b) => [`add ${b} 1`],
	(b) => [`n ${b}`],
	(b) => [`[+] ${b} 2`],
	(b) => [`[' 0] ${b}`],
	(b) => [`[* 2,] ${b}`],
	(b) => [`${b} == 6`],
	(b) => [`6 == ${b}`],
	(b) => [`${b} , 1`],
	(b) => [`pp ${b} 1`],
	(b) => [`tl ${b}`],
	(b) => [`||${b}||`],
	(b) => [`t : y ? y ${b}`, "t 1"],
	(b) => [`v : ${b}`, "v 3"],
];
// (b) の文脈 D（`$[…]` を書いた所）と、(c) の文脈 E（`@[…]` で開く所）。
const DELAY16 = [
	(b) => [`$[${b}]`],
	(b) => [`p : $[${b}]`],
	(b) => [`use $[${b}] 3`],
	(b) => [`[$[${b}]]`],
	(b) => [`$[${b}] , 1`],
	(b) => [`t : y ? $[y ${b}]`, "t 1"],
];
const OPEN16 = [(a) => [a], (a) => [`${a} 3`], (a) => [`p : ${a}`], (a) => [`t : y ? ${a}`, "t 1"]];
const at16 = (lines, defsFrom) => outcome(src([...usedDefs(UNITS16, defsFrom), ...lines]));
// 最後の行の種類と門、診断（名前と括りの比べ。名前の葉は開けないので木は比べない）。
const lastView16 = (o) => (o.crash ? `例外 ${o.crash}` : o.refused ? `断り ${refusalText(o)}` : `${lastOf(o).kind} || ${o.diag.join(" ")}`);
// 門と診断（(c) の開く所の比べ。種類は比べない、上の注）。
const diagView16 = (o) => (o.crash ? `例外 ${o.crash}` : o.refused ? `断り ${refusalText(o)}` : o.diag.join(" "));
law("16 括りの中で値の上に積まれて閉じた関数は、括りを外して根に置いたときと同じく消える：C[(X F)] と C[X]、根の X F と (X F)、w : X F ⏎ C[w] と C[(X F)]、$[X F] と $[X]、@[X F] と (X F) の診断", () => {
	const problems = [];
	const count = {
		通る: 0,
		同じ門で断る: 0,
		"恒等射（知らせない）": 0,
		"(a) 根の X F と (X F)": 0,
		"撒く項は (X) と比べる": 0,
		"名前 w : X F と (X F)": 0,
		"(b) $[X F]・$[X F , !_] と $[X]（書いた所は遅延）": 0, // 2026-10-25 の R60 から `$[X F]` と `$[X F , !_]` の比べ（名前は前のまま）
		"(b) 恒等射の F は消えて $[X] と同じ（R72）": 0, // 2026-10-26 の R72（§5 Q63 の答え）から
		"(c) @[X F] と (X F) の診断（開く所）": 0,
	};
	for (const x of XS16) {
		for (const f of FS16) {
			const b = `(${x} ${f})`;
			// 撒く項は `(X)` と比べる（上の注）。文字列の字面も `(X)` に替える：行頭のバッククォートはコメント（string_and_comment）なので、
			// `` `ab` 3 `` は1行に置けない。
			const p = x.endsWith("~") || x.startsWith("`") ? `(${x})` : x;
			if (x.endsWith("~")) count["撒く項は (X) と比べる"]++;
			// 括りの葉と、替えた物の木の綴り（名前の右辺に置いて解いた綴り。行頭のバッククォートはコメントなので、1行には置かない）。
			const rhsText = (t) => {
				const o = at16([`v : ${t}`], t);
				const s = o.trees ? lastOf(o).text : "";
				return s.startsWith("(: v ") ? s.slice(5, -1) : null;
			};
			const bText = rhsText(b);
			const pText = rhsText(p);
			if (!bText || !pText) {
				problems.push(`${b}・${p} の綴りが取れない: ${bText}・${pText}`);
				continue;
			}
			// (a) 根の X F と (X F)：どちらも A で、同じ名前の leftover-lambda（恒等射なら無し）。
			{
				count["(a) 根の X F と (X F)"]++;
				const names = (s) => {
					try {
						const r = resolve(src([...usedDefs(UNITS16, s), s]));
						return { kind: kindOf(r.trees[r.trees.length - 1]), left: r.diagnostics.filter((d) => d.reason === "leftover-lambda").map((d) => d.name) };
					} catch (e) {
						return { kind: `断り ${e.reason} ${e.gate || ""}`, left: [] };
					}
				};
				const root = names(`${x} ${f}`);
				const br = names(b);
				const want = IDENTITY16.has(f) ? 0 : 1;
				if (root.kind !== "A" || br.kind !== "A" || JSON.stringify(root.left) !== JSON.stringify(br.left) || br.left.length !== want) {
					problems.push(`(a) ${x} ${f}  ⇔  ${b}`, `  根: ${root.kind} ${JSON.stringify(root.left)}`, `  括り: ${br.kind} ${JSON.stringify(br.left)}`);
				}
			}
			for (const ctx of CTX16) {
				const bl = ctx(b);
				const pl = ctx(p);
				const defsFrom = [...bl, ...pl].join("\n");
				const ob = at16(bl, defsFrom);
				const op = at16(pl, defsFrom);
				const label = `${bl.join(" ⏎ ")}  ⇔  ${pl.join(" ⏎ ")}`;
				// 名前の右辺に括らずに書いた `w : X F` ⏎ C[w] も、C[(X F)] と同じ（最後の行の種類と門、診断。上の注）。
				{
					const nl = [`w : ${x} ${f}`, ...ctx("w")];
					const on = at16(nl, [...nl, ...bl].join("\n"));
					count["名前 w : X F と (X F)"]++;
					if (lastView16(on) !== lastView16(ob)) problems.push(`${nl.join(" ⏎ ")}  ⇔  ${bl.join(" ⏎ ")}：名前は右辺を閉じた1つの項として指すので同じはず`, `  名前: ${lastView16(on)}`, `  括り: ${lastView16(ob)}`);
				}
				if (ob.crash || op.crash) {
					problems.push(label, `  括り: ${brief(ob)}`, `  替えた: ${brief(op)}`);
					continue;
				}
				if (ob.refused || op.refused) {
					if (!ob.refused || !op.refused || refusalText(ob) !== refusalText(op)) problems.push(label, `  括り: ${brief(ob)}`, `  替えた: ${brief(op)}`);
					else count.同じ門で断る++;
					continue;
				}
				const fix = (s) => s.split(bText).join(pText);
				const tb = ob.trees.map((t) => `${fix(t.text)} : ${t.kind}`).join(" | ");
				const tp = op.trees.map((t) => `${t.text} : ${t.kind}`).join(" | ");
				// 括りの側の診断から、leftover-lambda を1つ除く（F が恒等射なら除かない）。
				const db = [...ob.diag];
				if (!IDENTITY16.has(f)) {
					const k = db.indexOf("leftover-lambda");
					if (k < 0) problems.push(label, `  括りの側に F の leftover-lambda が無い: ${ob.diag.join(" ")}`);
					else db.splice(k, 1);
				} else count["恒等射（知らせない）"]++;
				if (tb !== tp || db.join(" ") !== op.diag.join(" ")) {
					problems.push(label, `  括り: ${tb.split(" | ").slice(-1)[0]} || ${ob.diag.join(" ")}`, `  替えた: ${tp.split(" | ").slice(-1)[0]} || ${op.diag.join(" ")}`);
					if (tb !== tp) problems.push(`  （木の違い）括り: ${tb.slice(0, 400)}`, `  （木の違い）替えた: ${tp.slice(0, 400)}`);
					continue;
				}
				count.通る++;
			}
			// (b) `$[…]` の中身の並びは遅延した式：D[$[X F]]・D[$[X F , !_]] と D[$[X]] が、最後の行の種類と門、診断で同じ（上の注）。
			// 2026-10-24 の R53（`$` は関数だけを運ぶ）から、中身の X F・X F , !_・X はどれも関数でないので、3つとも G20 で同じ（書けない）。
			// 同じことに加えて G20 であることを見る（前は3つとも通って、同じ種類と診断だった）。
			// 2026-10-25 の R60（`$` は Reader と Writer を作る接頭辞、§5 Q54 の答え）から、値の中身の `$[X]` は値を読む参照として通る（法則17 が `$X` と
			// `$[X]` と右辺で比べる）。遅延した中身の X F は判定しない値と関数の積み上げで、種類が決まらないので1つの Reader と言い切れず、今までどおり G20
			// （F が恒等射でない物は R59、§5 Q53 の答えの「中身のどこかで余る関数があれば G20」にも当たる）。だから比べる相手は `$[X F]` と `$[X F , !_]`
			// の2つで、どちらも G20 であることを見る（`$[X]` とは比べない）。
			// 2026-10-26 の R72（§5 Q63 の答え、U〔答え〕[2026-10-25 21:56 c8ccdd69]「自明な恒等射が残る場合、即時評価して消してもいい…だから $5と結果は同じだと思う。」）
			// から、F が恒等射（`!_`・`i`・`i i`）なら、値の上に余った恒等射は書いた所で即時に消えるので、`$[X F]`・`$[X F , !_]` は `$[X]` と同じ答え（`$[X]` とも比べる）。
			// F が恒等射でなければ今のまま、2つとも G20。
			for (const d of DELAY16) {
				const dls = [`${x} ${f}`, `${x} ${f} , !_`].map((body) => d(body));
				const idF = IDENTITY16.has(f);
				const ref = d(x);
				const defsFrom = [...dls.flat(), ...ref].join("\n");
				const [o1, o2] = dls.map((dl) => at16(dl, defsFrom));
				count["(b) $[X F]・$[X F , !_] と $[X]（書いた所は遅延）"]++;
				if (lastView16(o1) !== lastView16(o2)) problems.push(`(b) ${dls[0].join(" ⏎ ")}  ⇔  ${dls[1].join(" ⏎ ")}：恒等射で消えて残った中身の並びは同じはず（R45）`, `  ${lastView16(o1)}`, `  ${lastView16(o2)}`);
				else if (idF) {
					count["(b) 恒等射の F は消えて $[X] と同じ（R72）"]++;
					const o3 = at16(ref, defsFrom);
					if (lastView16(o1) !== lastView16(o3)) problems.push(`(b) ${dls[0].join(" ⏎ ")}  ⇔  ${ref.join(" ⏎ ")}：値の上に余った恒等射は即時に消えるので同じはず（R72）`, `  ${lastView16(o1)}`, `  ${lastView16(o3)}`);
				} else if (!o1.refused || o1.refused.gate !== "G20") problems.push(`(b) ${dls[0].join(" ⏎ ")}：遅延した中身の値と関数の積み上げは G20 のはず（R53・R59・R60）`, `  ${lastView16(o1)}`);
			}
			// (c) 開く所の `@[X F]` と、括った `(X F)` の門と診断が同じ（上の注。種類は比べない）。
			for (const e of OPEN16) {
				const al = e(`@[${x} ${f}]`);
				const bl = e(b);
				const defsFrom = [...al, ...bl].join("\n");
				const oa = at16(al, defsFrom);
				const obr = at16(bl, defsFrom);
				count["(c) @[X F] と (X F) の診断（開く所）"]++;
				if (diagView16(oa) !== diagView16(obr)) problems.push(`(c) ${al.join(" ⏎ ")}  ⇔  ${bl.join(" ⏎ ")}：判定は開く所で、閉じた1つの項と同じはず`, `  開く: ${diagView16(oa)}`, `  括り: ${diagView16(obr)}`);
			}
		}
	}
	for (const [k, v] of Object.entries(count)) if (!v) problems.push(`「${k}」の組が無い（法則がその枝を見ていない）`);
	return { problems, note: Object.entries(count).map(([k, v]) => `${k} ${v}`).join("・") };
});

// ---------------------------------------------------------------------------
// 法則17：`$` は関数だけを運ぶ（R53・G20、2026-10-24）
// ---------------------------------------------------------------------------
//
// 比べる綴り：
// (a) 名前 N の `$N` と、括った `$[N]` を文脈 C に置いた `C[$N]` と `C[$[N]]`。[x] ≅ x（1項の括りはその項）なので同じ。仮引数の名前（素の関数の
//     裸の仮引数・括りの関数の実体で欄に受けた名前）も同じに比べる。
// (b) ファイルの定義 `N : R` の右辺を開いた `$[R]` を置いた `C[$[R]]` と `C[$N]`。`:` はメタで、名前は右辺を指す（§5 Q50 の答えで、右辺は閉じた
//     1つの項）。`?` の定義の右辺は、括った `?`（`$[x ? x + 1]`）。
// (a') 名前でない先 X（字面・番地・囲み・値の印の項・後置の印の項。2026-10-24 の確かめの直し）の `$X` と `$[X]`。[x] ≅ x で同じ。最初の版は名前だけを
//     比べていて、括らない `$5`・`$$inc`・`$vs~` が未知のまま通り、括った `$[5]`・`$[$inc]`・`$[vs~]` が G20 で割れていたのが見えなかった。
// (c) 括りの中身 B：`p : $[B]` が通るのは `p : [B]` の右辺が関数（L）のときだけで、通るなら診断が同じ。`p : [B]` が断るなら、同じ門で断る。
//     中身が関数なら、`$[…]` の中身の並びの遅延（R52 の判定をしない、§5 Q52 の答え）は効かない（値の上に積まれて閉じた関数が中身の並びに残らない）。
//     通るときの診断の一致のうち、中身の項の中（`$[add (5 inc)]`）と `?` の本体（`$[x ? x inc]`）の分は §5 Q53 の今の読み (1)（中身の項の中は
//     今のまま当てる）で、法則ではない（2026-10-24 の確かめで、R53 の片の「Q53 は閉じた」を直した。Q53 の答えが (2) なら、その分の比べを外す）。
//     「関数か」は `[B]` の側を同じ解決器で解いて決めるので、両側が括りの分類を共有する。だから R53 の文面の例（ANCHOR17）では、関数かを
//     規則の側に書いて、`[B]` の分類そのものも見る（2026-10-24 の確かめの指摘）。2026-10-25 の R56 から、中身が書いた `_` の `$[_]` は、`[_]` が
//     値でも零射 `$[x ? _]` の番地で通る（`_` を `[x ? _]` と読むのは `$` で物にする所だけ）。その1つは「通り、診断が同じ」で見る。
// 何を同じと見るか：最後の行の種類と門と名指し、診断（leftover-lambda は出たかだけ。outcome）。期待値は書かない（(c) の「関数のときだけ通る」は
// 規則の文面で、関数かは `[B]` の側を解いて決める。ANCHOR17 だけは R53 の文面の例を書く）。
// なぜ同じか：主の Claude の問い「`$` の縛りは、全部の `$` にかける？ それとも `$[…]` の中身だけ？」（12:26 UTC）に、U〔答え〕[2026-10-24 12:34
// ebf18260]「そもそも、識別子で名前がついているものも関数か否かについては区分可能。 / だから全部の$で良いはずだ。」。名前と括りと右辺で `$` の
// 当たり方が割れれば、「全部の `$`」が書き方で変わる。
// 比べの外：
// - `i : !_` の右辺は開かない：括った `[!_]` は否定の点なしで、恒等射ではない（R29）。`$i` と括らない `$!_` は法則18 で比べる。
// - `!!_` も括ると否定の点なしなので入れない。
// 2026-10-25（R54〜R57、§7.29）に比べを締めた所：
// - 別名（値の定義で右辺が関数：`p1 : inc`・`c1 : inc double`・`a1 : add 1`・`i : !_`）の `$N` は、R53 の片では指す関数の印を持たず（§5 Q45）、
//   印を読む文脈（`map $p1 vs`）で `$[p1]`・`$[inc]` と割れたので、通るか G20 かだけを比べて割れを数えていた。R55 で別名の `$N` も印を持つので、
//   ほかの名前と同じく答えの全部を比べる。恒等射の別名 `i` は、R55 の片では印を持たず（§5 Q56）、同じ日の Q56 の答えから1引数の恒等射の印を持つ。
//   どちらでも `$i` と `$[i]` は同じ先なので比べは同じ。
// - (a') の先が関数で表に無い組み合わせ（`$||inc||`・`$||!_||`）は、R53 の片では括らない綴りが未知のまま（§5 Q55）で割れを数えていた。R57 で
//   `$[…]` と同じく通るので、ほかの先と同じく答えの全部を比べる。
// - 書いた `_` の `$_` と `$[_]` は、R53 の片では両方 G20 で同じだった。R56 で両方とも零射 `$[x ? _]` の番地で、同じ（通る）。
// 2026-10-25（R59・R60、§7.33）に広げた所（法則の名前は前のまま）：
// - R60（`$` は Reader と Writer を作る接頭辞、§5 Q54 の答え）から、値の名前（`vs`・`five`・`st`・`pa`・`zz`）・値の右辺・名前でない値の先の `$X` は、
//   値を読む参照として通る。(a)(b)(a') の比べは今までどおりで、R53 の片では G20 どうしの比べだった組が、通る答えどうしの比べになった（値へ広げた）。
// 2026-10-27（片8、R99〜R101、§7.49）に変えた所（法則の名前は前のまま）：
// - `$` は必ず持ち上げ（R99）。値の先は通って warning の dollar-non-function（R100）、先の種類の分からない先も持ち上げで通る（前は G20）。診断は出たかどうかだけ
//   比べる（diagKeys）。(c) の規則は、値なら `[B]` の診断に警告を足した物、未知なら `[B]` と同じ診断で通る、に変えた。
// - 書いた `,` の積（単位律の後にも `,` が残る、product17）の `$[B]` は G20（R101）。名前を通した積は警告で通るので、(b) の右辺が積の組は比べず、規則の側の答え
//   （開いた側は G20、名前の側は G20 でない）を見る。
// - (c) の規則：`[B]` の右辺に余るラムダ（R59：中身のどこかに余る関数）があるか、B が後置の印の付いた項1つ（R57）なら `$[B]` は G20。ほかで `[B]` が関数か
//   値なら通り、診断は `[B]` と同じ。未知なら G20。錨（ANCHOR17）は R59・R60 の文面の例に書き直した。
const DEFS17 = [
	INC,
	"double : x ? x * 2",
	"add : x y ? x + y",
	"f3 : a b c ? a + b + c",
	"uu : x ? [,] x",
	"adder : q ? $[+ q]",
	"hd : [y ~ys] ? y",
	"i : !_",
	"p1 : inc",
	"c1 : inc double",
	"a1 : add 1",
	"vs : 1 , 2 , 3",
	"five : 5",
	"st : [k : 1]",
	"pa : $inc",
	"un : _",
	"use : f x ? @f x",
	"map : f [~t] ? [@f,] t~",
	"fold : f [~h] ? @f h~",
];
const UNITS17 = toUnits(DEFS17);
// [名前, 右辺（開けない物は null）, 別名か]
const NAMES17 = [
	["inc", "x ? x + 1", false],
	["add", "x y ? x + y", false],
	["f3", "a b c ? a + b + c", false],
	["uu", "x ? [,] x", false],
	["adder", "q ? $[+ q]", false],
	["hd", "[y ~ys] ? y", false],
	["i", null, true],
	["p1", "inc", true],
	["c1", "inc double", true],
	["a1", "add 1", true],
	["vs", "1 , 2 , 3", false],
	["five", "5", false],
	["st", "[k : 1]", false],
	["pa", "$inc", false],
	["zz", null, false], // 未定義の名前（前は R21 の値。2026-10-28 の片9b の R111 から `_` で、`$zz`・`$[zz]` は `$un` と同じ零射の番地）
	// 書いた `_`（名前ではないが、`$_` と `$[_]` は [x] ≅ x で同じ。2026-10-25 の R56 から、どちらも零射 `$[x ? _]` の番地で通る。R53 の片では
	// 印＝値でどちらも G20）。`!_` は括ると否定の点なし（R29）なので入れない。
	["_", null, false],
	// `_` を右辺に持つ名前（R56）：`$un` と `$[un]` と、右辺を開いた `$[_]`。
	["un", "_", false],
];
const CTX17 = [
	(t) => [t],
	(t) => [`p : ${t}`, "p"],
	(t) => [`use ${t} 5`],
	(t) => [`map ${t} vs`],
	(t) => [`fold ${t} vs`],
	(t) => [`[${t}]`],
	(t) => [`${t} , 1`],
	(t) => [`||${t}||`],
	// 仮引数は u（右辺を開いた `$[x y ? x + y]`・`$[[y ~ys] ? y]` の仮引数が外の仮引数を隠すと、比べる片方の綴りにだけ name-shadow の知らせが出る。寄せ3 の R133 の前は P2 で断った）。
	(t) => [`t : u ? ${t}`, "t 1"],
	(t) => [`t : u ? use ${t} u`, "t 1"],
];
// 仮引数の名前の文脈：[名前, 仮引数, 項を置く行を作る関数]。
const PARAM17 = [
	["素の関数の裸の仮引数 y", "y", (t) => [`t : y ? ${t}`, "t 1"]],
	["欄で関数を受けた s", "s", (t) => [`hb : [s] ? use ${t} 1`, "hb [s : inc]"]],
	["欄で数を受けた s", "s", (t) => [`hb : [s] ? use ${t} 1`, "hb [s : 5]"]],
	["欄で関数を受けた s を返す", "s", (t) => [`hb : [s] ? ${t}`, "hb [s : add]"]],
	["番地を受けた裸の仮引数 f", "f", (t) => [`tw : f [~r] ? map ${t} r`, "tw $inc vs"]],
];
// (a') の名前でない先：[先, 先が関数で表に無い組み合わせか（R53 の片の §5 Q55。2026-10-25 の R57 から数えるだけで、比べ方はほかと同じ）]。
const NONNAME17 = [
	["5", false],
	["0x10", false],
	["`ab`", false],
	["$inc", false],
	["$vs", false],
	["|5|", false],
	["-5", false],
	["-inc", false],
	["!5", false],
	["~vs", false],
	["vs~", false],
	["5~", false],
	["5!", false],
	["||inc||", true],
	["||!_||", true],
];
// (c) の錨：R53 の文面の例で、中身が関数か（§4 R53 の「括りの種類」と §6.2 の G20 の行）。2026-10-25 の R59・R60 から、[B の綴り, `[B]` の種類, `$[B]` が
// 通るか]：先が値なら値を読む参照として通り（R60。R53 の文面では G20）、中身のどこかに余る関数があれば G20（R59。R53 の片では関数なら通った）。
const ANCHOR17 = [
	["+ 1", "L", true],
	["inc double", "L", true],
	["add 1", "L", true],
	["f3 !_ 2", "L", true],
	["x ? x + 1", "L", true],
	[",", "L", true],
	["inc , !_", "L", true],
	["5 inc", "A", false], // 括りの中は R52 で 5。`$[…]` の中身の並びは遅延した積み上げで種類が決まらない（Q52）
	["1 2", "A", true], // R60（R53 の文面では G20）
	["inc 5", "A", true], // R60
	["uu 5", "U", true], // 2026-10-27 の片8 の R99：先の種類の分からない持ち上げで通る（前は G20）
	["inc , double", "A", false], // 2026-10-27 の片8 の R101：書いた `,` の積の `$` は断る（前は値を読む参照で通った）
	["five , 1 , _", "A", false], // R101：単位律の後にも `,` が残る
	["5", "A", true], // R60
	["vs", "A", true], // R60
	["$inc", "A", true], // R60（番地を読む参照）
	["k : 5 inc", "A", false], // R59（欄の右辺に余る関数）
	["x ? x inc", "L", false], // R59（`?` の本体に余る関数。R53 の片では通った）
	["add (5 inc)", "L", false], // R59（R53 の片では通った）
	["vs~", "A", false], // R57（[x] ≅ x で `$vs~` と同じ）
];
// 括りの中身 B（(c)）。関数・値・積み上げ・欄・枝・中置・恒等射・印・番地。2026-10-25 の R59 から、中身の項の中に余る関数のある物（`add (5 inc)`・`f3 (5 inc)`）も。
const BODIES17 = [
	"inc", "inc double", "add 1", "+ 1", "* 2,", "[+]", ",", "uu", "hd", "!_", "inc , !_", "!_ , inc", "inc add 5", "f3 !_ 2", "x ? x inc", "x ? x + 1",
	"x ? 5 inc", "[x ? x inc]", "inc inc inc", "@inc", "5 inc", "(5 inc)", "5 inc , !_", "k : 5 inc", "5 > 1 : 5 inc", "5 inc == 6", "(5 inc) 3", "1 2",
	"vs", "uu 5", "inc 5", "_", "5", "$inc", "5 add 1", "!_ == 1", "inc vs~", "vs~", "add (5 inc)", "f3 (5 inc)", "add (5 !_)", "_ , 5",
	// 2026-10-27 の片8 の R101：単位律の後にも `,` が残る積と、単位律で1項に縮む積
	"inc , double", "five , 1 , _", "five , 1", "inc , i", "i , five", "_ , !_",
];
// 後置の印の付いた項1つの中身（R57・R60：[x] ≅ x で、括らない `$x~` と同じく G20）。
const POSTFIX17 = new Set(["vs~"]);
// 中身 B が、単位律（R45・R61・R71：`_`・`!_`・恒等射の名前 `i` は `,` の単位）の後にも `,` の残る書いた積か（2026-10-27 の片8 の R101。規則の側で、書いた綴りから数える。
// B はいちばん外の `,` で切れる綴りだけを並べている）。
const product17 = (b) => b.includes(" , ") && b.split(" , ").filter((x) => !["_", "!_", "i"].includes(x.trim())).length >= 2;
const view17 = (o) => (o.crash ? `例外 ${o.crash}` : o.refused ? `断り ${refusalText(o)}` : `${lastOf(o).kind} || ${o.diag.join(" ")}`);
const r53Of17 = (o) => (o.crash ? `例外 ${o.crash}` : o.refused && o.refused.gate === "G20" ? "G20" : "G20 でない");
const at17 = (lines) => outcome(src([...usedDefs(UNITS17, lines.join("\n")), ...lines]));
law("17 `$` は関数だけを運ぶ（R53）：C[$N] と C[$[N]] と C[$[右辺]]、p : $[B] は [B] が関数のときだけ通り、通れば同じ診断", () => {
	const problems = [];
	const count = {
		"(a) $N と $[N]": 0,
		"(b) $N と $[右辺]": 0,
		"(a) 仮引数の $N と $[N]": 0,
		"通る組": 0,
		"G20 の組": 0,
		"別名の組（R55 から答えの全部）": 0,
		"(c) 中身が関数で通る": 0,
		"(c) 中身の種類が分からず持ち上げで通る（R99）": 0,
		"(c) 中身が断る（同じ門）": 0,
	};
	count["(a') 名前でない先の $X と $[X]"] = 0;
	count["(a') 先が関数の組み合わせ（R57 から答えの全部）"] = 0;
	count["(c) 錨（R53 の文面の例）"] = 0;
	// alias・fnCombo は数えるための印（2026-10-25 の R55・R57 から、比べ方はほかの組と同じ。R53 の片では、通るか G20 かだけ・未知のままかだけを見ていた）。
	const pair = (label, a, b, alias, fnCombo = false) => {
		const oa = at17(a);
		const ob = at17(b);
		if (oa.crash || ob.crash) {
			problems.push(`${label}：例外`, `  ${a.join(" ⏎ ")} → ${view17(oa)}`, `  ${b.join(" ⏎ ")} → ${view17(ob)}`);
			return;
		}
		if (alias) count["別名の組（R55 から答えの全部）"]++;
		if (fnCombo) count["(a') 先が関数の組み合わせ（R57 から答えの全部）"]++;
		if (view17(oa) !== view17(ob)) {
			problems.push(`${label}：答えが割れた`, `  ${a.join(" ⏎ ")} → ${view17(oa)}`, `  ${b.join(" ⏎ ")} → ${view17(ob)}`);
			return;
		}
		if (r53Of17(oa) === "G20") count["G20 の組"]++;
		else count["通る組"]++;
	};
	for (const [n, rhs, alias] of NAMES17) {
		for (const c of CTX17) {
			count["(a) $N と $[N]"]++;
			pair(`(a) ${n}`, c(`$${n}`), c(`$[${n}]`), alias);
			if (rhs !== null && product17(rhs)) {
				// 2026-10-27 の片8 の R101：右辺が書いた `,` の積（単位律の後にも `,` が残る）なら、開いた `$[右辺]` は書いた積の `$` で G20、名前を通した `$N` は名前の先の
				// 値の持ち上げで通る（R100 の警告）。決定の文が書いた綴りで分けた所（U [2026-10-27 10:24 58a809c9]「この段階で,がついてるので無し。」）なので、
				// 同じ答えは比べず、規則の側の答え（開いた側は G20、名前の側は G20 でない）を見る。
				count["(b) 右辺が書いた `,` の積（R101、開いた側だけ G20）"] = (count["(b) 右辺が書いた `,` の積（R101、開いた側だけ G20）"] || 0) + 1;
				const oo = at17(c(`$[${rhs}]`));
				const on = at17(c(`$${n}`));
				if (!oo.refused || oo.refused.gate !== "G20") problems.push(`(b) ${n} : ${rhs}：開いた \`$[右辺]\` は書いた積の G20 のはず（R101）`, `  ${view17(oo)}`);
				if (on.refused && on.refused.gate === "G20") problems.push(`(b) ${n} : ${rhs}：名前を通した \`$N\` は G20 でないはず（R100）`, `  ${view17(on)}`);
			} else if (rhs !== null) {
				count["(b) $N と $[右辺]"]++;
				pair(`(b) ${n} : ${rhs}`, c(`$${n}`), c(`$[${rhs}]`), alias);
			}
		}
	}
	for (const [label, p, c] of PARAM17) {
		count["(a) 仮引数の $N と $[N]"]++;
		pair(`(a) ${label}`, c(`$${p}`), c(`$[${p}]`), false);
	}
	for (const [x, fnCombo] of NONNAME17) {
		for (const c of CTX17) {
			// 囲みの先をノルムの文脈に置くと、`||$|5|||` は字句で読めない（構文の誤りで、解決器の答えではない）ので外す。
			if (x.includes("|") && c("X")[0] === "||X||") continue;
			count["(a') 名前でない先の $X と $[X]"]++;
			pair(`(a') ${x}`, c(`$${x}`), c(`$[${x}]`), false, fnCombo);
		}
	}
	// (c) の錨：`p : [B]` の右辺の種類と `p : $[B]` が通るかを、R53・R59・R60 の文面の例で規則の側に書く。
	for (const [b, kind, pass] of ANCHOR17) {
		count["(c) 錨（R53 の文面の例）"]++;
		if (!BODIES17.includes(b)) problems.push(`(c) 錨 ${b}：BODIES17 に無い`);
		let rk = null;
		try {
			const pl = [`p : [${b}]`];
			const r = resolve(src([...usedDefs(UNITS17, pl.join("\n")), ...pl]));
			const t = r.trees[r.trees.length - 1];
			rk = t && t.right ? kindOf(t.right) : null;
		} catch (e) {
			rk = `断り ${e.reason || e.message}`;
		}
		const rkWant = kind === "U" ? "未知" : kind;
		if (rk !== rkWant) problems.push(`(c) 錨 ${b}：[B] の種類が ${rk}（文面の例では ${rkWant}）`);
		const od = at17([`p : $[${b}]`]);
		const passed = !od.crash && !od.refused;
		if (passed !== pass || (!pass && (!od.refused || od.refused.gate !== "G20"))) problems.push(`(c) 錨 ${b}：$[B] は ${view17(od)}（文面の例では${pass ? "通る" : "G20"}）`);
	}
	// (c) `p : $[B]` と `p : [B]`。
	for (const b of BODIES17) {
		const dl = [`p : $[${b}]`];
		const pl = [`p : [${b}]`];
		const od = at17(dl);
		const op = at17(pl);
		if (od.crash || op.crash) {
			problems.push(`(c) ${b}：例外`, `  ${view17(od)}`, `  ${view17(op)}`);
			continue;
		}
		if (op.refused) {
			count["(c) 中身が断る（同じ門）"]++;
			if (!od.refused || refusalText(od) !== refusalText(op)) problems.push(`(c) ${b}：[B] が断るなら $[B] も同じ門のはず`, `  $[B]: ${view17(od)}`, `  [B]: ${view17(op)}`);
			continue;
		}
		let rk = null;
		try {
			const r = resolve(src([...usedDefs(UNITS17, pl.join("\n")), ...pl]));
			const t = r.trees[r.trees.length - 1];
			rk = t && t.right ? kindOf(t.right) : null;
		} catch (e) {
			rk = `例外 ${e.message}`;
		}
		// 2026-10-25 の R59・R60 から：`[B]` の右辺に余るラムダの知らせ（leftover-lambda）があれば、`$[B]` は G20（R59：中身のどこかに余る関数。中身の並び
		// そのものの値と関数の積み上げは、遅延した式で種類が決まらないので、同じく G20）。後置の印の付いた項1つの中身も G20（R57）。ほかで、`[B]` が関数（L）
		// か値（A、R60：値を読む参照）なら通り、診断は `[B]` と同じ。未知なら G20。R53 の片では「関数なら通り、関数でなければ G20」だった。
		// 注（2026-10-25 の反証する人の指摘）：この側の「余る関数があるか」は、実装と同じ leftoverUnit の知らせ（恒等射を除く isIdentityKind も同じ）から読むので、
		// 両側に同じ前提が置かれている。実装の外から余る関数を数える物は、まだ無い。外延が恒等射の `[y ? y]` の余り（`$[x ? x (y ? y)]` は G20、`$[x ? x !_]` は
		// 通る）は、この比べでは見えない（R52 の知らせと同じ線。§5 Q56 の `$!_` が `[x ? x]` を指すこととの関わりは §5 Q65 の注）。
		const deadInside = op.diag.includes("leftover-lambda");
		// 2026-10-27 の片8（R99〜R101）から：`$` は必ず持ち上げで、先の種類では断らない。値の先は通って警告（R100、dollar-non-function）、関数の先と先の種類の分からない
		// 先は警告しない。断るのは中で余る関数（R59）・後置の印（R57）・書いた `,` の積（R101）だけ。前（R60）は、未知の先が G20 で、値の先は黙って通った。
		const lifted = !!od.diag && od.diag.includes("dollar-non-function");
		const odPlain = (od.diag || []).filter((x) => x !== "dollar-non-function").join(" ");
		if (b === "_" || b === "_ , !_") {
			// 書いた `_` の中身（R56、2026-10-25。`_ , !_` は R71 で `_`）：並びの中の `[_]` は値（印）だが、`$` で物にする所では零射 `$[x ? _]` の番地で通る。診断は `[B]` と同じ
			// （零射は関数なので警告しない、R100）。
			count["(c) 中身が書いた `_`（R56、通る）"] = (count["(c) 中身が書いた `_`（R56、通る）"] || 0) + 1;
			if (od.refused || od.diag.join(" ") !== op.diag.join(" ")) problems.push(`(c) ${b}：\`$[_]\` は零射の番地で通り、診断は [B] と同じはず（R56）`, `  $[B]: ${view17(od)}`, `  [B]: ${view17(op)}`);
		} else if (deadInside || POSTFIX17.has(b)) {
			count["(c) 中身に余る関数か後置の印で G20（R59・R57）"] = (count["(c) 中身に余る関数か後置の印で G20（R59・R57）"] || 0) + 1;
			if (!od.refused || od.refused.gate !== "G20") problems.push(`(c) ${b}：中身に余る関数か後置の印があれば G20 のはず（R59・R57）`, `  $[B]: ${view17(od)}`, `  [B]: ${view17(op)}`);
		} else if (product17(b)) {
			count["(c) 中身が書いた `,` の積で G20（R101）"] = (count["(c) 中身が書いた `,` の積で G20（R101）"] || 0) + 1;
			if (!od.refused || od.refused.gate !== "G20") problems.push(`(c) ${b}：単位律の後にも \`,\` の残る書いた積なら G20 のはず（R101）`, `  $[B]: ${view17(od)}`, `  [B]: ${view17(op)}`);
		} else if (rk === "L" || rk === "A") {
			count[rk === "L" ? "(c) 中身が関数で通る" : "(c) 中身が値で通り警告（R60・R100）"] = (count[rk === "L" ? "(c) 中身が関数で通る" : "(c) 中身が値で通り警告（R60・R100）"] || 0) + 1;
			if (od.refused || odPlain !== op.diag.join(" ") || lifted !== (rk === "A"))
				problems.push(`(c) ${b}：中身が関数か値なら通り、診断は [B] と同じ（値なら R100 の警告を足す）はず`, `  $[B]: ${view17(od)}`, `  [B]: ${view17(op)}`);
		} else {
			count["(c) 中身の種類が分からず持ち上げで通る（R99）"]++;
			if (od.refused || od.diag.join(" ") !== op.diag.join(" ")) problems.push(`(c) ${b}：中身が未知（${rk}）なら持ち上げで通り、警告しないはず（R99・R100）`, `  $[B]: ${view17(od)}`, `  [B]: ${view17(op)}`);
		}
	}
	for (const [k, v] of Object.entries(count)) if (!v) problems.push(`「${k}」の組が無い（法則がその枝を見ていない）`);
	return { problems, note: Object.entries(count).map(([k, v]) => `${k} ${v}`).join("・") };
});

// ---------------------------------------------------------------------------
// 法則18：`$` の先は書いた所で1つの関数（R54〜R57・G20、2026-10-25）
// ---------------------------------------------------------------------------
//
// 比べる綴り（どれも本体 `tt : u ?` の2行目か、括りの2行目に `C[…]` を置く。1行目は、定義の行か、同じ形の局所の値 `w0 : 0`）：
// (1) ファイルの定義 `lf : R` と、本体の `C[$lf]`
// (2) 右辺を開いた `C[$[R]]`（R が `!_` なら括らない `$!_`：括った `[!_]` は否定の点なし、R29）
// (3) 同じ定義を本体の局所に置いた `lf : R` ⏎ `C[$lf]`（R54）と、局所の名前を括った `lf : R` ⏎ `C[$[lf]]`（[x] ≅ x）。2026-11-04 の寄せ1 で (3a)・(3b) に
// 書き直した（下の注）
// 括りの中の文脈でも (1) と (2) は同じ（`lf : R` ⏎ `[w0 : 0 ⏎ C[$lf]]`・`[w0 : 0 ⏎ C[$[R]]]`）。R が外の仮引数 u を掴む閉包なら、(1) の u は未定義の
// 名前で別の物なので、本体の (1) は外す（括りでは u はどれも未定義の名前で同じ）。
// 括りの中に定義を置いた `[lf : R ⏎ C[$lf]]` は比べない：括りの行は欄かもしれず、局所の定義と読むかが決まっていないので、R54 は関数の本体の行だけに
// 当て、括りの中の名前は G20 で断る（2026-10-25 の確かめの直し、§5 Q10。断る行は coproduct.test.js）。作る途中の版は括りにも当てて、ここで比べていた。
// (4) `C[$_]` と `C[$[x ? _]]`（R56：`$_` は零射 `$[x ? _]` の番地）。
// (5) `C[$!_]` と `C[$[x ? x]]` と `i : !_` ⏎ `C[$i]`（§5 Q56 の答え、2026-10-25：`$!_` は1引数の恒等射 `[x ? x]` の番地で、恒等射の別名も同じ印。
// 主の Claude の問い「…Q56 は `$!_` が `[x ? x]` を指す、でいい？」（07:29 UTC）に U〔答え〕[2026-10-25 07:34 2772473e]「そうか分かった！ …」）。
// (4)・(5) の文脈には、開いた所の口の数が木に出る `tw : f [~r] ? @f 1 2` を足す（`$[x ? x]` なら `(construct (apply @f 1) 2)`）。
// R が `!_` の行は、R55 の片では `$!_` も別名・局所の `$lf` も指す関数の印を持たず（§5 Q56）、どの綴りも印の無い番地で同じだった。作る途中の版は、どれにも
// 並び全体を受ける恒等射の印を付けていて、両側に同じ前提を置いた比べになり、`$[x ? x]` と割れる所（`map2`・`fold`・`@f 1 2`）が見えなかった。(5) は、
// 印を付けた今、その割れを `$[x ? x]` との比べで見る。
// 何を同じと見るか：断れば門と名指し、通れば `C[…]` の行の木（`$[R]`・`$[x ? _]` の綴りは `$lf`・`$_` に読み替える）、ほかの行の木（括りの関数の実体。
// ファイルの `lf` の定義の行は (1) にしか無いので外す）、最後の行の種類、診断（leftover-lambda は出たかだけ）。期待値は書かない。
// なぜ同じか：U [2026-10-24 16:52 8dfc006e]「そもそも、$が指定できるのは、一つの関数だと言い切れることが条件。」。名前は右辺を指す（`:` はメタ、
// §5 Q50 の答え）ので、`$lf` の先は R の1つの関数で、どこに定義を置いても、開いて書いても同じ。`$_` は U [2026-10-25 00:08 8dfc006e]「…$_ は $[x ? _]」。
// 主の Claude の局所の定義を通す案に U〔答え〕[2026-10-25 00:25 8dfc006e]「…後はすべて君の言う通り。」。
// 比べの外：右辺の中から自分を `$` で指す局所の定義（R54 で断る。ファイルの `?` の定義は通る）と、右辺を解く所を通る値の輪（`w : [sq : z ? w ⏎ $sq]`。
// 局所では値を含む輪、ファイルの定義なら通る）は、局所の側だけが断る形として coproduct.test.js に置いた（§5 Q10）。
// 2026-10-25（R59・R60、§7.33）に広げた所：R60 から値の右辺（`5`・`1 , 2`・`[k : 1]`・`$inc`・`vs`）の `$lf` は値を読む参照として通るので、R54〜R57 の片では
// G20 どうしだった組が、通る答えどうしの比べになった（局所の側も、右辺の値の形を持つ。resolve.js の localTarget）。右辺・本体に余る関数のある物（`add (5 inc)`・
// `z ? z inc`。R59）と、`,` の `_` の消える右辺（`5 , _`。R61）を足した。
// 2026-11-04 の寄せ1（R128、U〔答え〕「入って」）で (3) を書き直した：本体の字下げの `:` の行は、左が名前1つでも枝で、何も定義しない（R80 と R54 の局所の
// 所は消えた）。`$名前` は本体の行を見ない（細目7）ので、本体に同じ名前の枝 `lf : R` を置いても `$lf` の先は変わらない。(3) は次の2つの比べにした（どの形も
// 1行目に同じ枝 `lf : R` を置くので、枝の条件と値の知らせはどの形にも同じに出る）：
// (3a) ファイルに `lf : R` がある時、`lf : R` ⏎ `C[$lf]` と `lf : R` ⏎ `C[$[R]]`（閉包と書いた積は除く。(1)・(2) と同じ理由）と `lf : R` ⏎ `C[$[lf]]` が同じ答え
// （`$lf` はファイルの lf を指す）。
// (3b) ファイルに lf が無い時、`lf : R` ⏎ `C[$lf]` と `lf : R` ⏎ `C[$_]` と `lf : R` ⏎ `C[$[lf]]` が同じ答え（未定義の名前の `$` は零射の番地 `$_`、R56・R111）。
// 前の (3) の「局所の `$lf` が (1)・(2) と同じ」は、局所の定義が無くなったので外した。閉包の右辺は、前は (2) と (3) を比べていたが、(2) の開いた `$[R]` は
// 仮引数 u を掴み、(3a) のファイルの lf の u は未定義の名前なので、閉包は (3a)・(3b) の中だけで比べる。
const BASE18 = [
	INC,
	"double : x ? x * 2",
	"add : x y ? x + y",
	"f3 : a b c ? a + b + c",
	"vs : 1 , 2 , 3",
	"use : f x ? @f x",
	"map : f [~t] ? [@f,] t~",
	"map2 : f [~t] ? @f t~",
	"fold : f [~h] ? @f h~",
	"tw : f [~r] ? @f 1 2",
];
// [右辺 R, 外の仮引数 u を掴む閉包か]
const RHS18 = [
	["z ? z * z", false],
	["inc", false],
	["inc double", false],
	["add 1", false],
	["a b ? a + b", false],
	["[y ~ys] ? y", false],
	["f3 !_ 2", false],
	["||inc||", false],
	["!_", false],
	["z ? z + u", true],
	["5", false],
	["1 , 2", false],
	["5 inc", false],
	["[k : 1]", false],
	["$inc", false],
	["vs", false],
	["_", false],
	// 2026-10-25 の R59（§5 Q53 の答え）：右辺・本体に余る関数のある物。`$[R]` は G20 で、名前を通した `$lf`（ファイルの定義も局所も）も同じく G20（§5 Q62）。
	["add (5 inc)", false],
	["z ? z inc", false],
	["5 , _", false], // R61：`,` の `_` は消えて 5
];
const CTX18 = [(x) => x, (x) => `map ${x} vs`, (x) => `map2 ${x} vs`, (x) => `fold ${x} vs`, (x) => `use ${x} u`, (x) => `[${x}]`, (x) => `${x} , 1`, (x) => `||${x}||`];
const CTX18F = [...CTX18, (x) => `tw ${x} vs`]; // (4)・(5)：開いた所の口の数が木に出る文脈を足す
const open18 = (r) => (r === "!_" ? "$!_" : `$[${r}]`);
// 答えの綴り。rename は [書いた綴り, 読み替える綴り]。
const answer18 = (lines, rename) => {
	let r;
	try {
		r = resolve(src([...BASE18, ...lines]));
	} catch (e) {
		if (!e.reason) return `例外 ${e.name}: ${e.message}`;
		return `断り ${e.reason} ${e.gate || ""} ${JSON.stringify((e.instances || []).map((i) => [i.fn, i.shape]))}`;
	}
	const fix = (s) => (rename ? s.split(rename[0]).join(rename[1]) : s);
	const out = [];
	for (const t of r.trees) {
		if (!t) continue;
		const text = show(t);
		if (text.startsWith("(: lf ")) continue; // (1) にしか無い定義の行
		if (t.t === "op" && t.sym === ":" && text.startsWith("(: tt ")) {
			const rows = t.right && t.right.body && t.right.body.view && t.right.body.view.rows;
			out.push(`tt の2行目 ${rows && rows[1] ? fix(show(rows[1])) : "?"}`);
		} else if (t.t === "leaf" && t.view && Array.isArray(t.view.inner) && t.view.inner.length === 2) {
			out.push(`括りの2行目 ${fix(show(t.view.inner[1]))} [${kindOf(t)}]`);
		} else out.push(`${fix(text)} [${kindOf(t)}]`);
	}
	const diag = diagKeys(r);
	return `通る ${out.join(" ⏎ ")} || ${diag.join(" ")}`;
};
law("18 `$` の先は1つの関数（R54〜R57）：ファイルの `$lf`・開いた `$[R]` が同じ答え、本体の同じ名前の枝の後ろの `$lf` はファイルの lf か `$_`（R128）、`$_` と `$[x ? _]`、`$!_` と `$[x ? x]` と `$i` が同じ答え", () => {
	const problems = [];
	const count = {
		"本体の (1)・(2)": 0,
		"(3a) 本体の同じ名前の枝の後ろ（ファイルに lf）": 0,
		"(3a) のうち閉包": 0,
		"(3b) 本体の同じ名前の枝の後ろ（lf は未定義で `$_` と同じ）": 0,
		"括りの中の文脈の2つ": 0,
		"通る組": 0,
		"G20 の組": 0,
		"ほかの断りの組": 0,
		"(4) `$_` と `$[x ? _]`": 0,
		"(5) `$!_` と `$[x ? x]` と `$i`": 0,
	};
	const tally = (a) => (a.startsWith("通る") ? "通る組" : a.includes(" G20 ") ? "G20 の組" : "ほかの断りの組");
	const same = (label, forms) => {
		const answers = forms.map(([lines, rename]) => answer18(lines, rename));
		if (answers.some((a) => a.startsWith("例外"))) {
			problems.push(`${label}：例外`, ...answers.map((a, i) => `  ${forms[i][0].join(" ⏎ ")} → ${a}`));
			return;
		}
		if (answers.some((a) => a !== answers[0])) {
			problems.push(`${label}：答えが割れた`, ...answers.map((a, i) => `  ${forms[i][0].join(" ⏎ ")} → ${a}`));
			return;
		}
		count[tally(answers[0])]++;
	};
	for (const [r, closure] of RHS18) {
		for (const c of CTX18) {
			const body = (first, x) => ["tt : u ?", `\t${first}`, `\t${c(x)}`, "", "tt 1"];
			// 2026-10-27 の片8 の R101：右辺が書いた `,` の積（単位律の後にも `,` が残る）なら、開いた `$[R]` は書いた積の `$` で G20、名前を通した `$lf` は値の持ち上げ
			// （R100 の警告）。決定の文が書いた綴りで分けた所なので、開いた側は比べから外し、規則の側の答え（G20）を見る（法則17 の (b) と同じ）。
			const product = r.includes(" , ") && r.split(" , ").filter((x) => !["_", "!_"].includes(x.trim())).length >= 2;
			if (product) {
				count["開いた側が書いた積（R101、比べの外で G20）"] = (count["開いた側が書いた積（R101、比べの外で G20）"] || 0) + 1;
				const a = answer18(body("w0 : 0", open18(r)), null);
				if (!a.includes(" G20 ")) problems.push(`本体 ${r} / ${c("X")}：開いた \`$[R]\` は書いた積の G20 のはず（R101）：${a}`);
			}
			// (1)・(2)：閉包は (1) の u が未定義の名前で別の物、書いた積は (2) が比べの外なので、どちらも比べる組が1つになって外す
			if (!closure && !product) {
				count["本体の (1)・(2)"]++;
				same(`本体 ${r} / ${c("X")}`, [
					[[`lf : ${r}`, ...body("w0 : 0", "$lf")], null],
					[body("w0 : 0", open18(r)), [open18(r), "$lf"]],
				]);
			}
			// (3a) ファイルの lf があって、本体の1行目が同じ名前の枝 `lf : R`（R128：何も定義しない、細目7：`$lf` は本体の行を見ない）
			const forms3a = [[[`lf : ${r}`, ...body(`lf : ${r}`, "$lf")], null]];
			if (!closure && !product) forms3a.push([[`lf : ${r}`, ...body(`lf : ${r}`, open18(r))], [open18(r), "$lf"]]);
			// 名前を括った `$[lf]`（[x] ≅ x で `$lf` と同じ先）
			forms3a.push([[`lf : ${r}`, ...body(`lf : ${r}`, "$[lf]")], ["$[lf]", "$lf"]]);
			count["(3a) 本体の同じ名前の枝の後ろ（ファイルに lf）"]++;
			if (closure) count["(3a) のうち閉包"]++;
			same(`本体 (3a) ${r} / ${c("X")}`, forms3a);
			// (3b) ファイルに lf が無い：`$lf` は未定義の名前の `$` で、零射の番地 `$_`（R56・R111）
			count["(3b) 本体の同じ名前の枝の後ろ（lf は未定義で `$_` と同じ）"]++;
			same(`本体 (3b) ${r} / ${c("X")}`, [
				[body(`lf : ${r}`, "$lf"), null],
				[body(`lf : ${r}`, "$_"), ["$_", "$lf"]],
				[body(`lf : ${r}`, "$[lf]"), ["$[lf]", "$lf"]],
			]);
			// 括りの中の文脈（u は外の名前で、どれも未定義の名前）。括りの中に定義を置いた形は比べない（上の注）。
			const br = (first, x) => [`[${first}`, `${c(x)}]`];
			count["括りの中の文脈の2つ"]++;
			if (product) {
				const a = answer18(br("w0 : 0", open18(r)), null);
				if (!a.includes(" G20 ")) problems.push(`括り ${r} / ${c("X")}：開いた \`$[R]\` は書いた積の G20 のはず（R101）：${a}`);
			} else
				same(`括り ${r} / ${c("X")}`, [
					[[`lf : ${r}`, ...br("w0 : 0", "$lf")], null],
					[br("w0 : 0", open18(r)), [open18(r), "$lf"]],
				]);
		}
	}
	// (4) `$_` と `$[x ? _]`（ファイルの範囲の文脈。use の u は 5 に替える）
	for (const c of CTX18F) {
		count["(4) `$_` と `$[x ? _]`"]++;
		const line = (x) => [c(x).replace(/\bu\b/g, "5")];
		same(`(4) ${c("X")}`, [
			[line("$_"), null],
			[line("$[x ? _]"), ["$[x ? _]", "$_"]],
		]);
	}
	// (5) `$!_` と `$[x ? x]` と、恒等射の別名 `i : !_` の `$i`（§5 Q56 の答え）。`i` の定義の行は `$i` の側にしか無いので、`(: i …)` の行を外して比べる
	// （answer18 は `(: lf ` だけを外すので、別名の名前を lf にする）。
	for (const c of CTX18F) {
		count["(5) `$!_` と `$[x ? x]` と `$i`"]++;
		const line = (x) => [c(x).replace(/\bu\b/g, "5")];
		same(`(5) ${c("X")}`, [
			[line("$!_"), null],
			[line("$[x ? x]"), ["$[x ? x]", "$!_"]],
			[["lf : !_", ...line("$lf")], ["$lf", "$!_"]],
		]);
	}
	for (const [k, v] of Object.entries(count)) if (!v) problems.push(`「${k}」の組が無い（法則がその枝を見ていない）`);
	return { problems, note: Object.entries(count).map(([k, v]) => `${k} ${v}`).join("・") };
});

// ---------------------------------------------------------------------------
// 法則19：合成に来た流れは、合成全体の口の数で受ける（R58、2026-10-25）
// ---------------------------------------------------------------------------
//
// 比べる綴り：
// (a) 合成 `F G` に撒いた流れを当てた `F G X~` と、合成を名前にした `g : F G` ⏎ `g X~` と、括った `(F G) X~`。
// (b) 合成全体の口が1つか2つなら、合成を関数で書き下した `h X~`（合成全体の口が2つ：F の口が1つなら `h : x y ? G (F x) y`、F の口が2つなら
//     `h : x y ? G (F x y)`。口が1つなら `h : x ? G (F x)`）。実装の外の片側（合成全体の口を数える所 composedMouths を通らない綴り）。
// 何を同じと見るか：最後の行が通るか断るか、通るなら種類、断るなら reason と門。文脈 `inc (B)` に置いた答えも。期待値は書かない。
// なぜ同じか：合成は1つの関数（カリー化された関数）で、撒いた流れはその関数の口の数で受ける（主の Claude の問い「合成に入った流れは、合成全体を
// 1つの関数として口の数で受ける、でいい？」（10:06 UTC）に、利用者は主の Claude が用意したボタン「合成全体で受ける」を選んだ。U〔答え〕[2026-10-25
// 14:39 533071da]。ボタンの文は主の Claude の物：「合成は1つの関数なので、撒いた流れは合成全体の口の数で受ける（2つなら畳み込み、1つなら書き下し、
// 3つ以上は G19）。」）。`:` はメタで名前は右辺を指す（§5 Q50 の答え）、括りは [x] ≅ x なので、(a) の3つは同じ関数。(b) の h は、合成と同じ関数を
// 素の関数で書いた物。
// 比べの外・許す所：(b) の合成の側が G19 で断るのは許す（断る側。畳まない2項の点なし `[<<]` を合成全体で畳む形は §5 Q49 で断り、h は素の関数なので
// 通る）。h の側は、本体の根が F・G の根で決まる素の関数なので、合成の側の未知を A と読むことはない（片向きに、合成の側が A なら h の側も A を見る）。
const DEFS19 = [
	INC,
	"double : x ? x * 2",
	"add : x y ? x + y",
	"f2 : x y ? x - y",
	"f3 : a b c ? a + b + c",
	"uu : x ? [,] x",
	"tl : [y ~ys] ? ys",
	"vs : 1 , 2 , 3",
];
const UNITS19 = toUnits(DEFS19);
// [関数の項, 口の数（null は可変長の口か、口の数の分からない関数）]
const FNS19 = [
	["inc", 1],
	["double", 1],
	["add", 2],
	["f2", 2],
	["[+ 1]", 1],
	["(add 1)", 1],
	["[x ? x]", 1],
	["[<<]", 2],
	["f3", 3],
	["uu", 1],
	["[+]", null],
	["tl", null],
];
const XS19 = ["vs", "[1 2]", "[5]", "5", "`ab`", "[]", "(tl vs)"];
const at19 = (lines) => outcome(src([...usedDefs(UNITS19, lines.join("\n")), ...lines]));
const ans19 = (o) => (o.crash ? `例外 ${o.crash}` : o.refused ? `断り ${o.refused.reason} ${o.refused.gate}` : `通る ${lastOf(o).kind}`);
law("19 合成に来た流れは合成全体の口で受ける（R58）：F G X~ と g : F G ⏎ g X~ と (F G) X~、合成全体の口が1つか2つなら合成を素の関数で書いた h X~", () => {
	const problems = [];
	const count = { "(a) 3つの綴り": 0, 通る: 0, 断る: 0, "(b) 素の関数で書いた h": 0, "(b) 合成の側が断る（許す）": 0, "(b) 同じ答え": 0 };
	count["(b) h の側が断る（許す。本体の中で未知の項が並びにある `add (uu x9) y9` など）"] = 0; // 数えるだけ（0 でもよい）
	count["(b) 合成の側だけが未知の予想（許す。R120 の前は h の側が G7）"] = 0;
	const both = (lines) => [ans19(at19(lines)), ans19(at19([...lines.slice(0, -1), `inc (${lines[lines.length - 1]})`]))].join(" / 文脈 ");
	for (const [f, mf] of FNS19) {
		for (const [g, mg] of FNS19) {
			for (const xs of XS19) {
				const forms = [[`${f} ${g} ${xs}~`], [`g9 : ${f} ${g}`, `g9 ${xs}~`], [`(${f} ${g}) ${xs}~`]];
				const outs = forms.map(both);
				count["(a) 3つの綴り"]++;
				if (outs.some((a) => a.includes("例外"))) problems.push(`(a) ${f} ${g} ${xs}~：例外`, ...outs.map((a, i) => `  ${forms[i].join(" ⏎ ")} → ${a}`));
				else if (outs.some((a) => a !== outs[0])) problems.push(`(a) ${f} ${g} ${xs}~：答えが割れた`, ...outs.map((a, i) => `  ${forms[i].join(" ⏎ ")} → ${a}`));
				else if (outs[0].startsWith("断り")) count.断る++;
				else count.通る++;
				// (b) 合成全体の口が1つか2つなら、素の関数で書いた h。
				if (mf === null || mg === null) continue;
				const whole = mf + mg - 1;
				if (whole !== 1 && whole !== 2) continue;
				const h =
					whole === 1 ? `h9 : x9 ? ${g} (${f} x9)` : mf === 1 ? `h9 : x9 y9 ? ${g} (${f} x9) y9` : `h9 : x9 y9 ? ${g} (${f} x9 y9)`;
				const oh = both([h, `h9 ${xs}~`]);
				count["(b) 素の関数で書いた h"]++;
				const oc = outs[0];
				if (oh.includes("例外")) problems.push(`(b) ${h} ⏎ h9 ${xs}~：例外 ${oh}`);
				else if (oc.startsWith("断り coproduct-stream-arity")) count["(b) 合成の側が断る（許す）"]++;
				else if (oh.startsWith("断り")) count["(b) h の側が断る（許す。本体の中で未知の項が並びにある `add (uu x9) y9` など）"]++;
				// 片イ（R120、2026-11-02）から h の本体の `inc (uu x9)` は G7 で断らずに A で通る。合成の側は、途中が未知の結果を次の関数へ流す予想で未知のまま。
				// 木と種類は予想で、値は書いた項の並びを畳んだ答え（R118）なので、合成の側の未知だけの違いは許す（前はこの組が h の側の G7 で上の枝に入っていた）。
				else if (oc !== oh && oc.replace(/通る 未知/g, "通る A") === oh) count["(b) 合成の側だけが未知の予想（許す。R120 の前は h の側が G7）"]++;
				else if (oc !== oh) problems.push(`(b) ${f} ${g} ${xs}~  ⇔  ${h} ⏎ h9 ${xs}~：合成全体の口で受けるので同じはず`, `  合成: ${oc}`, `  h: ${oh}`);
				else count["(b) 同じ答え"]++;
			}
		}
	}
	for (const [k, v] of Object.entries(count)) if (!v && !k.startsWith("(b) h の側")) problems.push(`「${k}」の組が無い（法則がその枝を見ていない）`);
	return { problems, note: Object.entries(count).map(([k, v]) => `${k} ${v}`).join("・") };
});

// ---------------------------------------------------------------------------
// 法則20：`$[…]` の中身を単位律と [x] ≅ x で縮めても、`$` の先は同じ（R44・R45・R61・R57・R59、2026-10-25 の確かめの直し）
// ---------------------------------------------------------------------------
//
// 比べる綴り：`C[$[X]]` と `C[$[X , _]]`・`C[$[_ , X]]`・`C[$[X , !_]]`・`C[$[!_ , X]]`・`C[$[(X)]]`。文脈 C は根・素の関数の口（`use X 1`）・括りの関数の
// 実体の裸の仮引数（`hk [1] X`。実体の形の綴りで、`$` が作った物が番地か参照か・指す物の形まで見る）。
// 何を同じと見るか：断れば門と名指し、通れば最後の行の種類と診断と、`hk` の実体の形。期待値は書かない。
// なぜ同じか：`,` の被演算子の恒等射（R45）と書いた `_`（R61）は積の単位で消え、括り1つは中身と同じ（[x] ≅ x）ので、どの綴りも中身は X 1つ。
// 確かめる人・反証する人の指摘（2026-10-25）：R57 の後置の印と R59 の名前の先は、書いた字面の1項・名前1つだけを見ていて、`$[vs~ , _]`・`$[p , !_]`
// （p : add (5 inc)）が値を読む参照で通り、`$[vs~]`・`$p` の G20 と割れていた。
// 比べの外：X が `_`・`!_` の物（`_ , !_` は §5 Q61 で G7、`[!_]` は否定の点なし）と、並びの単位（`$[p !_]`。中身の並びは遅延した式、§5 Q63）。
const DEFS20 = [INC, "add : x y ? x + y", "vs : 1 , 2 , 3", "use : f x ? @f x", "hk : [k] f ? f", "p : add (5 inc)", "q5 : 5", "sq : x ? x inc", "w : vs~", "un : _", "fs : inc , 1"];
const UNITS20 = toUnits(DEFS20);
const XS20 = ["5", "vs", "inc", "add 1", "q5", "p", "sq", "w", "un", "vs~", "5!", "add (5 inc)", "[x ? x inc]", "[x ? x + 1]", "$inc", "(inc 5)", "fs", "zz"];
const CTX20 = [(x) => x, (x) => `use ${x} 1`, (x) => `hk [1] ${x}`];
const ans20 = (line) => {
	const o = outcome(src([...usedDefs(UNITS20, line), line]));
	if (o.crash) return `例外 ${o.crash}`;
	if (o.refused) return `断り ${refusalText(o)}`;
	const inst = o.trees.map((t) => t.text).filter((t) => t.startsWith("(: hk ")).map((t) => (t.match(/\(inst [^ ]+/g) || []).join(" "));
	return `通る ${lastOf(o).kind} ${inst.join(" ")} || ${o.diag.join(" ")}`;
};
law("20 `$[…]` の中身を単位律で縮めても同じ先：C[$[X]] と C[$[X , _]]・C[$[_ , X]]・C[$[X , !_]]・C[$[!_ , X]]・C[$[(X)]]", () => {
	const problems = [];
	const count = { 比べた組: 0, 通る: 0, G20: 0, "ほかの断り": 0 };
	for (const x of XS20) {
		for (const c of CTX20) {
			const forms = [`$[${x}]`, `$[${x} , _]`, `$[_ , ${x}]`, `$[${x} , !_]`, `$[!_ , ${x}]`, `$[(${x})]`].map(c);
			const outs = forms.map(ans20);
			count.比べた組 += forms.length - 1;
			if (outs.some((a) => a.startsWith("例外"))) problems.push(`${c(`$[${x}]`)}：例外`, ...outs.map((a, i) => `  ${forms[i]} → ${a}`));
			else if (outs.some((a) => a !== outs[0])) problems.push(`${c(`$[${x}]`)}：答えが割れた`, ...outs.map((a, i) => `  ${forms[i]} → ${a}`));
			else if (outs[0].startsWith("通る")) count.通る++;
			else if (outs[0].includes(" G20 ")) count.G20++;
			else count["ほかの断り"]++;
		}
	}
	for (const k of ["比べた組", "通る", "G20"]) if (!count[k]) problems.push(`「${k}」の組が無い（法則がその枝を見ていない）`);
	return { problems, note: Object.entries(count).map(([k, v]) => `${k} ${v}`).join("・") };
});

// ---------------------------------------------------------------------------
// 法則21：Reader を値の演算子に当てる形は、綴りに依らず同じ答え（R60 の細かい所・§5 Q59、2026-10-25 の確かめの直し）
// ---------------------------------------------------------------------------
//
// 比べる綴り：R を値の演算子に当てる形を、中置（`R + 1`・`1 + R`・`R == 1`）・区間（`[+ 1] R`・`[1 +] R`・`[+ R] 1`・`[R +] 1`）・畳む点なし（`[+] R 1`・
// `[+] 1 R`・`[==] R 1`）・畳まない点なし（`[<<] R 1`）・前置の点なし（`[-_] R`）・写像（`[* 2,] R`・`[inc,] R`）・絶対値（`|R|`）・素の関数の口（`inc R`・
// `add R 1`・`add 1 R`・`(add R) 1`・`[x9 ? x9 + 1] R`・別の素の関数の口を通る `g9 R`）・括りの関数の実体の裸の仮引数（`pq [1] R`）で書く。
// 何を同じと見るか：R が `$` の作った Reader（`$5`・`$vs`・`$inc`・`p5 : $5` の p5）なら、どの綴りも同じ門（G7）。R が Reader でない値（`5`・`vs`）なら、
// どの綴りも通る。値の演算子でない物（論理の `R | 1` と `[|] R 1`）は、R に依らず同じ答え。期待値の門は書かず、中置の `R + 1` の答えと比べる。
// なぜ同じか：区間は位置で被演算子を取り（`[+ 1] x` は `x + 1`、R31・R32）、写像は要素ごとの適用（R50）、素の関数の適用は本体への代入（β）。前（R60 の片）は
// 中置の項の所だけで断っていて、ほかの綴りは通った（確かめる人・反証する人の指摘）。
// 比べの外（届かない所、§5 Q59）：素の関数が返した値（`id2 : x ? x` の `(id2 $5) + 1`）・器の中身（`($5 , 1) + 1`）・括りの関数や前置 `@` の項の口へ
// 素の関数の本体から渡した物。どれも、値の演算子が直に見ない所で、関数を器に入れた `(inc , 1) + 1` が A なのと同じ線。
// 2026-10-26 の R62（§5 Q59 の答え、番地の点と差）から、値を読む参照（`$5`・`$vs`・p5）の綴りはどれも G21（中置の `R + 1`・`R == 1` は Address と数を
// 混ぜた形で G21、ほかの綴りは中置の外の綴りで G21）、関数を指す番地（`$inc`）は今のまま G7。比べ方（中置の `R + 1` の答えと同じ門）は変えない。
// 中置で通る `R + 0x10`・`R - R` を中置の外の綴りで書いた形（`[+ 0x10] R`・`[-] R R`）は G21 で割れるので、この法則の外（§5 Q66。法則22 は中置だけを比べる）。
// 届かない所は 2026-10-26 から §5 Q66。
const DEFS21 = [INC, "add : x y ? x + y", "vs : 1 , 2 , 3", "p5 : $5", "g9 : y ? inc y", "pq : [a] b ? a + b"];
const UNITS21 = toUnits(DEFS21);
const RS21 = [["$5", true], ["$vs", true], ["$inc", true], ["p5", true], ["5", false], ["vs", false]];
const FORMS21 = [
	(r) => `${r} + 1`, (r) => `1 + ${r}`, (r) => `${r} == 1`, (r) => `[+ 1] ${r}`, (r) => `[1 +] ${r}`, (r) => `[+ ${r}] 1`, (r) => `[${r} +] 1`,
	(r) => `[+] ${r} 1`, (r) => `[+] 1 ${r}`, (r) => `[==] ${r} 1`, (r) => `[<<] ${r} 1`, (r) => `[-_] ${r}`, (r) => `[* 2,] ${r}`, (r) => `[inc,] ${r}`,
	(r) => `|${r}|`, (r) => `inc ${r}`, (r) => `add ${r} 1`, (r) => `add 1 ${r}`, (r) => `(add ${r}) 1`, (r) => `[x9 ? x9 + 1] ${r}`, (r) => `g9 ${r}`, (r) => `pq [1] ${r}`,
];
const LOGIC21 = [(r) => `${r} | 1`, (r) => `[|] ${r} 1`];
const cls21 = (line) => {
	const o = outcome(src([...usedDefs(UNITS21, line), line]));
	if (o.crash) return `例外 ${o.crash}`;
	return o.refused ? `断り ${o.refused.reason} ${o.refused.gate}` : "通る";
};
law("21 Reader を値の演算子に当てる形は綴りに依らず同じ答え：R + 1 と [+ 1] R・[+] R 1・inc R・[inc,] R・|R|・pq [1] R ほか", () => {
	const problems = [];
	const count = { 比べた組: 0, "Reader で断る": 0, "Reader でない値で通る": 0, "論理の綴りの組": 0 };
	for (const [r, reader] of RS21) {
		const base = cls21(FORMS21[0](r));
		if (reader !== base.startsWith("断り")) problems.push(`${FORMS21[0](r)}：${base}（Reader なら断り、Reader でなければ通るはず）`);
		for (const f of FORMS21.slice(1)) {
			const line = f(r);
			const a = cls21(line);
			count.比べた組++;
			if (a !== base) problems.push(`${line}：${a}（${FORMS21[0](r)} は ${base}）`);
			else count[reader ? "Reader で断る" : "Reader でない値で通る"]++;
		}
		const logic = LOGIC21.map((f) => cls21(f(r)));
		count["論理の綴りの組"]++;
		if (logic[0] !== logic[1]) problems.push(`${LOGIC21[0](r)} と ${LOGIC21[1](r)}：答えが割れた（${logic.join(" / ")}）`);
	}
	for (const [k, v] of Object.entries(count)) if (!v) problems.push(`「${k}」の組が無い（法則がその枝を見ていない）`);
	return { problems, note: Object.entries(count).map(([k, v]) => `${k} ${v}`).join("・") };
});

// ---------------------------------------------------------------------------
// 法則22：番地の点と差は torsor（R62、2026-10-26。§5 Q59 の答え）
// ---------------------------------------------------------------------------
//
// 比べる綴り：
// (a) 点 + 差 − 点は差：`((P + X) - P)` と、ほかの綴りの差 `($vs - $five)`。P は点（`$vs`・`$five`・`$5`・`p : $vs` の p・ずらした点 `($vs + 0x10)` と
//     それを指す名前 q）、X は差（`0x10`・`8x00FF`・括った `(0x10)`・字面を右辺に持つ名前 nx・点どうしの差 `($five - $vs)`）。
// (b) 点 + (点2 − 点) は点2：`(P + (Q - P))` と `(Q)`（P・Q は (a) の点）。
// (c) 名前・括りで包んでも同じ：`C[X]` と `C[(X)]` と `w : X ⏎ C[w]` と `w : X ⏎ w2 : w ⏎ C[w2]`（X は1語：点・字面・数・関数の番地・未定義の名前）。
//     2語以上の X（ずらした点・差）は字面のまま置くと結び方が変わるので、`C[(X)]` と名前の綴りだけを比べる。
// (d) 点 − 差 + 差は点：`((P - X) + X)` と `(P)`（P は (a) の点、X は (a) の差）。
// (e) 作用の結合：`((P + D1) + D2)` と `(P + (D1 + D2))`（D1・D2 は点どうしの差の綴り。`0x…` どうしの和 `(0x10 + 0x8)` は点が無いので今までの読みの
//     中身の見えない A で、点に足すと §5 Q66：割れるのが分かっているので比べの外にし、錨で今の答えを留める）。→ 2026-10-27 の片7 の R96 で `0x…` どうしの和は差になり、
//     割れは無くなった（錨を通る側に替えた。`0x…` の和と字面を混ぜた作用の結合・幅の倍数の門の順は法則35 が比べる）。
// (f) 差の群：`((D1 + D2) - D2)` と `(D1)`（D1・D2 は (e) の差）。
// 文脈 C は顔（点・差・数）を見分ける所：根・`C + 0x10`（点なら点、差なら §5 Q66）・`C - $vs`（点なら差、差なら §5 Q66）・`$vs - C`・`$vs + C`・`C + 1`・
// `C == $vs`・`C == ($vs - $five)`・`($vs - $five) + C`・`$[C]`・`use C 1`・括りの関数の実体の裸の仮引数（`hk [1] C`、hk の本体は `f == $vs`。2026-10-26 の
// 確かめの直しの前は `f - $vs` だったが、差を返す関数は答えに印を持たせられないので、どの C でも G21 になり顔を見分けない）。
// 何を同じと見るか：断れば門と名指し、通れば最後の行の種類と診断。(c) は `hk` の実体の形も（(a)(b) は、ずらした点の形 `$+` と値を読む参照の形 `$[N…]` が
// 違うので見ない）。期待値は書かない。
// なぜ同じか：位置は差の群が働く torsor（アフィン空間）で、点 + 差は点、点 − 点は差、差は群（主の Claude の読み、R。表に U〔答え〕[2026-10-25 21:15
// c8ccdd69]「その表のとおりで良い。」）。名前は右辺を指し（`:` はメタ）、括り1つは中身と同じ（[x] ≅ x）。
// 比べの外：`@` で開く文脈（ずらした点が指す物は解決器の段では分からず G21、点2 の `@` は指す値を読む。§5 Q66）・中置の外の綴り（区間・点なし・素の
// 関数の口は番地を受ければ G21 で、答えに点・差の印を持たない。§5 Q66）・書いた `_`（並びの中と名前・括りで顔が違う、R56 の R の所）。
// 2026-10-26 の確かめの直しの後の比べの外：(b)(d) で右が `$` の作った点（`$vs`・`$five`・`$5`・p）のときの `use C 1`。番地の算術で作った点・差は、印を落とす
// 所（素の関数の口）に入れば G21、`$` が作った点（値を読む参照）は R60 の届かない所のまま通るので、同じ点が綴りで割れる（§5 Q66 の問い、圏論の視点で
// 見直す所）。錨で今の答えを留める。本体の局所の名前で包む形（`tt : y ? ⏎ w : X ⏎ C[w]`）は、2026-10-26 の R80 から局所の名前が右辺の desc（点・差の印も）を
// 持つので、ファイルの定義で包む形と同じ答えになる（法則27 が比べる。前は局所の名前が種類の未知（P2）で、局所の定義の右辺の点・差は G21 だった）。
// 2026-11-04 の寄せ1（R128）から、本体の `w : X` の行は枝で何も定義しないので、この包む形は無くなった（法則27 も消した）。
const DEFS22 = [
	INC, "add : x y ? x + y", "vs : 1 , 2 , 3", "use : f x ? @f x", "five : 5", "p : $vs", "q : $vs + 0x10", "nx : 0x10", "hk : [k] f ? f == $vs", "dq : $vs - $five",
];
const UNITS22 = toUnits(DEFS22);
const PTS22 = ["$vs", "$five", "$5", "p", "($vs + 0x10)", "q"];
// 幅つきの字面は、2026-10-27 の片7 の R97（幅の倍数でない差は断る）から、Int の幅 8 byte の倍数の `8x00F8` にした（前の `8x00FF` は値 0xFF で、PTS22 の点は
// どれも Int の要素を指すので、(a) の左だけが G21 になる。点の幅と差の値の比べは法則35 が見る）。(c) の WORDS22 の `8x00FF` は包みどうしの比べなので残した。
const DIFFS22 = ["0x10", "8x00F8", "(0x10)", "nx", "($five - $vs)"];
const WORDS22 = ["0x10", "8x00FF", "$vs", "$five", "$5", "5", "$inc", "zz", "p", "q", "nx"];
const MULTI22 = ["$vs + 0x10", "$vs - $five", "$five - 0x10", "(0x10)", "($vs - $five) + ($five - $vs)"];
// 点どうしの差の綴り（(e)(f)。名前 dq も）。
const DD22 = ["($five - $vs)", "($vs - $five)", "(($vs + 0x10) - $vs)", "dq"];
// `$` が作った点（値を読む参照）の綴り。(b)(d) の右がこれなら、印を落とす所の `use C 1` は比べない（上の注）。
const DOLLAR_PTS22 = new Set(["$vs", "$five", "$5", "p"]);
const USE22 = (e) => `use ${e} 1`;
const CTX22 = [
	(e) => e, (e) => `${e} + 0x10`, (e) => `${e} - $vs`, (e) => `$vs - ${e}`, (e) => `$vs + ${e}`, (e) => `${e} + 1`, (e) => `${e} == $vs`,
	(e) => `${e} == ($vs - $five)`, (e) => `($vs - $five) + ${e}`, (e) => `$[${e}]`, USE22, (e) => `hk [1] ${e}`,
];
const ctxFor22 = (right) => (DOLLAR_PTS22.has(right) ? CTX22.filter((c) => c !== USE22) : CTX22);
// (c) の包みだけに、幅の倍数でない字面を足す文脈 `C + 0x3` を足す（2026-10-27 の片7 の R97：点の幅と差の値は名前と括りに運ぶので、包んでも同じ答え。変異で、名前に幅を
// 運ばない作りが法則で落ちないのを見つけた）。(a)(b)(d)(e)(f) には足さない：値の決まらない差でずらした点は幅を持たない（R97）ので、`P + (Q - P)` と `Q`、`(P - X) + X` と `P`
// （X が点どうしの差）がこの文脈で割れる（§5 Q77。下の錨で今の答えを留める）。
const CTX22C = [...CTX22, (e) => `${e} + 0x3`];
const ans22 = (lines, withInst) => {
	const line = lines[lines.length - 1];
	const o = outcome(src([...usedDefs(UNITS22, lines.join("\n")), ...lines]));
	if (o.crash) return `例外 ${o.crash}`;
	if (o.refused) return withInst ? `断り ${refusalText(o)}` : `断り ${o.refused.reason} ${o.refused.gate}`;
	const inst = withInst ? o.trees.map((t) => t.text).filter((t) => t.startsWith("(: hk ")).map((t) => (t.match(/\(inst [^ ]+ [^ ]+/g) || []).join(" ")) : [];
	return `通る ${lastOf(o).kind} ${inst.join(" ")} || ${o.diag.join(" ")}${line ? "" : ""}`;
};
law("22 番地の点と差は torsor：(P + X) - P と差・P + (Q - P) と Q・C[X] と C[(X)] と名前・(P - X) + X と P・作用の結合・差の群", () => {
	const problems = [];
	const count = {
		比べた組: 0, "(a) 通る": 0, "(a) 断る": 0, "(b) 通る": 0, "(b) 断る": 0, "(c) 通る": 0, "(c) 断る": 0,
		"(d) 通る": 0, "(d) 断る": 0, "(e) 通る": 0, "(e) 断る": 0, "(f) 通る": 0, "(f) 断る": 0,
	};
	const cmp = (tag, forms, withInst) => {
		const outs = forms.map((ls) => ans22(ls, withInst));
		count.比べた組 += forms.length - 1;
		if (outs.some((a) => a.startsWith("例外"))) problems.push(`${tag}：例外`, ...outs.map((a, i) => `  ${forms[i].join(" ⏎ ")} → ${a}`));
		else if (outs.some((a) => a !== outs[0])) problems.push(`${tag}：答えが割れた`, ...outs.map((a, i) => `  ${forms[i].join(" ⏎ ")} → ${a}`));
		else count[`${tag.slice(0, 3)} ${outs[0].startsWith("通る") ? "通る" : "断る"}`]++;
	};
	// (a) 点 + 差 − 点は差
	for (const pt of PTS22) for (const x of DIFFS22) for (const c of CTX22) cmp("(a) " + c(`((${pt} + ${x}) - ${pt})`), [[c(`((${pt} + ${x}) - ${pt})`)], [c("($vs - $five)")]], false);
	// (b) 点 + (点2 − 点) は点2
	for (const pt of PTS22) for (const q2 of PTS22) for (const c of ctxFor22(q2)) cmp("(b) " + c(`(${pt} + (${q2} - ${pt}))`), [[c(`(${pt} + (${q2} - ${pt}))`)], [c(`(${q2})`)]], false);
	// (d) 点 − 差 + 差は点
	for (const pt of PTS22) for (const x of DIFFS22) for (const c of ctxFor22(pt)) cmp("(d) " + c(`((${pt} - ${x}) + ${x})`), [[c(`((${pt} - ${x}) + ${x})`)], [c(`(${pt})`)]], false);
	// (e) 作用の結合（点どうしの差の綴りで）
	for (const pt of PTS22) for (const d1 of DD22) for (const d2 of DD22) for (const c of CTX22) cmp("(e) " + c(`((${pt} + ${d1}) + ${d2})`), [[c(`((${pt} + ${d1}) + ${d2})`)], [c(`(${pt} + (${d1} + ${d2}))`)]], false);
	// (f) 差の群
	for (const d1 of DD22) for (const d2 of DD22) for (const c of CTX22) cmp("(f) " + c(`((${d1} + ${d2}) - ${d2})`), [[c(`((${d1} + ${d2}) - ${d2})`)], [c(`(${d1})`)]], false);
	// (c) 名前・括りで包んでも同じ
	for (const x of WORDS22) for (const c of CTX22C) cmp("(c) " + c(x), [[c(x)], [c(`(${x})`)], [`w : ${x}`, c("w")], [`w : ${x}`, "w2 : w", c("w2")]], true);
	for (const x of MULTI22) for (const c of CTX22C) cmp("(c) " + c(`(${x})`), [[c(`(${x})`)], [`w : ${x}`, c("w")], [`w : ${x}`, "w2 : w", c("w2")]], true);
	// 錨：(a) の差は「点の左に置けば §5 Q66、点から引けば点」、(b) の点は「`0x10` を足せば点、点から引けば差」と、顔を見分けて答えが分かれていること。
	const anchor = (line, want) => {
		const a = ans22([line], false);
		if (!a.startsWith(want)) problems.push(`錨 ${line}：${a}（${want} のはず）`);
	};
	anchor("(($vs + 0x10) - $vs) - $vs", "断り coproduct-address-arith G21");
	anchor("$vs - (($vs + 0x10) - $vs)", "通る A");
	anchor("($vs + ($five - $vs)) + 0x10", "通る A");
	anchor("($vs + ($five - $vs)) - $vs", "通る A");
	anchor("($vs + ($five - $vs)) == ($vs - $five)", "断り coproduct-address-arith G21");
	anchor("(($vs + 0x10) - $vs) + 1", "断り coproduct-address-arith G21");
	// 比べの外にした割れ（§5 Q66）を、今の答えで留める：印を落とす所（素の関数の口）では、算術で作った点は G21、`$` が作った点は通る。`0x…` どうしの和を
	// 点に足すと §5 Q66、1つずつ足せば点（作用の結合が `0x…` の綴りで割れる）。
	// 2026-10-26 の R81（§5 Q45 の答え）から、use は印で実体を作り、本体の `@f` で開く：ずらした点は開けずに G21（R62）、`$` の作った点は指す値を読んで A（前は
	// 印が届かず未知）。割れは印を落とす所から `@` で開く所へ移ったが、同じ点が綴りで割れるのは変わらない（§5 Q66）。
	anchor("use ($vs + ($five - $vs)) 1", "断り coproduct-address-arith G21");
	anchor("use ($five) 1", "通る A");
	// 2026-10-27 の片7 の R96（§5 Q66 の算術の所の答え）で `0x… ± 0x…` は差になり、`$vs + (0x10 + 0x8)` も点（前は §5 Q66 の G21）。作用の結合の `0x…` の綴りの割れは
	// 無くなった（法則35 が比べる）。
	anchor("$vs + (0x10 + 0x8)", "通る A");
	anchor("($vs + 0x10) + 0x8", "通る A");
	// 2026-10-27 の片7 の R97：値の決まらない差でずらした点は幅を持たないので、torsor の `P + (Q - P)` と `Q`、`(P - X) + X` と `P` が幅の倍数の門で割れる（§5 Q77）。
	anchor("($vs + ($five - $vs)) + 0x3", "通る A");
	anchor("$five + 0x3", "断り coproduct-address-arith G21");
	anchor("(($vs - ($five - $vs)) + ($five - $vs)) + 0x3", "通る A");
	anchor("$vs + 0x3", "断り coproduct-address-arith G21");
	for (const k of Object.keys(count)) if (!count[k]) problems.push(`「${k}」の組が無い（法則がその枝を見ていない）`);
	return { problems, note: Object.entries(count).map(([k, v]) => `${k} ${v}`).join("・") };
});

// ---------------------------------------------------------------------------
// 法則23：参照の口は双積の点（R64・R66、2026-10-26。§5 Q3 の答えと、括りの名前は射影）
// ---------------------------------------------------------------------------
//
// 比べる綴り：最後の仮引数が括りの関数の頭 H（前の仮引数に当てる実引数 a… のあと）に、要素 e1 … em（m ≥ 2、どれも1項）を渡す4つの綴り。
// (s) 書き並べ `H a… e1 … em`、(c) 積 `H a… e1 , … , em`（R66）、(b) 括り `H a… [e1 … em]`、(f) 撒いた流れ `H a… [e1 … em]~`（R64）。
// 包み：根・`(X) 7`・`inc (X)`・`[X]`・`5 X`・名前 `w : X ⏎ w`・本体 `t : y ? X ⏎ t 1`。頭は名前・別名・部分適用（括り・名前）・括った `?`。
// 何を同じと見るか：断れば門と名指し、通れば最後の行の種類と、括りの関数の定義の行の木（実体の形の綴り）と、診断（R64 の bracket-excess は名前まで）。
// 期待値は書かない。
// なぜ同じか：括りの口（参照の口）は行の残りを1つの List として丸ごと受ける（R24・R64）ので、書き並べと括りは同じ List。参照の口では余積の並びと積の並びが
// 同じ List になる（双積の点、主の Claude の読み、R）ので、積も同じ（R66。U〔答え〕[2026-10-25 22:45 c8ccdd69]「その方向でお願い。」）。撒いた流れは書き並べと
// 同じ要素の流れで、括りの口はそれを1つの List として受ける（R51 の「最後の口が可変長なら丸ごと」、R64）。名前は右辺を指し（`:` はメタ）、括り1つは中身と同じ。
// 比べの外：`,` の左の値が最後の括りに最初に入らない形（最後の括りがもう前の項を受けている `H e1 e2 , e3`・最後でない括り・値の口）は R66 の外で G3
// （§5 Q68）。撒く項と書いた実引数の混ざった形（`H 1 vs~`）は今のまま未知（§5 Q29）。2026-10-26 の確かめの直しから、`,` の右の要素が2項以上の並び
// （`H e1 , e2 e3`、左の鏡）と、`,` のすぐ左が書いた `_` の形（`H _ , e2 , e3`）も G3（§5 Q68。錨で見る）。要素に書いた `_` を入れた組（真ん中・後ろ）は比べる。
// 2026-10-27 の R93（§5 Q68 の答え：書いた形のまま実引数の形）から、`H e1 e2 , e3` は `H (e1 e2 , e3)`、鏡は `H (e1 , e2 e3)`、頭の `_` は `H (_ , e2 , e3)` で通る（錨で見る）。
// 頭の `_` の組は比べに入れた。残る比べの外は、最後でない括り・値の口（G3、§5 Q68 の残り）。
const DEFS23 = [
	INC, "vs : 1 , 2 , 3", ...M,
	"fp : [a b c] ? a + b * c", "fh : [x ~xs] ? x", "fl : [~xs] ? xs", "fab : [a b] ? a + b", "hs : [x ~xs] ? x + hs xs", "mp : h [~l] ? [@h,] l~",
	"hv : v [x ~xs] ? v + x", "p3 : [a] [b ~bs] [c ~cs] ? a + c", "pm : mp $inc", "fa : fp", "pp3 : p3 1",
];
const UNITS23 = toUnits(DEFS23);
const PATTERN_NAMES23 = ["fp", "fh", "fl", "fab", "hs", "mp", "hv", "p3"];
// [頭, 前の仮引数に当てる実引数]
const HEADS23 = [
	["fp", ""], ["fh", ""], ["fl", ""], ["fab", ""], ["hs", ""], ["mp", "$inc"], ["hv", "1"], ["p3", "1 [2 3]"],
	["(p3 1 [2 3])", ""], ["pm", ""], ["fa", ""], ["pp3", "[2 3]"], ["[[x ~xs] ? x]", ""],
];
// `["zz", "zz"]` の zz は未定義の名前で、2026-10-28 の片9b の R111 から `_` と分かる値（前は R21 の中身の見えない値。両側に同じ綴りを置くので比べはそのまま）。
const ESETS23 = [
	["1", "2"], ["1", "2", "3"], ["1", "2", "3", "4"], ["\\a", "\\b"], ["[1 2]", "[3 4]"], ["[1 2]", "3"], ["$inc", "$inc"], ["zz", "zz"],
	["(inc 1)", "2"], ["vs", "vs"], ["`ab`", "`cd`"], ["1 + 2", "3"], ["-1", "2", "3"], ["m", "m"],
	// 書いた `_` の要素（2026-10-26 の確かめの直し）：並びの中の書いた `_` は R15・R61 のまま消える（位置は詰まる）ので、どの綴りも同じ List。
	// 頭の `_`（`H _ , 1 , 2`）は、2026-10-26 は `,` のすぐ左が書いた `_` で R66 の外の G3（§5 Q68）なので (c) だけ比べの外だった。2026-10-27 の R93（§5 Q68 の答え：
	// 書いた形のまま）から `H (_ , 1 , 2)` で、積の頭の `_` は R61 で消えるので、(c) も比べる。
	["1", "_", "2"], ["1", "2", "_"], ["_", "1", "2"],
];
const WRAPS23 = [
	(x) => [x], (x) => [`(${x}) 7`], (x) => [`inc (${x})`], (x) => [`[${x}]`], (x) => [`5 ${x}`], (x) => [`w : ${x}`, "w"], (x) => [`t : y ? ${x}`, "t 1"],
];
const ans23 = (lines) => {
	const o = outcome(src([...usedDefs(UNITS23, lines.join("\n")), ...lines]));
	if (o.crash) return `例外 ${o.crash}`;
	if (o.refused) return `断り ${refusalText(o)}`;
	const defs = o.trees.map((t) => t.text).filter((t) => PATTERN_NAMES23.some((n) => t.startsWith(`(: ${n} (? `)));
	return `通る ${lastOf(o).kind} || ${defs.join(" | ")} || ${o.diag.join(" ")}`;
};
law("23 参照の口は双積の点：H e1 … em と H e1 , … , em と H [e1 … em] と H [e1 … em]~（名前・括り・本体で包んでも）", () => {
	const problems = [];
	const count = { 比べた組: 0, 通る: 0, 断る: 0, "名前の無い要素を知らせる": 0, "(f) の外（関数の見える器を撒く、§5 Q20）": 0, "`,` のすぐ左が書いた `_` の組（R93）": 0 };
	for (const [h, front] of HEADS23) {
		for (const es of ESETS23) {
			const pre = front ? `${h} ${front}` : h;
			const forms = [`${pre} ${es.join(" ")}`, `${pre} [${es.join(" ")}]`];
			if (es[0] === "_") count["`,` のすぐ左が書いた `_` の組（R93）"]++;
			forms.splice(1, 0, `${pre} ${es.join(" , ")}`);
			// 中身に関数の見える器（欄に関数のある構造体 m の List）を撒く形は、今のまま G7（§5 Q20：撒いた中身をどの段で解くかが決まっていない）なので、(f) は比べの外。
			if (es.includes("m")) count["(f) の外（関数の見える器を撒く、§5 Q20）"]++;
			else forms.push(`${pre} [${es.join(" ")}]~`);
			for (const w of WRAPS23) {
				const outs = forms.map((f) => ans23(w(f)));
				count.比べた組 += forms.length - 1;
				if (outs.some((a) => a.startsWith("例外")) || outs.some((a) => a !== outs[0])) {
					problems.push(`${w(forms[0]).join(" ⏎ ")}：答えが割れた`, ...outs.map((a, i) => `  ${w(forms[i]).join(" ⏎ ")} → ${a.slice(0, 300)}`));
					continue;
				}
				if (outs[0].startsWith("通る")) count.通る++;
				else count.断る++;
				if (outs[0].includes("bracket-excess/")) count["名前の無い要素を知らせる"]++;
			}
		}
	}
	// 錨：積の綴りが今の答えで通ること・余りを知らせること・比べの外の G3。
	const anchor = (lines, want) => {
		const a = ans23(lines);
		if (!a.startsWith(want)) problems.push(`錨 ${lines.join(" ⏎ ")}：${a.slice(0, 300)}（${want} のはず）`);
	};
	anchor(["fp 1 , 2 , 3"], "通る A");
	anchor(["fp 1 , 2 , 3 , 4"], "通る A");
	if (!ans23(["fp 1 , 2 , 3 , 4"]).includes("bracket-excess/fp")) problems.push("錨 fp 1 , 2 , 3 , 4：名前の無い要素の知らせが無い");
	// 2026-10-26 は `fp 1 2 , 3`・鏡の `fab 1 , 2 3`・`,` のすぐ左が書いた `_` の `fp _ , 1 , 2` を G3（§5 Q68）の錨で見ていた。2026-10-27 の R93（§5 Q68 の答え：
	// 書いた形のまま）から通り、`fp 1 2 , 3` は `[[1 2] 3]` で長さ 2 の実体（足りない c は `_`、R91）、`fab 1 , 2 3` は `[1 [2 3]]`。残りの形（最後でない括り）の G3 を錨で見る。
	anchor(["fp 1 2 , 3"], "通る A || (: fp (? [[a b c]] (inst [A…](2)");
	anchor(["fab 1 , 2 3"], "通る A");
	anchor(["fp _ , 1 , 2"], "通る A || (: fp (? [[a b c]] (inst [N…](2)");
	// 最後でない括りに入る `p3 1 , 2` と値の口の `inc 1 , 2` は、片イ（R121、2026-11-02。問4 の答え U〔答え〕[2026-11-01 12:15 159479c9]「同じ」）から
	// G3 でなく `,` の辺を左から畳む：`inc 1 , 2` は `(inc 1) , 2`、`p3 1 , 2` は辺の終わりに余った `p3 1` が `_`（leftover-lambda）で 2。
	anchor(["p3 1 , 2"], "通る A");
	if (!ans23(["p3 1 , 2"]).includes("leftover-lambda")) problems.push("錨 p3 1 , 2：辺の終わりに余った `p3 1` の leftover-lambda が無い");
	anchor(["fp 1 , _ , 2"], "通る A");
	anchor(["inc 1 , 2"], "通る A");
	anchor(["fl 1 vs~"], "通る 未知");
	for (const [k, v] of Object.entries(count)) if (!v) problems.push(`「${k}」の組が無い（法則がその枝を見ていない）`);
	return { problems, note: Object.entries(count).map(([k, v]) => `${k} ${v}`).join("・") };
});

// ---------------------------------------------------------------------------
// 法則24：評価する所に残った丸ごとの関数は、どの評価する所でも同じ（R42・R48・R76、2026-10-26 の §5 Q37 の答え）
// ---------------------------------------------------------------------------
//
// 評価する所（行の根・比べと論理の被演算子・2行以上の手続きの本体の行）に丸ごとの関数 F（未評価のラムダ）が残れば、どこでも `_`（木は `(unit F)`）で、恒等射で
// なければ同じ名前で1回知らせる。期待値は書かず、行の根に置いた `F` の答えと、ほかの評価する所に置いた F の所の部分木と知らせを比べる。名前（`w : F` ⏎ w）と
// 括り（`(F)`）で包んでも、どの評価する所でも `(unit …)` になり、知らせの数は包まない F と同じ（名前の右辺は閉じた1つの項で、`:` の行では知らせない、§5 Q50）。
// 確かめの直し（2026-10-26）：手続きの最後の行（`&` の右の被演算子）も比べる。枝の値は本体の返す所（法則26）なので、ここから外した。裸のラムダの行は、括った
// ラムダの行と同じく `(unit …)` で1回知らせる（[x] ≅ x。最初の版は括った行だけを比べていて、裸の行が L のまま残る割れを見ていなかった）。
const DEFS24 = [INC, "add : x y ? x + y", "f2 : x y ? x - y", "i : !_", "uu : m ? [,] m"];
const UNITS24 = toUnits(DEFS24);
const F24 = ["inc", "add 1", "inc add 5", "[+ 1]", "(inc add)", "||inc||", "add !_ 3", "f2 _ 3", "i", "i i", "[x ? x + 1]", "inc i", "[<<] 1"];
// [置き方, F を置いた行, 置いた所の部分木を取り出す関数]
const PLACES24 = [
	["比べの左", (f) => [`${f} == 7`], (t) => t.left],
	["比べの右", (f) => [`7 == ${f}`], (t) => t.right],
	["否定の比べの左", (f) => [`${f} !== 7`], (t) => t.left],
	["論理の &", (f) => [`7 & ${f} | 8`], (t) => t.left.right],
	["論理の |", (f) => [`7 | ${f}`], (t) => t.right],
	["論理の ;", (f) => [`7 ; ${f}`], (t) => t.right],
	["字下げの本体の行", (f) => ["t24 : y ?", `\t${f}`, "\ty", ""], (t) => t.right.body.view.rows[0]],
	["手続きの最後の行", (f) => ["t24 : y ?", "\ty", `\t${f}`, ""], (t) => t.right.body.view.rows[1]],
];
// 裸のラムダと括ったラムダ（手続きの行で比べる。行の根では裸のラムダは `?` の木で、並びではない）。
const LAMBDAS24 = ["x ? x + 1", "x ? add x 1", "[x] ? x", "x ? y"];
const solve24 = (lines) => {
	const s = src([...usedDefs(UNITS24, lines.join("\n")), ...lines]);
	try {
		const r = resolve(s);
		return { r, left: r.diagnostics.filter((d) => d.reason === "leftover-lambda").map((d) => d.name) };
	} catch (e) {
		return { refused: `${e.reason} ${e.gate || ""} ${e.message}` };
	}
};
law("24 評価する所に残った丸ごとの関数は、どの評価する所でも `_` と同じ知らせ（R76）：根の F と、比べ・論理の被演算子・手続きの行の F、名前と括りで包んだ F", () => {
	const problems = [];
	const count = { 比べた組: 0, 恒等射: 0, "包んで比べた組": 0, "裸と括ったラムダの行": 0 };
	for (const lam of LAMBDAS24) {
		for (const [label, rowsOf, pick] of [
			["手続きの最初の行", (g) => ["t24 : y ?", `\t${g}`, "\ty", ""], (t) => t.right.body.view.rows[0]],
			["手続きの最後の行", (g) => ["t24 : y ?", "\ty", `\t${g}`, ""], (t) => t.right.body.view.rows[1]],
		]) {
			const bare = solve24(rowsOf(lam));
			const wrapped = solve24(rowsOf(`[${lam}]`));
			count["裸と括ったラムダの行"]++;
			if (bare.refused || wrapped.refused) {
				problems.push(`${label} の ${lam}: ${bare.refused || "通る"}  ⇔  括った: ${wrapped.refused || "通る"}`);
				continue;
			}
			const sb = pick(bare.r.trees[bare.r.trees.length - 1]);
			const sw = pick(wrapped.r.trees[wrapped.r.trees.length - 1]);
			if (!sb || !sw || sb.t !== "unit" || sw.t !== "unit") problems.push(`${label} の ${lam}: ${sb ? show(sb) : "部分木が無い"}  ⇔  括った: ${sw ? show(sw) : "部分木が無い"}`);
			if (bare.left.length !== 1 || wrapped.left.length !== 1) problems.push(`${label} の ${lam} の知らせの数: ${bare.left.length}  ⇔  括った: ${wrapped.left.length}`);
		}
	}
	for (const f of F24) {
		const root = solve24([f]);
		if (root.refused) {
			problems.push(`根の ${f} が断られた: ${root.refused}`);
			continue;
		}
		const rt = root.r.trees[root.r.trees.length - 1];
		if (rt.t !== "unit") {
			problems.push(`根の ${f} が (unit …) でない: ${show(rt)}`);
			continue;
		}
		const isId = root.left.length === 0;
		if (isId) count.恒等射++;
		for (const [label, place, pick] of PLACES24) {
			const o = solve24(place(f));
			count.比べた組++;
			if (o.refused) {
				problems.push(`${label} の ${f} が断られた: ${o.refused}`);
				continue;
			}
			const sub = pick(o.r.trees[o.r.trees.length - 1]);
			if (!sub || show(sub) !== show(rt) || kindOf(sub) !== "A") problems.push(`${label} の ${f}: ${sub ? `${show(sub)} : ${kindOf(sub)}` : "部分木が無い"}  ⇔  根: ${show(rt)}`);
			if (JSON.stringify(o.left) !== JSON.stringify(root.left)) problems.push(`${label} の ${f} の知らせ: ${JSON.stringify(o.left)}  ⇔  根: ${JSON.stringify(root.left)}`);
			// 名前と括りで包む：どこでも `(unit …)` で、知らせの数は同じ。
			for (const [wrapLabel, pre, g] of [
				["名前", ["w24 : " + f], "w24"],
				["括り", [], `(${f})`],
			]) {
				const ow = solve24([...pre, ...place(g)]);
				const orw = solve24([...pre, g]);
				count["包んで比べた組"]++;
				if (ow.refused || orw.refused) {
					problems.push(`${wrapLabel}で包んだ ${f}（${label}）が断られた: ${ow.refused || orw.refused}`);
					continue;
				}
				const sw = pick(ow.r.trees[ow.r.trees.length - 1]);
				const rw = orw.r.trees[orw.r.trees.length - 1];
				if (!sw || sw.t !== "unit" || rw.t !== "unit" || show(sw) !== show(rw)) problems.push(`${wrapLabel}で包んだ ${f}（${label}）: ${sw ? show(sw) : "部分木が無い"}  ⇔  根: ${show(rw)}`);
				if (ow.left.length !== root.left.length || orw.left.length !== root.left.length) problems.push(`${wrapLabel}で包んだ ${f}（${label}）の知らせの数: ${ow.left.length}・根 ${orw.left.length}  ⇔  包まない ${root.left.length}`);
			}
		}
	}
	for (const [k, v] of Object.entries(count)) if (!v) problems.push(`「${k}」の組が無い（法則がその枝を見ていない）`);
	return { problems, note: Object.entries(count).map(([k, v]) => `${k} ${v}`).join("・") };
});

// ---------------------------------------------------------------------------
// 法則25：`$v` の輪を通す形は、同じ値を輪の無い綴りで書いた形と同じ種類（R73、2026-10-26 の §5 Q60 の答え）
// ---------------------------------------------------------------------------
//
// Reader（`$`）は v をその場で評価しないので、輪を閉じる辺が `$v` の所だけなら輪ではない。だから `$v` の輪を通すプログラムの各行の種類（通るか、門の名前）は、
// `$v` を輪の外の値の名前（`u25 : 0`）を読む `$u25` に替えたプログラムと同じ。期待値は書かず、2つを比べる。輪の側は、文の並べ方を全部回しても同じ答え（法則3）。
// 輪の中で参照を `@` で開く形・`$` の無い v も輪にある形・v が値でない形は、輪の側が name-cycle で断る（比べの外、錨で見る）。
const HEADS25 = [
	// [v の右辺, 関数の定義（$R が `$v` か `$u25` に替わる）]
	["f25 1", (b) => `f25 : x ? ${b}`],
	["hv25 [1]", (b) => `hv25 : [x] ? ${b}`],
	["[w ? f25 w] 2", (b) => `f25 : x ? ${b}`],
];
const BODIES25 = ["x , $R", "$R , x", "[x $R]", "x , ($R)", "(x , $R) , 1", "x , [$R , 2]"];
// 輪の外の側で門に当たる本体（確かめの直し、2026-10-26）。輪の外の側が断れば、輪の側も断る（門の名前は、v の種類が決まらずに R73 の残りの name-cycle になる
// ことがあるので比べない）。最初の版はこの組を持たず、`v : $v + 1` でプロセスが落ちる形に届かなかった。
const REFUSED25 = ["$R + 1", "x , $R + 1", "x , [$R]~", "x , |$R|", "$R == 1", "x , $R * 2"];
// v の右辺に直に書いた形（輪は `v` → `v`）。輪の外の綴りは `v25 : <body の $R を $u25>`。
const DIRECT25 = ["1 , $R", "$R , 1", "[1 $R]", "$R + 1", "1 + $R", "$R == 1", "|$R|", "[$R]~", "1 , $R + 1", "[$R,] 1"];
const USES25 = [["v25"], ["w25 : v25", "w25"], ["v25 , 2"], ["[v25 1]"], ["n25 : [~q] ? q", "n25 v25"]];
// skip は、輪の無い綴りの頭に足した `u25 : 0` の行（比べの外）。
const ans25 = (lines, skip = 0) => {
	try {
		const r = resolve(src(lines));
		return `通る ${r.trees.slice(skip).map((t) => kindOf(t)).join(" ")}`;
	} catch (e) {
		return `断り ${e.reason} ${e.gate || ""}`;
	}
};
const perms25 = (xs) => (xs.length <= 1 ? [xs] : xs.flatMap((x, i) => perms25([...xs.slice(0, i), ...xs.slice(i + 1)]).map((p) => [x, ...p])));
law("25 `$v` の輪を通す形は、`$v` を輪の外の値の `$u25` に替えた形と同じ種類（R73）。輪の側は並べ方に依らない", () => {
	const problems = [];
	const count = { 比べた組: 0, 並べ方: 0, "輪の側が通る": 0, "外の側が断る組": 0, "右辺に直に書いた組": 0 };
	for (const [rhs, def] of HEADS25) {
		for (const body of REFUSED25) {
			const ring = [`v25 : ${rhs}`, def(body.replace("$R", "$v25")), "v25"];
			const free = ["u25 : 0", `v25 : ${rhs}`, def(body.replace("$R", "$u25")), "v25"];
			const a = ans25(ring);
			const b = ans25(free, 1);
			count["外の側が断る組"]++;
			if (!b.startsWith("断り")) problems.push(`外の側が断るはずの本体 ${body} が通った：${free.join(" ⏎ ")}：${b}`);
			else if (!a.startsWith("断り")) problems.push(`${ring.join(" ⏎ ")}：${a}  ⇔  輪の無い綴り：${b}`);
		}
	}
	for (const body of DIRECT25) {
		const a = ans25([`v25 : ${body.replace("$R", "$v25")}`, "v25"]);
		const b = ans25(["u25 : 0", `v25 : ${body.replace("$R", "$u25")}`, "v25"], 1);
		count["右辺に直に書いた組"]++;
		// 門の名前まで同じ（v の右辺の門は、その門の行の断り、resolve.js の selfReaderHolds）。通る形は同じ種類。
		if (a !== b) problems.push(`v25 : ${body.replace("$R", "$v25")}：${a}  ⇔  輪の無い綴り：${b}`);
	}
	for (const [rhs, def] of HEADS25) {
		for (const body of BODIES25) {
			for (const use of USES25) {
				const ring = [[`v25 : ${rhs}`], [def(body.replace("$R", "$v25"))], use];
				const free = [["u25 : 0"], [`v25 : ${rhs}`], [def(body.replace("$R", "$u25"))], use];
				const a = ans25(ring.flat());
				const b = ans25(free.flat(), 1);
				count.比べた組++;
				if (a !== b) problems.push(`${ring.flat().join(" ⏎ ")}：${a}  ⇔  輪の無い綴り：${b}`);
				if (a.startsWith("通る")) count["輪の側が通る"]++;
				// 輪の側の並べ方（定義の2文だけを入れ替える。使う行は後ろ）
				for (const p of perms25([0, 1])) {
					const c = ans25([...p.flatMap((k) => ring[k]), ...use]);
					count.並べ方++;
					if (c !== a) problems.push(`並べ方で割れた ${p.join(",")}：${c}  ⇔  ${a}`);
				}
			}
		}
	}
	// 錨：輪の外の断り（name-cycle のまま）と、輪の内で通る形の種類。
	const anchor = (lines, want) => {
		const a = ans25(lines);
		if (!a.startsWith(want)) problems.push(`錨 ${lines.join(" ⏎ ")}：${a}（${want} のはず）`);
	};
	anchor(["v25 : f25 1", "f25 : x ? @[$v25]", "v25"], "断り name-cycle");
	anchor(["v25 : f25 1", "f25 : x ? x , $v25 , v25", "v25"], "断り name-cycle");
	// v が関数（2026-10-27 の片8 の R103：持ち上げだけを通る輪は値の輪ではないので通る。前は値を読む参照の読みが外れて name-cycle）
	anchor(["add : x y ? x + y", "v25 : add (f25 1)", "f25 : x ? x , $v25", "v25 3"], "通る A A A A");
	anchor(["v25 : f25 1", "f25 : x ? x , $v25", "v25"], "通る A A A");
	anchor(["v25 : 1 , $v25", "v25"], "通る A A");
	// 輪の中で `' 0` で下ろす（2026-10-27 の片8 の R102・R103：`$v ' 0` は v で、下ろす所を通る輪。前は `'` が参照の先を読むかが決まらず、断る側に倒していた）
	anchor(["v25 : 1 , ($v25 ' 0)", "v25"], "断り name-cycle");
	anchor(["v25 : 1 , ||$v25||", "v25"], "通る A A"); // ノルムは先を読まない（`||$_||` は 1）
	for (const [k, v] of Object.entries(count)) if (!v) problems.push(`「${k}」の組が無い（法則がその枝を見ていない）`);
	return { problems, note: Object.entries(count).map(([k, v]) => `${k} ${v}`).join("・") };
});

// ---------------------------------------------------------------------------
// 法則26：本体の返す所に置いた F は、1行の本体の根に置いた F と同じ答え（R33・R76、2026-10-26 の確かめの直し。§5 Q35）
// ---------------------------------------------------------------------------
//
// 本体の返す所は、1行の本体の根（`t26 : y ? F`）・1行だけの字下げの本体（`⇥F`）・枝の値（`⇥y > 0 : F`）・枝の後の既定の行（`⇥F`）。どこに置いても、断るなら
// 同じ門、通るなら `t26 5` の種類と知らせの数が同じ。期待値は書かず、1行の本体の根と比べる。2行以上の手続きの最後の行は `&` の右の
// 被演算子（法則24）で、返す所ではない。最初の版の R76 は字下げの返す所を評価する所にしていて、`⇥[+ m]` が `_` で通り、1行の `[+ m]` の G16 と割れた。
// 片イ（R125、2026-11-02）から G16 は廃止：裸の関数は `_` を返して bare-function-return（information）で知らせるので、断る組は無くなり、
// 知らせの数（裸の関数の information）も比べる。
const DEFS26 = [INC, "add : x y ? x + y", "f2 : x y ? x - y", "i : !_"];
const UNITS26 = toUnits(DEFS26);
const F26 = ["inc", "add 1", "add y", "inc add 5", "[+ 1]", "[+ y]", "[+ inc]", "([+ y])", "(inc)", "||inc||", "add !_ 3", "i", "!_", "x ? x + y", "[x ? x + y]", "y", "inc y", "y + 1", "5 inc", "$inc", "$[+ y]", "inc == y", "y & inc", "5"];
const PLACES26 = [
	["1行だけの字下げの本体", (f) => ["t26 : y ?", `\t${f}`, ""]],
	["枝の値", (f) => ["t26 : y ?", `\ty > 0 : ${f}`, "\ty", ""]],
	["枝の後の既定の行", (f) => ["t26 : y ?", "\ty > 0 : y", `\t${f}`, ""]],
];
const ans26 = (lines) => {
	const s = src([...usedDefs(UNITS26, lines.join("\n")), ...lines, "t26 5"]);
	try {
		const r = resolve(s);
		const left = r.diagnostics.filter((d) => d.reason === "leftover-lambda").length;
		const bare = r.diagnostics.filter((d) => d.reason === "bare-function-return" && d.severity === "information").length;
		return `通る ${kindOf(r.trees[r.trees.length - 1])} 知らせ${left} 裸の関数${bare}`;
	} catch (e) {
		return `断り ${e.reason} ${e.gate || ""}`;
	}
};
law("26 本体の返す所（1行だけの字下げの本体・枝の値・枝の後の既定の行）に置いた F は、1行の本体の根に置いた F と同じ答え（R33・R76・R125）", () => {
	const problems = [];
	const count = { 比べた組: 0, 通る組: 0, 裸の関数を知らせる組: 0 };
	let refused = 0;
	for (const f of F26) {
		const root = ans26([`t26 : y ? ${f}`]);
		if (root.startsWith("断り")) refused++;
		else count.通る組++;
		if (/裸の関数[1-9]/.test(root)) count.裸の関数を知らせる組++;
		for (const [label, place] of PLACES26) {
			const a = ans26(place(f));
			count.比べた組++;
			// 枝の値・既定の行は、枝の条件 `y > 0` が A なので、返す所の答えは1行の根と同じ（通るなら種類、断るなら門）。
			if (a !== root) problems.push(`${label} の ${f}：${a}  ⇔  1行の本体の根：${root}`);
		}
	}
	for (const [k, v] of Object.entries(count)) if (!v) problems.push(`「${k}」の組が無い（法則がその枝を見ていない）`);
	return { problems, note: [...Object.entries(count).map(([k, v]) => `${k} ${v}`), `断る組 ${refused}`].join("・") };
});

// ---------------------------------------------------------------------------
// 法則27（2026-11-04 の寄せ1 で消した）：局所の定義は、同じ定義をファイルの定義に置いた形と同じ答え（R80、2026-10-26）
// ---------------------------------------------------------------------------
//
// R128（寄せ1、U〔答え〕2026-11-04「入って」。出どころ U〔答え〕[2026-10-29 12:18:19 32fe4b9c]「ガイドに戻す」）で、本体の字下げの `:` の行は、左が名前1つでも
// 枝（match_case）になり、本体に局所の定義は無くなった。比べる片方の綴り（本体の局所の定義）が無くなったので、法則ごと消した（寄せ1 の文面の「消える物」）。
// 番号は詰めない（28 から後は前の番号のまま）。本体の `:` の行が枝であることは、法則45（条件が未定義の名前の枝は、その行を消した本体と同じ値）と法則46
// （`⇥x : v` は `⇥(x) : v` と同じ）が見る。枝の読みの答えは coproduct.test.js（R128〜R130 の行）と interpret.test.js が期待値で見る。

// ---------------------------------------------------------------------------
// 法則28：素の関数の単相化は β と同じ種類で、括りの関数で同じ本体を書いた形とも同じ（R81、2026-10-26。§5 Q45 の答え）
// ---------------------------------------------------------------------------
//
// 比べる綴り：素の関数 `F : p1 … pn ? B` を、印のある実引数（関数の番地・値を読む参照・番地の点と差・書いた `_` と分かる値）を含む a1 … an で呼んだ形について、
// (a) 単相化 `F a1 … an`、(b) β：印のある実引数の仮引数を本体に `[ai]` で書き込み、印の無い仮引数は仮引数のまま残した `bf : (残り) ? B[pi := [ai]]` ⏎ `bf (残りの実引数)`
// （印の無い実引数は今のまま中身の見えない A なので、書き込まない。残りが無ければ `bf : y9 ? …` ⏎ `bf 0`）、(c) 括りの関数で同じ本体を書いた `pt : p1 … pn [~d9] ? B` ⏎
// `pt a1 … an []`（最後の括りは空の List を受けるだけで本体に出ない）。2026-10-27 の R90（§5 Q70 の答え）から、頭の名前がある括り（前の `[d9]`）に空の List が来ると
// 分解が立たずに本体を読まない（`_`）ので、空でも立つ残りだけの括り `[~d9]` にした（本体は同じに読む）。
// 包み：(d) `(F a1) a2 …`・`p : F a1 ⏎ p a2 …`・名前で渡す `q : a1 ⏎ F q a2 …`・括り1つ `F [a1] a2 …` が (a) と同じ。
// 実体の分け合い：(e) 同じ F を印の違う実引数で呼ぶ2行（`F A1 …` ⏎ `F A2 …`）の各行が、1行ずつ解いた答えと同じ（両方の並べ方で）。
// 何を同じと見るか：断れば reason と門（実体の名指しは関数が違うので見ない）、通れば最後の行の種類。期待値は書かない。
// なぜ同じか：R81（主の Claude の傾き「単相化する（引数で決まる多相は単相化の線）」に U〔答え〕[2026-10-25 08:44 c8ccdd69]「Q10 と Q45 は、君の傾きを採用できそうだと
// 思う。」）。素の関数の適用は本体への代入（β）で、印のある実引数を受けた実体の本体は、その実引数を書き込んだ本体と同じ読み。括りの関数（R24）と同じ仕組みで実体を
// 作るので、同じ本体の括りの関数とも同じ。名前は右辺を指し（`:` はメタ）、括り1つは中身と同じ（[x] ≅ x）。
// 比べの外：素の関数の定義の行（印の無い1回の読み）が断る形（`@f vs~` の G19・`x @f` の G6 など）。定義の行は今のまま印の無い読みで断る（§5 Q45 の残り）ので、
// 数だけ数える。本体が番地の点・差を返す形（`x + 0x10`）は、(b) の bf も関数なので、3つとも答えに印を持たせられずに G21（§5 Q66）で揃う。
// 2026-10-26 の確かめの直しで足した組（下の (f)〜(h)）：(f) 印の無い実引数の仮引数に `$` を付ける本体は β だけと比べる（(c) の括りの関数は、実体で渡された形の
// 見えない値の `$x` を G20 で断るので、素の関数と読みが違う。(a)≡(c) は同じ bindParams を両側に置くので、そこが割れても見えなかった）。(g) `$` で包んで渡す
// 再帰しない鎖は、括りの関数の無いファイルでも、β と、関係の無い定義を足した形と同じ。(h) 自分の仮引数の `$` を自分に渡す再帰は、断るかが関係の無い定義に依らず、
// JS の例外で落ちない。
const DEFS28 = [INC, "double : x ? x * 2", "add : x y ? x + y", "uu : x ? [,] x", "mp2 : h [~l] ? [@h,] l~", "fold : f [~l] ? @f l~", "vs : 1 , 2 , 3", "un : _", "five : 5", "hd : [x ~xs] ? x", "use : f x ? @f x", "hx : [k] f ? @f 1"];
const UNITS28 = toUnits(DEFS28);
// [名前, 仮引数, 本体（字下げの本体は ⏎ で行を分ける）]
const PL28 = [
	["u1", ["f", "x"], "@f x"], ["u2", ["f"], "@f vs~"], ["u3", ["f"], "$f"], ["u4", ["f"], "hx [1] $f"], ["u5", ["x"], "x + 0x10"], ["u7", ["y"], "y"], ["u8", ["x", "y"], "x - y"],
	["u9", ["f", "x"], "use f x"], ["u12", ["f", "x"], "x @f"], ["u13", ["f"], "[@f,] vs"], ["u14", ["x"], "(x + 0x10) - x"], ["u15", ["f"], "@[$f] 1"], ["u16", ["p", "q"], "p - q"],
	["u17", ["f"], "fold $f vs"], ["u18", ["f", "x"], "@f (@f x)"], ["u20", ["f"], "mp2 $f vs"], ["u21", ["x", "y"], "k : x , y ⏎ k"], ["u22", ["f", "x"], "w : @f x ⏎ w"],
	["u23", ["x"], "x == $vs"], ["u24", ["f", "x"], "hx [x] f"],
];
// 2026-10-27 の片6 の R94（§5 Q75 (a) の答え）から、値の口に書いた `[_]` は中身が詰まって `[]` になる書いた括りで、同じ位置に書いた `_` と同じ（穴か、末尾で消える）。
// 印のある実引数（R63 の「`_` と分かる値」）ではなくなったので、`[_]` を ARG28 から外した（片5 までは `un` と同じ印 zero の実引数として比べていた）。名前の `un` と、`q28 : [_]` の
// ように名前を通した `[_]` は今のまま R63 の印のある実引数で、書いた `[_]` と答えが割れる（`u1 [_] 5` は穴、`q28 : [_]` ⏎ `u1 q28 5` は印 zero の実体。§5 Q75 (e)）。
// 2026-10-28 の片9b（R112）：名前の `un` も、素の関数の口（値の口）では書いた `_` と同じに消える（`u1 un 5` は `u1 5`）ので、印 zero の実引数ではなくなった。ARG28 から
// 外した（上の注の「名前の `un` と…今のまま R63 の印のある実引数」は前の版の記録。値の口で `_` と分かる値が消える側は法則43 が見る）。
const ARG28 = ["$inc", "$add", "$uu", "$_", "$!_", "$[w ? w]", "$vs", "$5", "$five", "($vs + 0x10)", "($vs - $five)", "$(add 1)", "$hd"];
const marked28 = (a) => a.startsWith("$") || a.startsWith("(");
const subst28 = (body, ps, as) => body.replace(/[A-Za-z][A-Za-z0-9]*/g, (w) => (ps.includes(w) ? `[${as[ps.indexOf(w)]}]` : w));
const fnLines28 = (head, b) => (b.includes(" ⏎ ") ? [`${head} ?`, ...b.split(" ⏎ ").map((l) => `\t${l}`), ""] : [`${head} ? ${b}`]);
const ans28 = (lines) => {
	const o = outcome(src([...usedDefs(UNITS28, lines.join("\n")), ...lines]));
	if (o.crash) return `例外 ${o.crash}`;
	if (o.refused) return `断り ${o.refused.reason} ${o.refused.gate}`;
	return `通る ${lastOf(o).kind}`;
};
law("28 素の関数の単相化は β と同じ種類で、括りの関数で同じ本体を書いた形とも同じ（R81）：F a… と bf …（印のある実引数を書き込んだ本体）と pt a… []、包み・印の違う2行", () => {
	const problems = [];
	const count = { 比べた組: 0, 通る: 0, 断る: 0, "定義の行が断る（比べの外、§5 Q45 の残り）": 0, "包みの組": 0, "印の違う2行": 0 };
	for (const [name, ps, body] of PL28) {
		const defLines = fnLines28(`${name} : ${ps.join(" ")}`, body);
		if (ans28(defLines).startsWith("断り")) {
			count["定義の行が断る（比べの外、§5 Q45 の残り）"]++;
			continue;
		}
		for (const a of ARG28) {
			for (const b of ["5", "$inc"]) {
				const as = ps.length === 1 ? [a] : [a, b];
				if (!as.some(marked28)) continue;
				const mono = ans28([...defLines, `${name} ${as.join(" ")}`]);
				const keep = ps.filter((p, i) => !marked28(as[i]));
				const bLines = [...fnLines28(`bf : ${keep.length ? keep.join(" ") : "y9"}`, subst28(body, ps.filter((p, i) => marked28(as[i])), as.filter(marked28))), `bf ${keep.length ? as.filter((x) => !marked28(x)).join(" ") : "0"}`];
				const beta = ans28(bLines);
				const pat = ans28([...fnLines28(`pt : ${ps.join(" ")} [~d9]`, body), `pt ${as.join(" ")} []`]);
				count.比べた組 += 2;
				const tag = `${name} ${as.join(" ")}（本体 ${body}）`;
				if ([mono, beta, pat].some((x) => x.startsWith("例外"))) {
					problems.push(`${tag}：例外 ${mono} / ${beta} / ${pat}`);
					continue;
				}
				if (mono !== pat) problems.push(`${tag}：単相化 ${mono}  ⇔  括りの関数 ${pat}`);
				if (mono !== beta) problems.push(`${tag}：単相化 ${mono}  ⇔  β ${beta}（${bLines.slice(-2).join(" ⏎ ")}）`);
				else count[mono.startsWith("通る") ? "通る" : "断る"]++;
				// (d) 包み
				const rest = as.slice(1).join(" ");
				const wraps = [
					[...defLines, `(${name} ${as[0]})${rest ? ` ${rest}` : ""}`],
					[...defLines, `p28 : ${name} ${as[0]}`, `p28${rest ? ` ${rest}` : ""}`],
					[...defLines, `q28 : ${as[0]}`, `${name} q28${rest ? ` ${rest}` : ""}`],
					[...defLines, `${name} [${as[0]}]${rest ? ` ${rest}` : ""}`],
				];
				for (const w of ps.length === 1 ? wraps.slice(2) : wraps) {
					count.包みの組++;
					const x = ans28(w);
					if (x !== mono) problems.push(`包み ${w.slice(defLines.length).join(" ⏎ ")}：${x}  ⇔  ${name} ${as.join(" ")}：${mono}`);
				}
			}
		}
		// (e) 印の違う2行：各行は1行ずつ解いた答えと同じ（実体の鍵が印を見るので、分け合わない）。
		const pick = ARG28.filter((x) => x.startsWith("$")).slice(0, 6);
		for (let i = 0; i < pick.length; i++) {
			for (let j = 0; j < pick.length; j++) {
				if (i === j) continue;
				const call = (a) => `${name} ${ps.length === 1 ? a : `${a} 5`}`;
				const one = (a) => ans28([...defLines, call(a)]);
				const both = (x, y) => {
					const o = outcome(src([...usedDefs(UNITS28, [...defLines, call(x), call(y)].join("\n")), ...defLines, call(x), call(y)]));
					if (o.crash || o.refused) return null;
					return o.trees.slice(-2).map((t) => t.kind);
				};
				const ax = one(pick[i]);
				const ay = one(pick[j]);
				if (!ax.startsWith("通る") || !ay.startsWith("通る")) continue;
				count["印の違う2行"]++;
				const ks = both(pick[i], pick[j]);
				if (!ks || `通る ${ks[0]}` !== ax || `通る ${ks[1]}` !== ay) problems.push(`印の違う2行 ${call(pick[i])} ⏎ ${call(pick[j])}：${JSON.stringify(ks)}  ⇔  1行ずつ ${ax} / ${ay}`);
			}
		}
	}
	// (f) β だけで比べる本体（2026-10-26 の確かめの直し）：印の無い実引数を受けた仮引数に `$` を付ける本体。素の関数の印の無い仮引数は、定義の行の読みと同じく
	// 裸の仮引数のまま読む（`$x` は値を読む参照。resolve.js の bindParams の注）ので、単相化は β と同じ。(c) の括りの関数は比べない：括りの関数の実体で渡された
	// 形の見えない値の `$x` は G20（R63 の残り、§5 Q64）で、括りの関数と素の関数の裸の仮引数の読みの違い（同じ仕組みを両側に置くと、この違いが見えなかった）。
	// 前は単相化の実体が印の無い実引数も括りの関数と同じ形の見えない値で受け、`pz : f x ? $x` の `pz $inc 5` が G20（`pz 1 5` と β の `bf : x ? $x` ⏎ `bf 5` は A）。
	const PL28B = [["v1", ["f", "x"], "$x"], ["v2", ["f", "x"], "@f $x"], ["v3", ["f", "x"], "x , $x"], ["v4", ["f", "x"], "hx [1] $x"], ["v5", ["f", "x"], "w : x ⏎ $w"], ["v6", ["x", "f"], "$[x , !_]"]];
	for (const [name, ps, body] of PL28B) {
		const defLines = fnLines28(`${name} : ${ps.join(" ")}`, body);
		for (const a of ARG28) {
			for (const b of ["5", "five", "vs"]) {
				const as = ps[0] === "f" ? [a, b] : [b, a];
				const mono = ans28([...defLines, `${name} ${as.join(" ")}`]);
				const keep = ps.filter((p, i) => !marked28(as[i]));
				const bLines = [...fnLines28(`bf : ${keep.join(" ")}`, subst28(body, ps.filter((p, i) => marked28(as[i])), as.filter(marked28))), `bf ${as.filter((x) => !marked28(x)).join(" ")}`];
				const beta = ans28(bLines);
				const plainCall = ans28([...defLines, `${name} ${as.map((x) => (marked28(x) ? "1" : x)).join(" ")}`]);
				count["β だけ（印の無い仮引数の `$`）"] = (count["β だけ（印の無い仮引数の `$`）"] || 0) + 1;
				if (mono !== beta) problems.push(`β だけ ${name} ${as.join(" ")}（本体 ${body}）：単相化 ${mono}  ⇔  β ${beta}（${bLines.slice(-2).join(" ⏎ ")}）`);
				// 印の無い仮引数の読みは、関係の無い口の印に依らない：本体が印の口 f を使わないなら、印の口を数に替えた呼び出し（定義の行の印の無い読み）と同じ答え。
				if (!/\bf\b/.test(body) && mono !== plainCall) problems.push(`β だけ ${name} ${as.join(" ")}：単相化 ${mono}  ⇔  印の口を数にした ${plainCall}`);
			}
		}
	}
	// (g) `$` で包んで渡す、再帰しない素の関数の鎖（2026-10-26 の確かめの直し）：鎖 `c1 $inc` は、β で書き下した `cL $[$[…$inc…]]` と同じで、関係の無い定義（括りの関数・
	// 素の関数）を足しても答えが変わらない。実体の深さの上限は実体を作る関数（括りの関数と素の関数）の数で決める（resolve.js の writtenDepth）。前は括りの関数だけを
	// 数え、括りの関数の無いファイルで3段を超える鎖を深さの門で断り、関係の無い括りの関数を1つ足すと通った。
	for (let L = 2; L <= 6; L++) {
		const chainLines = [...[...Array(L - 1).keys()].map((i) => `c${i + 1} : f ? c${i + 2} $f`), `c${L} : f ? 5`];
		const beta = `c${L} ${"$[".repeat(L - 1)}$inc${"]".repeat(L - 1)}`;
		const forms = [
			[INC, ...chainLines, "c1 $inc"],
			[INC, ...chainLines, beta],
			[INC, ...chainLines, "zz : [q] ? q", "c1 $inc"],
			[INC, ...chainLines, "zp : y ? y", "zq : y ? y", "c1 $inc"],
		];
		const outs = forms.map((f) => {
			const o = outcome(src(f));
			return o.crash ? `例外 ${o.crash}` : o.refused ? `断り ${o.refused.reason} ${o.refused.gate}` : `通る ${lastOf(o).kind}`;
		});
		count["`$` で包む鎖"] = (count["`$` で包む鎖"] || 0) + 1;
		if (outs.some((x) => x !== outs[0])) problems.push(`\`$\` で包む鎖 ${L} 段：${outs.join(" / ")}`);
	}
	// (h) 自分の仮引数の `$` を自分に渡す再帰（印が段ごとに深くなる多相の再帰、§5 Q45 の残り）：断るかは、関係の無い定義を足しても変わらない（門か守りかは上限で
	// 変わりうるので、断るかだけを見る）。JS の例外で落ちない。
	for (const rec of [["r2 : f ? r2 $f"], ["cnt : f n ? n == 0 & 0 | cnt $f (n - 1)"], ["r8 : f ? r8 $(f3 f f)", "f3 : a b c ? a + b + c"]]) {
		const outs = [rec, [...rec, "zz : [q] ? q"], [...rec, "zp : y ? y", "zq : y ? y"]].map((f) => outcome(src(f)));
		count["`$` を自分に渡す再帰"] = (count["`$` を自分に渡す再帰"] || 0) + 1;
		if (outs.some((o) => o.crash)) problems.push(`再帰 ${rec[0]}：例外 ${outs.map(brief).join(" / ")}`);
		else if (outs.some((o) => !!o.refused !== !!outs[0].refused)) problems.push(`再帰 ${rec[0]}：断るかが割れた ${outs.map(brief).join(" / ")}`);
	}
	for (const [k, v] of Object.entries(count)) if (!v) problems.push(`「${k}」の組が無い（法則がその枝を見ていない）`);
	return { problems, note: Object.entries(count).map(([k, v]) => `${k} ${v}`).join("・") };
});

// ---------------------------------------------------------------------------
// 法則29：前置 `@` の値の定義の名前は、括った `@[p]` と同じ答え（R82、2026-10-26。§5 Q45 の残りの答え）
// ---------------------------------------------------------------------------
//
// 比べる綴り：値の定義 `p : R` について、文脈 C の (a) `C[@p]` と (b) `C[@[p]]`、関数の本体の局所の定義に置いた (c) `tt : x ?` ⏎ `⇥p : R` ⏎ `⇥C[@p]` と (d) `⇥C[@[p]]`
// （(c)(d) は寄せ1 で読みが変わった。下の注）。
// 何を同じと見るか：断れば reason と門、通れば最後の行の木（`@[p]` を `@p` に読み替えて）と種類。期待値は書かない。
// なぜ同じか：`:` はメタで名前は右辺を指し、括り1つは中身と同じ（[x] ≅ x）なので、`@p` は `@[p]` と同じ先を開く（R82。主の Claude の決定の文、§4 R82 の出どころ）。
// 輪も同じ：右辺が `@p` を通って自分に戻る値の定義は、`@[p]` と同じく name-cycle。
// 2026-11-04 の寄せ1（R128）で (c)(d) を書き直した：本体の `⇥p : R` は枝で何も定義しない（局所の定義は無くなった）ので、(c)(d) は「本体の1行目に同じ名前の枝
// `p : R` を置いても、`@p` と `@[p]` は同じ先を開く」の比べにした。先は、ファイルに `p : R` があればファイルの p（(c)）、無ければ未定義の名前（(e)、R111）。
// どれも本体の行を見ない（細目7 の `$名前` と同じ読み）。前の (c)(d) は最後の行 `tt 1` の木と種類だけを比べていたので、本体を含む tt の定義の行の木（`@[p]` を
// `@p` に読み替えて）と `tt 1` の種類と診断を比べる。
const DEFS29 = [INC, "add : x y ? x + y", "vs : 1 , 2 , 3", "five : 5", "un : _"];
const UNITS29 = toUnits(DEFS29);
const RHS29 = ["$inc", "$vs", "$vs + 0x10", "$vs - $five", "5", "vs", "$_", "$!_", "[$inc]", "inc", "$(add 1)", "un", "$un", "0x10"];
const CTX29 = [(e) => e, (e) => `${e} 3`, (e) => `5 ${e} 3`, (e) => `inc ${e} 5`, (e) => `${e} vs~`, (e) => `[${e},] vs`, (e) => `${e} + 1`, (e) => `(${e}) == 5`];
const ans29 = (lines, rename) => {
	const o = outcome(src([...usedDefs(UNITS29, lines.join("\n")), ...lines]));
	if (o.crash) return `例外 ${o.crash}`;
	if (o.refused) return `断り ${o.refused.reason} ${o.refused.gate}`;
	const t = lastOf(o);
	return `通る ${rename ? t.text.split("@[p]").join("@p") : t.text} : ${t.kind}`;
};
// 本体の枝の比べ（(c)・(e)）の答え：tt の定義の行の木（本体ごと）・`tt 1` の種類・診断
const ansBody29 = (lines, rename) => {
	const o = outcome(src([...usedDefs(UNITS29, lines.join("\n")), ...lines]));
	if (o.crash) return `例外 ${o.crash}`;
	if (o.refused) return `断り ${o.refused.reason} ${o.refused.gate}`;
	const tt = o.trees.find((t) => t.text.startsWith("(: tt "));
	const text = tt ? tt.text : "?";
	return `通る ${rename ? text.split("@[p]").join("@p") : text} || tt 1：${lastOf(o).kind} || ${o.diag.join(" ")}`;
};
law("29 前置 `@` の値の定義の名前は、括った `@[p]` と同じ答え（R82）：C[@p] と C[@[p]]、本体に同じ名前の枝 `p : R` を置いても（R128）、輪も", () => {
	const problems = [];
	const count = { 比べた組: 0, 通る: 0, 断る: 0, "(c) 本体の枝の後ろ（ファイルに p）": 0, "(e) 本体の枝の後ろ（p は未定義）": 0, "本体の枝の後ろで通る": 0 };
	for (const r of RHS29) {
		for (const c of CTX29) {
			const file = [ans29([`p : ${r}`, c("@p")]), ans29([`p : ${r}`, c("@[p]")], true)];
			count.比べた組++;
			if (file[0] !== file[1]) problems.push(`p : ${r} ⏎ ${c("@p")}：${file[0]}  ⇔  ${c("@[p]")}：${file[1]}`);
			else count[file[0].startsWith("通る") ? "通る" : "断る"]++;
			for (const [label, pre] of [
				["(c) 本体の枝の後ろ（ファイルに p）", [`p : ${r}`]],
				["(e) 本体の枝の後ろ（p は未定義）", []],
			]) {
				const body = [ansBody29([...pre, "tt : x ?", `\tp : ${r}`, `\t${c("@p")}`, "", "tt 1"]), ansBody29([...pre, "tt : x ?", `\tp : ${r}`, `\t${c("@[p]")}`, "", "tt 1"], true)];
				count.比べた組++;
				count[label]++;
				if (body[0] !== body[1]) problems.push(`${label} p : ${r} ⏎ ${c("@p")}：${body[0]}  ⇔  ${c("@[p]")}：${body[1]}`);
				else if (body[0].startsWith("通る")) count["本体の枝の後ろで通る"]++;
			}
		}
	}
	// 輪：右辺が `@p` を通って自分に戻る値の定義（`@[p]` と同じ name-cycle）。
	for (const body of ["@v29", "@v29 1", "inc @v29", "[@v29,] vs"]) {
		const a = ans29(["v29 : f29 1", `f29 : x ? ${body}`, "v29"]);
		const b = ans29(["v29 : f29 1", `f29 : x ? ${body.replace("@v29", "@[v29]")}`, "v29"]);
		count.比べた組++;
		if (a !== b) problems.push(`輪 f29 : x ? ${body}：${a}  ⇔  @[v29]：${b}`);
	}
	for (const [k, v] of Object.entries(count)) if (!v) problems.push(`「${k}」の組が無い（法則がその枝を見ていない）`);
	return { problems, note: Object.entries(count).map(([k, v]) => `${k} ${v}`).join("・") };
});

// ---------------------------------------------------------------------------
// 法則30：末尾の書いた `_` を付けた並びと付けない並びは、どこでも同じ木・同じ種類・同じ知らせ（R28、2026-10-26 に書き直した）
// ---------------------------------------------------------------------------
//
// 比べる綴り：並び X について、文脈 C の (a) `C[X]` と `C[X _]`。文脈は、根・括りに当てる `(X) 5`・括りを合成に置く `double (X) 5`・名前の右辺 `w30 : X` ⏎ `w30 5`
// と ⏎ `w30`・値の上 `5 X`・比べの被演算子 `X == 6`・手続きの行・`$[X]`・本体の根 `t31 : y ? X`。(b) 後ろが関数の `_`（引数の並びの終わり）も、`C[X _ G]` と `C[X G]`
// （G は inc・add。根・括り・名前の右辺）。X は頭の種類を全部（素の関数とその部分適用・合成・名前や括りで包んだ合成と部分適用・点なし・貪欲な単項・`[,]`・括りの
// 関数・R34 の k < n の穴の関数・穴とカリー化・恒等射・既定値のある関数の既定値の無い口・前置 `@`・値・断る形）。
// 何を同じと見るか：断れば reason と門、通れば全部の行の木・種類と、診断の reason と名前（書いた括りと遅らせた本体の綴りには付けた `_` が見えるので、`X _` を X に
// 読み替えて比べる）。期待値は書かない。
// なぜ同じか：並びの最後の書いた `_` は、R15 と同じく消える印（U〔答え〕[2026-10-26 10:15 c8ccdd69] のボタン「8 でいい」：「末尾の書いた `_` は消えて、部分適用も
// 合成も関数のまま残る。」。ボタンの文は主の Claude の物）。消した後の関数は関数のまま残り、評価する所で何も受けずに残れば R42 の `_`。だから、付けても付けなくても
// 同じ並びで、どの文脈でも答えが同じでなければならない。後ろが関数の `_` は、決定の文の `add _ inc` は `add inc`（左からの畳み込みのまま）。
// 比べの外：`_` が畳む2項の点なしの被演算子の印になる所（R31、`[+] 1 _` は `1 + _`）・既定値のある口に当たる所（R39、`go 1 _` は zs の既定値）・`,` の被演算子の並び
// （`1 , inc _` は G3 のまま。§4 R28 の R の所）。X はそれを含まない物にした（`go` は最初の口に既定値が無いので入れる）。
// 2026-10-26 の確かめの直しで足した所：
// - 1行の括りの中が点なしの形の項の後ろに書いた `_` だけが続く並び（X が `!_` で、文脈が X を1行の括りに置く所。`(!_ _) 5`・`double (!_ _) 5`・`$[!_ _]`）は、
//   末尾の `_` を消してから括りの形を見れば否定の点なし `(!_)`、書いた項で見れば恒等射（R29）で割れるので、`_` を付けた側は G7（§5 Q74）。比べずに G7 を見る。
//   → 2026-10-28 の R108（§5 Q74 (c) を閉じた）から、書いた項どおり恒等射なので、恒等射の名前 i を括った綴りと比べる（`(!_)` は否定の点なしで別の関数）。
//   前は ans30 の綴りの読み替え（`[!_ _]` を `[!_]` に）が、恒等射の括りと否定の点なしの括りの違いを隠して通していた（確かめの指摘）。読み替えに頼らずに種類の
//   違いが出る文脈として、括りの後ろに関数と値を置く `(X) inc 5` も足した（恒等射なら R74 で消えて `inc 5`、否定なら合成）。
// - 後ろが関数の `X _ G` と `X G` の比べ (b) は、G の後ろに何も続かない所だけ。G の後ろに値が続く `X _ G 5` は内側の `_`（5 が `_` の口に入るか次の口に入るかで
//   割れる、§5 Q74）で、比べない（試験の「R28」の節の断る行が見る）。
const DEFS30 = [INC, "double : x ? x * 2", "add : x y ? x + y", "f2 : x y ? x - y", "f3 : a b c ? a + b + c", "io1 : [say] ? say 21", "pb : [a] [b] ? a", "mx : a [b] ? a",
	"n : [~x] ? x", "i : !_", "q : inc add 5", "a1 : add 5", "uu : m ? [,] m", "vs : 1 , 2 , 3", "go :", "\t\tys", "\t\tzs : 3", "\t? ys", ""];
const X30 = [
	"5", "inc 5", "add 2 3", "add 3", "add", "inc", "inc inc", "inc add 5", "f2 3 f2 5", "q", "a1", "(add 3)", "(inc inc)",
	"[+ 1]", "[-_]", "[!_]", "[<<] 1", "[* 2,] 1", "[,] 1", "io1", "pb 1", "n", "mx", "(f3 !_ 2) 1", "(f3 !_ 2)", "f3 !_", "add !_",
	"add _ 10", "add _", "f3 _ 2", "inc !_", "add 1 !_", "i", "!_", "i inc", "!_ inc", "i 5", "add _ inc", "io1 inc", "go", "go inc",
	"uu 5", "5 add 3", "1 2 f2", "inc 5 !_ 6", "inc 1 _ 2", "inc []~", "add vs~", "inc 5 !_", "_", "_ inc", "5 _", "@f30", "~_",
];
const CTX30 = [
	["根", (x) => [x]],
	["括りに当てる", (x) => [`(${x}) 5`]],
	["括りを合成に置く", (x) => [`double (${x}) 5`]],
	["名前の右辺", (x) => [`w30 : ${x}`, "w30 5"]],
	["名前の右辺を根に", (x) => [`w30 : ${x}`, "w30"]],
	["値の上", (x) => [`5 ${x}`]],
	["比べの被演算子", (x) => [`${x} == 6`]],
	["手続きの行", (x) => ["t30 : y ?", `\t${x}`, "\ty", "", "t30 1"]],
	["`$[…]` の中身", (x) => [`$[${x}]`]],
	["本体の根", (x) => [`t31 : y ? ${x}`]],
	["括りの後ろに関数と値", (x) => [`(${x}) inc 5`]],
];
// X を1行の括りに置く文脈（上の注の `(!_ _)`）と、そこで括りの点なしの形になる X。
const BRACKET_CTX30 = new Set(["括りに当てる", "括りを合成に置く", "`$[…]` の中身", "括りの後ろに関数と値"]);
const PF_FORM30 = new Set(["!_"]);
const asBracket30 = (t) => t.split("(").join("[").split(")").join("]");
// 答えの綴り。from を to に読み替える（書いた括り・遅らせた本体の綴りに見える `_` の違いを消す。書いた `(X)` は木では `[X]`）。
const ans30 = (lines, from = null, to = null) => {
	let o;
	try {
		const r = resolve(src([...DEFS30, ...lines]));
		o = `通る ${r.trees.map((t) => `${show(t)} : ${kindOf(t)}`).join(" ⏎ ")} ／ ${diagKeys(r, true).join(" ")}`;
	} catch (e) {
		return e.reason ? `断り ${e.reason} ${e.gate || ""}` : `例外 ${e.name}: ${e.message}`;
	}
	return from === null ? o : o.split(from).join(to).split(asBracket30(from)).join(asBracket30(to));
};
law("30 末尾の書いた `_` を付けた並びと付けない並びは、どこでも同じ木・同じ種類・同じ知らせ（R28）：C[X _] と C[X]、後ろが関数の C[X _ G] と C[X G]", () => {
	const problems = [];
	const count = { 比べた組: 0, 通る: 0, 断る: 0, "括った `!_ _` は恒等射の i を括った物と同じ（R108）": 0 };
	const tail = (s) => (s.length > 400 ? `…${s.slice(-400)}` : s);
	for (const x of X30) {
		for (const [cname, c] of CTX30) {
			// 2026-10-28 の R108（§5 Q74 (c) を閉じた）から、1行の括りの `!_ _` は書いた項どおり恒等射（否定の点なしは裸の `[!_]` だけ）。末尾の `_` を消した `(!_)` は
			// 否定の点なしで別の関数なので、`_` を消した綴りとは比べず、恒等射の名前 i を括った綴りと比べる（前は G7 で比べの外）。
			if (PF_FORM30.has(x) && BRACKET_CTX30.has(cname)) {
				const a = ans30(c("i"));
				const b = ans30(c(`${x} _`), `${x} _`, "i");
				count["括った `!_ _` は恒等射の i を括った物と同じ（R108）"]++;
				if (a !== b) problems.push(`${cname} ${x} _：恒等射の i を括った物と同じのはず：${tail(b)}  ⇔  i：${tail(a)}`);
				continue;
			}
			const a = ans30(c(x));
			const b = ans30(c(`${x} _`), `${x} _`, x);
			count.比べた組++;
			if (a !== b) problems.push(`${cname} ${x}：${tail(a)}  ⇔  ${x} _：${tail(b)}`);
			else count[a.startsWith("通る") ? "通る" : "断る"]++;
		}
		for (const g of ["inc", "add"]) {
			for (const [cname, c] of CTX30.slice(0, 4)) {
				const a = ans30(c(`${x} ${g}`));
				const b = ans30(c(`${x} _ ${g}`), `${x} _ ${g}`, `${x} ${g}`);
				count.比べた組++;
				if (a !== b) problems.push(`後ろが関数 ${cname} ${x} ${g}：${tail(a)}  ⇔  ${x} _ ${g}：${tail(b)}`);
				else count[a.startsWith("通る") ? "通る" : "断る"]++;
			}
		}
	}
	for (const [k, v] of Object.entries(count)) if (!v) problems.push(`「${k}」の組が無い（法則がその枝を見ていない）`);
	return { problems, note: Object.entries(count).map(([k, v]) => `${k} ${v}`).join("・") };
});

// ---------------------------------------------------------------------------
// 法則31：空の流れと書いた `_` は、同じ位置なら同じ答え（参照の口が流れ1つを丸ごと受ける所を除く。R83・R84・R95、2026-10-27）
// ---------------------------------------------------------------------------
//
// 比べる綴り：位置 X[E] の E に、長さ 0 の流れ（`[]~`・`e0 : []` の `e0~`・書いた `_~`・`[[]]~`、2026-10-27 の確かめの直しから `_` と分かる値を撒いた `[_]~`・
// `un : _` の `un~`）を置いた物と、書いた `_` を置いた物。位置は、値の口（素の関数の口・
// 穴・関数を挟んで値が続く所）・既定値のある関数の口・括りの受ける並びの中（括りの関数の最後の括りに、ほかの要素と一緒に入る所・最後でない括り）・合成の中・
// 畳む2項の点なしの実引数・値の隣。文脈で包む（根・括って後ろに値・名前・括り・値の上・関数の本体・比べの辺・値の口の括り）。
// 2026-10-27 の片6 の R95（§5 Q75 (b) の点なしの所の答え：U〔答え〕[2026-10-27 09:25 df447414]「4. それは点無しの関数が残るはず。」）から、点なしの可変長の口（貪欲な単項・
// 写像・畳む2項の点なし・恒等射と、それを頭にした合成）が流れ1つを受ける位置も比べに入れた（片5 は R51 の丸ごとで比べの外、錨で `[* 2,] []~` が A を見ていた）。
// 恒等射の位置は、文脈の比べの辺（`!_ E == 1`、R44 の G7）と括り（`[!_ E]`、§5 Q74 (c) の G7）で、綴りで並びの形を見る門も同じに数えることを見る。
// 何を同じと見るか：通れば全部の行の木と種類と知らせ（名前まで）、断れば門。E の綴りは木と知らせの中で `_` に読み替えて比べる（ソースの違いは E の綴りだけなので、
// 読み替えで隠れるのはその綴りだけ）。期待値は書かない。
// なぜ同じか：U〔答え〕[2026-10-26 11:35 c8ccdd69]「…[]~ = _~ = _ / [] = _ / をきちんと念頭に」（U [10:18]「[]~ = _~ だと思っていいとなると。 _~ は展開しても _
// として考え直していいわけ。」）。展開は List から並びへのモノイド準同型なので単位を単位へ送る（主の Claude の読み、R）。単位は着いた口で読む（R83）。
// 比べの外（錨で見る）：参照の口が流れ1つだけを丸ごと受ける所（括りの関数の最後の括りの `fq []~` は R64 で `fq []`（R90 で A）、書いた `fq _` は R28 で fq のまま。
// R34 の穴の関数の最後の括りの `(f3 !_ 2) 1 []~` も元の流れ。X31 にこの位置は置いていない）。§5 Q75 (b) の参照の口の割れで、「どの口でも同じ」とは言えない
// （2026-10-27 の確かめの直しで題を狭め、片6 の R95 で点なしの口を比べに戻した）。
const DEFS31 = [
	INC, "double : x ? x * 2", "add : x y ? x + y", "sub : x y ? x - y", "f2 : x y ? x - y", "f3 : a b c ? a + b + c", "fq : [a b c] ? a", "pb2 : [a] [b] ? a", "mx : a [b] ? a",
	"e0 : []", "un : _", "i : !_", "go :", "\t\tys", "\t\tzs : 3", "\t? ys", "",
];
const UNITS31 = toUnits(DEFS31);
const X31 = [
	(e) => `inc ${e} 5`, (e) => `add ${e} 3`, (e) => `sub ${e} 3`, (e) => `f2 3 ${e}`, (e) => `add ${e}`, (e) => `inc ${e}`, (e) => `f3 ${e} 1 2`, (e) => `f3 1 ${e} 2`, (e) => `f3 1 2 ${e}`,
	(e) => `f2 ${e} inc 5`, (e) => `add 1 ${e} 3`, (e) => `inc 5 ${e} 6`,
	(e) => `go 1 ${e}`, (e) => `go ${e} 2`, (e) => `go ${e}`,
	(e) => `fq ${e} 1 2`, (e) => `fq 1 ${e} 2`, (e) => `fq 1 2 ${e}`, (e) => `pb2 ${e} 1`, (e) => `mx 1 ${e} 2`,
	(e) => `inc double ${e}`, (e) => `inc add ${e} 3`, (e) => `add inc ${e} 5`, (e) => `[+] 1 ${e} 3`,
	(e) => `5 ${e}`, (e) => `${e} 5`, (e) => `1 ${e} 2`, (e) => `5 ${e} inc`,
	// 2026-10-27 の片6 の R95：点なしの可変長の口（流れ1つを受ける所と、後ろに値や関数が続く所）
	(e) => `[* 2,] ${e}`, (e) => `[inc,] ${e}`, (e) => `[+] ${e}`, (e) => `[+] inc ${e}`, (e) => `[* 2,] inc ${e}`, (e) => `[-_,] ${e}`,
	(e) => `i ${e}`, (e) => `!_ ${e}`, (e) => `i ${e} inc`, (e) => `i i ${e}`, (e) => `inc i ${e}`, (e) => `[* 2,] ${e} 5`, (e) => `5 [* 2,] ${e}`,
];
const CTX31 = [
	["根", (x) => [x]], ["括って後ろに値", (x) => [`(${x}) 7`]], ["名前", (x) => [`w : ${x}`, "w"]], ["括り", (x) => [`[${x}]`]], ["値の上", (x) => [`5 ${x}`]],
	["本体", (x) => [`t : y ? ${x}`, "t 1"]], ["比べの辺", (x) => [`${x} == 1`]], ["値の口の括り", (x) => [`inc (${x})`]],
];
const EMPTY31 = ["[]~", "e0~", "_~", "[[]]~", "[_]~", "un~"];
const ans31 = (lines, from = null) => {
	const s = lines.join("\n");
	let o;
	try {
		const r = resolve(src([...usedDefs(UNITS31, s), ...lines]));
		// 比べるのは書いた行の木だけ（定義の行は、使う名前の定義だけを並べるので両側で違う：`e0~` の側にだけ e0 の定義がある）
		o = `通る ${r.trees.slice(-lines.length).map((t) => `${show(t)} : ${kindOf(t)}`).join(" ⏎ ")} ／ ${diagKeys(r, true).join(" ")}`;
	} catch (e) {
		return e.reason ? `断り ${e.reason} ${e.gate || ""}` : `例外 ${e.name}: ${e.message}`;
	}
	return from === null ? o : o.split(from).join("_");
};
law("31 空の流れと書いた `_` は、同じ位置なら同じ答え（参照の口が流れ1つを丸ごと受ける所を除く。R83・R84・R95）：C[X[[]~]]・C[X[e0~]]・C[X[_~]]・C[X[un~]] と C[X[_]]", () => {
	const problems = [];
	const count = { 比べた組: 0, 通る: 0, 断る: 0, 錨: 0 };
	const tail = (s) => (s.length > 400 ? `…${s.slice(-400)}` : s);
	for (const x of X31) {
		for (const [cname, c] of CTX31) {
			const b = ans31(c(x("_")));
			if (b.startsWith("例外")) problems.push(`${cname} ${x("_")}：${b}`);
			for (const e of EMPTY31) {
				const a = ans31(c(x(e)), e);
				count.比べた組++;
				if (a !== b) problems.push(`${cname} ${x(e)}：${tail(a)}  ⇔  ${x("_")}：${tail(b)}`);
				else count[a.startsWith("通る") ? "通る" : "断る"]++;
			}
		}
	}
	// 錨（比べの外）：参照の口が流れ1つだけを丸ごと受ける所は、今のまま R64 の丸ごと（書いた `_` の R28 と答えが違う。§5 Q75 (b) の参照の口）。片5 の錨の
	// `[* 2,] []~`（R51 の丸ごとで A）は、片6 の R95 で `[* 2,] _` と同じになり、上の比べに入れた。
	const anchor = (lines, want) => {
		count.錨++;
		const a = ans31(lines);
		if (!a.startsWith(want)) problems.push(`錨 ${lines.join(" ⏎ ")}：${tail(a)}（${want} のはず）`);
	};
	anchor(["fq []~"], "通る (apply fq []~) : A");
	anchor(["fq _"], "通る (unit fq) : A");
	anchor(["(f3 !_ 2) 1 []~"], "通る (apply [f3 !_ 2] (construct 1 []~)) : 未知");
	anchor(["(f3 !_ 2) 1 _"], "通る (unit (apply [f3 !_ 2] 1)) : A");
	for (const [k, v] of Object.entries(count)) if (!v) problems.push(`「${k}」の組が無い（法則がその枝を見ていない）`);
	return { problems, note: Object.entries(count).map(([k, v]) => `${k} ${v}`).join("・") };
});

// ---------------------------------------------------------------------------
// 法則32：値の演算子の被演算子に残った丸ごとの関数は、ほかの評価する所と同じ答え（R87、2026-10-27）
// ---------------------------------------------------------------------------
//
// 比べる綴り：丸ごとの関数 F を値の演算子 op（段12〜16・19〜22）の被演算子に置いた `F op 1`・`1 op F` と、比べの辺（R76 の評価する所）に置いた `F == 1`・`1 == F`。
// 文脈で包む（根・括って後ろに値・値の上・関数の本体・括り）。値の印（前置 `-`・`!!`）の核の F は、中置の `0 - F` と種類と知らせで比べる（葉の綴りが違う）。
// 何を同じと見るか：通れば全部の行の木（演算子の綴りを `==` に読み替える）と種類と知らせ（名前まで）、断れば門。期待値は書かない。
// なぜ同じか：主の Claude の傾き「Q73 | 値の演算子の被演算子も評価する所にするか | 広げる」（2026-10-26 11:57 の表の A。利用者は A の行に異議を言わず、傾きで受けた、R）と、
// U [2026-10-25 22:11 e20e5341]「x + sum _ = x + sum = x + _ だから x だけが返る…と言いたいな。」。評価する所に残った丸ごとの関数は `_`（R42・R48・R76）。
const DEFS32 = [INC, "add : x y ? x + y", "i : !_"];
// `$inc`（関数を指す番地、R62 の G7）と `!_`（中置の被演算子の穴、G7）は、評価する所でも今のまま断る組（比べの「断る」の枝）。
const F32 = ["inc", "(add 1)", "[x ? x]", "i", "(inc inc)", "add", "[+ 1]", "$inc", "!_"];
const OPS32 = ["+", "-", "*", "/", "<", ">=", "<<", "~"];
// 値の上は括って置く（`5 inc + 1` は中置が空白より強く結ぶので `5 (inc + 1)`、`5 inc == 1` は `==` が空白より緩く結ぶので `(5 inc) == 1` で、結び方が違う）。
const CTX32 = [["根", (x) => [x]], ["括って後ろに値", (x) => [`(${x}) 7`]], ["値の上", (x) => [`5 (${x})`]], ["本体", (x) => [`t : y ? ${x}`, "t 1"]], ["括り", (x) => [`[${x}]`]]];
const ans32 = (lines) => {
	try {
		const r = resolve(src([...DEFS32, ...lines]));
		// 比べるのは書いた行の木だけ（定義の行の本体の中置を、演算子の読み替えに巻き込まない）
		return `通る ${r.trees.slice(-lines.length).map((t) => `${show(t)} : ${kindOf(t)}`).join(" ⏎ ")} ／ ${diagKeys(r, true).join(" ")}`;
	} catch (e) {
		return e.reason ? `断り ${e.reason} ${e.gate || ""}` : `例外 ${e.name}: ${e.message}`;
	}
};
const kindDiag32 = (lines) => {
	try {
		const r = resolve(src([...DEFS32, ...lines]));
		const t = r.trees[r.trees.length - 1];
		return `通る ${kindOf(t)} ／ ${diagKeys(r, true).join(" ")}`;
	} catch (e) {
		return e.reason ? `断り ${e.reason} ${e.gate || ""}` : `例外 ${e.name}: ${e.message}`;
	}
};
law("32 値の演算子の被演算子に残った丸ごとの関数は、ほかの評価する所と同じ答え（R87）：C[F op 1]・C[1 op F] と C[F == 1]・C[1 == F]", () => {
	const problems = [];
	const count = { 比べた組: 0, 通る: 0, 断る: 0, 値の印の組: 0 };
	for (const f of F32) {
		for (const [cname, c] of CTX32) {
			for (const [mk, cmp] of [[(op) => `${f} ${op} 1`, `${f} == 1`], [(op) => `1 ${op} ${f}`, `1 == ${f}`]]) {
				const b = ans32(c(cmp));
				for (const op of OPS32) {
					// 演算子の綴りだけを `==` に読み替える（節の頭 `(op ` と、括りの葉に書いたままの ` op `）
					const a = ans32(c(mk(op))).split(`(${op} `).join("(== ").split(` ${op} `).join(" == ");
					count.比べた組++;
					if (a !== b) problems.push(`${cname} ${mk(op)}：${a}  ⇔  ${cmp}：${b}`);
					else count[a.startsWith("通る") ? "通る" : "断る"]++;
				}
			}
		}
		for (const mark of ["-", "!!"]) {
			if (!/^[a-z]/.test(f)) continue; // 値の印は核に係る（括りの核の `-(add 1)` は括りの値の印で、別の形。`$`・`!_` は印の組み合わせで別の行）
			const a = kindDiag32([`${mark}${f}`]);
			const b = kindDiag32([`0 - ${f}`]);
			count.値の印の組++;
			if (a !== b) problems.push(`値の印 ${mark}${f}：${a}  ⇔  0 - ${f}：${b}`);
		}
	}
	for (const [k, v] of Object.entries(count)) if (!v) problems.push(`「${k}」の組が無い（法則がその枝を見ていない）`);
	return { problems, note: Object.entries(count).map(([k, v]) => `${k} ${v}`).join("・") };
});

// ---------------------------------------------------------------------------
// 法則33：番地の組は、どちらも番地と言える物の中で、左右と包みに依らず同じ答え（R92、2026-10-27）
// ---------------------------------------------------------------------------
//
// 比べる綴り：番地の点 P（`$vs`・`p1 : $vs` の p1・ずらした点 `($vs + 0x10)`）・差 D（`($vs - $five)`・`d1 : $vs - $five` の d1）・字面 H（`0x10`・`h1 : 0x10` の h1）の
// `+` の組 `L + R` と左右を入れ替えた `R + L`、`-` と `+` の組の、括り1つ `(L op R)` と名前 `w : L op R` ⏎ `w` で包んだ物。
// 何を同じと見るか：通るか断るか（門）と、答えの顔（点か差か）。顔は後ろに置いた比べで見る（`(X) == $vs` が通れば点、`(X) == ($vs - $five)` が通れば差）。
// 期待値は書かない（左右と包みを互いに比べる）。
// なぜ同じか：U〔答え〕[2026-10-26 23:35 c8ccdd69]「アドレス同士の計算は、きちんとアドレス値だと言いえるものだけに限定する原則が重要！」。位置は差の群が働く
// torsor で、差の群は可換なので作用を左から書いても同じ点（主の Claude の読み、R）。差の隣の `0x…` は差（R）。名前は右辺を指し（`:` はメタ）、括り1つは中身と同じ。
// 見ない物（2026-10-27 の確かめの直しで書いた）：`0x…` の顔の読みそのもの。顔は R62 のとおり置かれた所（隣）で決め、両側に同じ読みを置いているので、
// 「`差 + 0x…` の `0x…` を点と読めば点、差と読めば差」という読みの割れは、この法則では落ちない（§5 Q66 の見直す所）。点から引く `$x - 0x10` も R62 から
// 同じ作りで、両方の読みが型として成り立つ（点 − 点で差、点 − 差で点）のを置いた所で差に決めている。
// → 2026-10-27 の片7 の R96（U〔答え〕[2026-10-27 09:53 58a809c9]「それでいい。算術の中の `0x…` は差と読める所ではいつも差（…）、点としか読めない所は断る。…」）で、
// 算術の中の `0x…` を差に決める読みは答えになった（`$x - 0x10` も点のまま）。字面どうしの組も比べに入れた（同じ日の確かめの直しから、字面どうしの和は点か差の
// 隣で字面の和として差と読み、和そのものは字面と同じ中身の見えない値。包んでも左右を入れ替えても同じ答えなのを見る）。
const DEFS33 = ["vs : 1 , 2 , 3", "five : 5", "p1 : $vs", "d1 : $vs - $five", "h1 : 0x10"];
const P33 = ["$vs", "p1", "($vs + 0x10)"];
const D33 = ["($vs - $five)", "d1"];
const H33 = ["0x10", "h1"];
const ok33 = (lines) => {
	try {
		resolve(src([...DEFS33, ...lines]));
		return "通る";
	} catch (e) {
		return e.reason ? `断り ${e.gate || e.reason}` : `例外 ${e.name}: ${e.message}`;
	}
};
// 答えと顔：X の通るか（門）と、X が点か差か（後ろに置いた比べで見る）。
const face33 = (pre, x) => {
	const self = ok33([...pre, x]);
	if (self !== "通る") return self;
	const pt = ok33([...pre, `(${x}) == $vs`]) === "通る";
	const df = ok33([...pre, `(${x}) == ($vs - $five)`]) === "通る";
	return `通る 顔 ${pt ? "点" : df ? "差" : "どちらでもない"}`;
};
law("33 番地の組は、どちらも番地と言える物の中で、左右と包みに依らず同じ答え（R92）：L + R と R + L、括りと名前で包んでも", () => {
	const problems = [];
	const count = { 左右の組: 0, 包みの組: 0, 通る: 0, 断る: 0 };
	const all = [...P33.map((x) => ["点", x]), ...D33.map((x) => ["差", x]), ...H33.map((x) => ["字面", x])];
	// 2026-10-27 の片7 の R96 から、字面どうしの組（`0x10 + h1`）も比べる（前は番地の顔の無い組で、今までの読みとして比べの外だった。和は字面の和で、
	// 顔は「どちらでもない」：比べの相手では字面の和を見ない、hexFace）。
	for (const [lk, l] of all) {
		for (const [rk, r] of all) {
			const lr = face33([], `${l} + ${r}`);
			const rl = face33([], `${r} + ${l}`);
			count.左右の組++;
			if (lr !== rl) problems.push(`左右 ${lk} ${l} + ${rk} ${r}：${lr}  ⇔  ${r} + ${l}：${rl}`);
			else count[lr.startsWith("通る") ? "通る" : "断る"]++;
			for (const op of ["+", "-"]) {
				const base = face33([], `${l} ${op} ${r}`);
				const wrapped = [face33([], `(${l} ${op} ${r})`), face33([`w : ${l} ${op} ${r}`], "w")];
				for (const w of wrapped) {
					count.包みの組++;
					if (w !== base) problems.push(`包み ${l} ${op} ${r}：${base}  ⇔  ${w}`);
				}
			}
		}
	}
	for (const [k, v] of Object.entries(count)) if (!v) problems.push(`「${k}」の組が無い（法則がその枝を見ていない）`);
	return { problems, note: Object.entries(count).map(([k, v]) => `${k} ${v}`).join("・") };
});

// ---------------------------------------------------------------------------
// 法則34：値の口に書いた `[]` は、同じ位置に書いた `_` と同じ答え（R94、2026-10-27 の片6）
// ---------------------------------------------------------------------------
//
// 比べる綴り：位置 X[E] の E に、書いた `[]` と、中身が詰まって `[]` になる書いた括り（`[[]]`・`~[]`・`[_]`・`~_`）を置いた物と、書いた `_` を置いた物。位置は値の口：素の関数の口
// （穴・カリー化・末尾・関数を挟んで値が続く所・穴 `!_` と一緒の所・R34 で余りが前の穴に入る所）・括りの関数の裸の仮引数・単項と畳まない2項の点なしの口・既定値のある関数の
// 裸の仮引数と既定値のある口・合成の中で値の口に入る所・穴の関数の裸の口・値の後ろに積まれた頭。文脈で包む（根・括って後ろに値・名前・括り・値の上・関数の本体・
// 比べの辺・値の口の括り・`$[…]`）。
// 何を同じと見るか：通れば全部の行の木と種類と知らせ（名前まで）と、木の葉の種類の並び（既定値のある口に着いた所は、書いた綴りのまま既定値の葉になるので、綴りの読み替え
