		const r = resolve(src([...usedDefs(UNITS34, s), ...lines]));
		o = `通る ${r.trees
			.slice(-lines.length)
			.map((t) => `${show(t)} : ${kindOf(t)} <${leafCats34(t).join(",")}>`)
			.join(" ⏎ ")} ／ ${diagKeys(r, true).join(" ")}`;
