	anchor(["inc e0"], "通る (unit inc) : A");
	anchor(["inc un"], "通る (unit inc) : A");
	anchor(["pb2 [] 1"], "通る (apply pb2 (construct [] 1)) : A");
	anchor(["fq []"], "通る (apply fq []) : A");
	anchor(["(f3 !_ 2) 1 []"], "通る (unit (apply [f3 !_ 2] (construct 1 []))) : A");
