	// `(apply [go !_ 2] [])`）。穴の口の比べは法則40 が見るので、ここは錨の答えを直した。
	anchor(["(go !_ 2) []"], "通る (unit [go !_ 2]) : A");
	anchor(["inc [1 2]"], "通る (apply inc [1 2]) : A");
