	anchor(["mx _ [] inc"], "通る (unit (compose mx inc)) : A");
	anchor(["(f3 !_ 2) _ []"], "通る (unit [f3 !_ 2]) : A");
	anchor(["(add 3) _ [] []"], "通る (unit [add 3]) : A");
	anchor(["inc _ _ []"], "通る (unit inc) : A");
	for (const [k, v] of Object.entries(count)) if (!v) problems.push(`「${k}」の組が無い（法則がその枝を見ていない）`);
